INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 1, 'ما الذي يدرسه علم الأوبئة', 'What epidemiology studies', '[''ذكر التعريف العلمي لعلم الوبائيات وشرح التوزع والمحددات والحالات أو الأحداث المرتبطة بالصحة والجماعات السكانية المحددة وتطبيق الدراسة.'', ''التمييز بين الأسئلة السكانية وأسئلة الرعاية السريرية للفرد.'', ''شرح أهمية توحيد تعريف الحالة، وأن تصنيفات مشتبهة ومحتملة ومؤكدة تختلف باختلاف المرض وبروتوكول الترصد.'']', '[''State the standard epidemiology definition and explain distribution, determinants, health-related states or events, specified populations, and application.'', ''Distinguish population-level questions from individual clinical questions.'', ''Explain why case definitions are standardized and why suspected, probable and confirmed categories are disease- and protocol-specific.'']', 'علم الوبائيات هو دراسة توزّع الحالات أو الأحداث المرتبطة بالصحة ومحدداتها في جماعات سكانية محددة، وتطبيق هذه الدراسة للوقاية من المشكلات الصحية والسيطرة عليها. يصف التوزّع نمط وقوع الأحداث وتواترها بحسب الشخص والمكان والزمان. وتشمل المحددات العوامل البيولوجية والكيميائية والفيزيائية والاجتماعية والثقافية والاقتصادية والجينية والسلوكية التي تؤثر في الصحة؛ لذلك لا يقتصر علم الوبائيات على العوامل المعدية أو سلوك الفرد. وتشمل الحالات والأحداث المرتبطة بالصحة الأمراض والإصابات وأسباب الوفاة والسلوكيات الصحية والحالات الصحية الإيجابية والاستجابة للتدابير الوقائية وتقديم الخدمات الصحية واستخدامها. يسأل الطبيب السريري غالبا عما يحدث لمريض بعينه وكيفية تدبير حالته، بينما يدرس عالم الوبائيات أنماط الأحداث الصحية في جماعة سكانية محددة والعوامل التي قد تفسرها وكيفية استخدام الدليل لتوجيه إجراءات سكانية. والمنظوران متكاملان. قبل عدّ الحالات، يستخدم المحققون تعريفا موحدا للحالة؛ ويحدد عادة المعايير السريرية أو المخبرية، ويحدد أثناء تقصي الفاشية قيود الشخص والمكان والزمان عند الحاجة. أما المعايير الدقيقة وتسميات مشتبهة ومحتملة ومؤكدة فتختلف باختلاف المرض وبروتوكول الترصد الوطني أو الدولي المعمول به، وليست مراحل عالمية ذات معنى ثابت واحد. المرجع العلمي: منظمة الصحة العالمية، بونيتا وآخرون، علم الوبائيات الأساسي، الطبعة الثانية، الفصل الأول؛ ومراكز مكافحة الأمراض والوقاية منها، مبادئ علم الوبائيات، الدرس الأول، القسم الخامس.', 'Epidemiology is the study of the distribution and determinants of health-related states or events in specified populations, and the application of this study to the prevention and control of health problems. Distribution describes the frequency and pattern of events by person, place and time. Determinants include biological, chemical, physical, social, cultural, economic, genetic and behavioural factors that influence health; they are not limited to infectious agents or individual behaviour. Health-related states and events include diseases, injuries, causes of death, health behaviours, positive health states, responses to preventive measures, and the provision and use of health services. A clinician commonly asks what is happening to an individual patient and how to manage that patient; an epidemiologist asks how health events are patterned across a defined population, what factors may explain those patterns, and how evidence can guide population action. These perspectives complement one another. Before cases are counted, investigators use a consistent case definition. It normally specifies clinical or laboratory criteria and, especially during an outbreak investigation, relevant person, place and time limits. The exact criteria and the labels suspected, probable and confirmed are condition-specific and must follow the applicable national or WHO surveillance protocol; they are not universal stages with one fixed meaning. Reference basis: WHO, Bonita et al., Basic Epidemiology, 2nd ed., Chapter 1; CDC, Principles of Epidemiology, Lesson 1, Section 5.', '{"exampleEn": "Field case — A clinic reports “many diarrhoea cases.” For this fictional training exercise, the team first agrees a working clinical and epidemiological case definition: a person with three or more loose stools in 24 hours, resident in the defined town, with onset between 1 and 7 June. The team records laboratory findings and possible exposures separately rather than making an exposure (such as eating at the wedding) part of the case definition, because doing so would prevent an unbiased comparison of exposed and unexposed people. The team then applies the specific suspected, probable and confirmed classification in the relevant national diarrhoeal-disease surveillance protocol. A phone alert is a notification requiring verification, not automatically a case category. This prevents rumours, notifications, and cases meeting different levels of evidence from being combined into one misleading total. The dates, clinical threshold and location here are illustrative only, not a national case definition.", "exampleAr": "حالة ميدانية — تبلغ عيادة عن «حالات إسهال كثيرة». في هذا التمرين التدريبي الافتراضي، يتفق الفريق أولا على تعريف عملي للحالة يجمع المعايير السريرية والوبائية: شخص لديه ثلاث مرات براز رخو أو أكثر خلال 24 ساعة، ويقيم في البلدة المحددة، وبدأت أعراضه بين 1 و7 يونيو. ويسجل الفريق نتائج المختبر والتعرضات المحتملة كلٌّ على حدة، بدلا من إدخال التعرض (مثل تناول الطعام في وليمة الزفاف) ضمن تعريف الحالة؛ لأن ذلك سيمنع إجراء مقارنة غير متحيزة بين من تعرضوا ومن لم يتعرضوا. بعد ذلك يطبق الفريق تصنيفات مشتبهة ومحتملة ومؤكدة الواردة في بروتوكول الترصد الوطني المعمول به للمرض الإسهالي المعني. والبلاغ الهاتفي تنبيه يستلزم التحقق، وليس تلقائيا فئة من فئات الحالات. يمنع ذلك دمج الشائعات والبلاغات والحالات ذات مستويات الدليل المختلفة في مجموع واحد مضلل. والتواريخ والحد السريري والموقع هنا أمثلة تعليمية وليست تعريفا وطنيا معتمدا للحالة.", "fieldEn": "Before you recommend anything, ask: who is at risk, over what time, and who was counted? Write the denominator next to every count, and write the case definition at the top of every line list.", "fieldAr": "قبل أن توصي بأي شيء، اسأل: من المعرض للخطر، وخلال أي زمن، ومن تم عده؟ اكتب المقام بجانب كل عدد، واكتب تعريف الحالة أعلى كل قائمة حالات.", "calcTitleEn": "Worked calculation — cumulative incidence (risk) over one month", "calcTitleAr": "حساب محلول — الحدوث التراكمي (الخطر) خلال شهر واحد", "calcStepsEn": ["Step 1 — Count incident cases: 60 people who newly developed the outcome during the month.", "Step 2 — Use the population initially at risk: 12,000 people who did not already have the outcome at the start of the month and were eligible to become cases.", "Step 3 — Cumulative incidence (risk) = new cases ÷ population at risk at the start = 60 ÷ 12,000 = 0.005.", "Step 4 — Express as a percentage or scaled proportion: 0.005 × 100 = 0.5%, or 0.005 × 1,000 = 5 per 1,000 over the one-month period.", "This is a risk over a specified period, not an incidence rate: no person-time denominator is used. The simple calculation assumes the population denominator and case ascertainment are appropriate for the period."], "calcStepsAr": ["الخطوة 1 — عدّ الحالات الجديدة: 60 شخصا ظهرت لديهم النتيجة الصحية لأول مرة خلال الشهر.", "الخطوة 2 — استخدم السكان المعرضين للخطر عند البداية: 12000 شخص لم تكن لديهم النتيجة عند بداية الشهر وكانوا مؤهلين لأن يصبحوا حالات.", "الخطوة 3 — الحدوث التراكمي (الخطر) = الحالات الجديدة ÷ السكان المعرضين للخطر عند البداية = 60 ÷ 12000 = 0.005.", "الخطوة 4 — عبّر عنه كنسبة مئوية أو نسبة مضروبة: 0.005 × 100 = 0.5%، أو 0.005 × 1000 = 5 لكل 1000 خلال فترة الشهر.", "هذا خطر خلال فترة محددة وليس معدل حدوث؛ إذ لم يُستخدم مقام زمن الأشخاص. ويفترض الحساب أن مقام السكان واكتشاف الحالات مناسبان للفترة."], "calcResultEn": "Result: cumulative incidence = 5 per 1,000 people over the one-month period (0.5%). If the same 60 incident cases occurred among 600 people initially at risk over the same period, the cumulative incidence would be 100 per 1,000 (10%). Always state the period; do not label this a person-time rate.", "calcResultAr": "النتيجة: الحدوث التراكمي = 5 لكل 1000 شخص خلال فترة الشهر (0.5%). وإذا حدثت الحالات الجديدة الستون نفسها بين 600 شخص كانوا معرضين للخطر عند البداية وخلال الفترة نفسها، فسيكون الحدوث التراكمي 100 لكل 1000 (10%). اذكر الفترة دائما، ولا تسمِّ هذا المقياس معدلا قائما على زمن الأشخاص.", "terms": [{"termEn": "Distribution", "termAr": "التوزع", "defEn": "Who, where and when illness occurs in a population.", "defAr": "من وأين ومتى يحدث المرض بين السكان."}, {"termEn": "Determinants", "termAr": "المحددات", "defEn": "Factors that increase or decrease the chance of illness.", "defAr": "العوامل التي تزيد أو تقلل احتمال المرض."}, {"termEn": "Population at risk", "termAr": "السكان المعرضون للخطر", "defEn": "People who could develop the outcome during the study period.", "defAr": "الأشخاص الذين يمكن أن يصابوا بالنتيجة خلال فترة الدراسة."}, {"termEn": "Case definition", "termAr": "تعريف الحالة", "defEn": "A precise rule for who counts as a case.", "defAr": "قاعدة دقيقة لتحديد من يُحسب حالة."}], "objEn": ["State the standard epidemiology definition and explain distribution, determinants, health-related states or events, specified populations, and application.", "Distinguish population-level questions from individual clinical questions.", "Explain why case definitions are standardized and why suspected, probable and confirmed categories are disease- and protocol-specific."], "objAr": ["ذكر التعريف العلمي لعلم الوبائيات وشرح التوزع والمحددات والحالات أو الأحداث المرتبطة بالصحة والجماعات السكانية المحددة وتطبيق الدراسة.", "التمييز بين الأسئلة السكانية وأسئلة الرعاية السريرية للفرد.", "شرح أهمية توحيد تعريف الحالة، وأن تصنيفات مشتبهة ومحتملة ومؤكدة تختلف باختلاف المرض وبروتوكول الترصد."]}', '[{"qEn": "Epidemiology mainly studies…", "qAr": "علم الأوبئة يدرس أساسا…", "optsEn": ["Distribution and determinants of health in populations", "Illness in one patient only", "Hospital building design"], "optsAr": ["توزع الصحة ومحدداتها بين السكان", "مرض مريض واحد فقط", "تصميم بناء المستشفى"], "ans": 0, "explEn": "Distribution (who, where, when) plus determinants (why) is the core definition.", "explAr": "التوزع (من وأين ومتى) مع المحددات (لماذا) هو التعريف الأساسي."}, {"qEn": "A “probable” case usually means…", "qAr": "الحالة «المحتملة» تعني عادة…", "optsEn": ["Laboratory-confirmed", "Fits the clinical picture plus an epidemiological link, without lab confirmation", "Any rumour by phone"], "optsAr": ["مؤكدة مخبريا", "تنطبق عليها الصورة السريرية مع ارتباط وبائي، من دون تأكيد مخبري", "أي شائعة بالهاتف"], "ans": 1, "explEn": "Probable sits between suspected and confirmed: clinical fit + link, lab still missing.", "explAr": "المحتملة تقع بين المشتبهة والمؤكدة: صورة سريرية مناسبة + ارتباط، والمختبر ما زال غائبا."}, {"qEn": "60 cases in 12,000 people equals…", "qAr": "60 حالة بين 12000 شخص تساوي…", "optsEn": ["60 per 1,000", "0.5 per 100,000", "5 per 1,000"], "optsAr": ["60 لكل 1000", "0.5 لكل 100000", "5 لكل 1000"], "ans": 2, "explEn": "60 ÷ 12,000 = 0.005; × 1,000 = 5 per 1,000.", "explAr": "60 ÷ 12000 = 0.005؛ × 1000 = 5 لكل 1000."}, {"qEn": "Why write a case definition before counting?", "qAr": "لماذا نكتب تعريف الحالة قبل العدّ؟", "optsEn": ["So everyone counts the same thing and totals can be compared", "To make the report longer", "To avoid using a denominator"], "optsAr": ["حتى يعدّ الجميع نفس الشيء ويمكن مقارنة المجاميع", "لجعل التقرير أطول", "لتجنب استخدام المقام"], "ans": 0, "explEn": "A shared definition makes counting consistent and comparable.", "explAr": "التعريف المشترك يجعل العدّ متسقا وقابلا للمقارنة."}]' FROM courses WHERE course_code='B-101';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 2, 'الاستدلال الوصفي مقابل التحليلي', 'Descriptive vs analytic reasoning', '[''وصف نمط حسب الشخص والمكان والزمان.'', ''بناء مجموعة مقارنة عادلة بمقام واضح.'', ''تسمية الإرباك وتحيز الاختيار وتحيز المعلومات في مثال.'']', '[''Describe a pattern by person, place and time.'', ''Build a fair comparison group with a clear denominator.'', ''Name confounding, selection bias and information bias in an example.'']', 'الاستدلال الوصفي يسأل: ماذا حدث، ولمن، وأين، ومتى؟ والاستدلال التحليلي يسأل: هل مجموعة مختلفة عن أخرى، ولماذا؟ الوصف الجيد غالبا يكشف المقارنة الجديرة بالاختبار. والمقارنة من دون وصف قد تجيب عن السؤال الخطأ بدقة كبيرة. كل مقارنة تحليلية تحتاج شيئين: مجموعة مقارنة متشابهة إلا في التعرض، ومقاما لكل مجموعة. إذا اختلفت المجموعتان في العمر أو في طريقة اكتشافهما أو في طريقة قياس مرضهما، فقد يكون الفرق الذي تراه إرباكا أو تحيزا، لا أثر التعرض. الإرباك عامل ثالث مرتبط بالتعرض والنتيجة معا — مثلا العمر قد يربك مقارنة حيّين إذا كان أحدهما أكبر سنا بكثير. تحيز الاختيار يحدث عندما يعتمد دخول الدراسة على التعرض والنتيجة معا. وتحيز المعلومات يحدث عندما يُقاس التعرض أو النتيجة بشكل مختلف بين المجموعتين.', 'Descriptive reasoning asks: what happened, to whom, where and when? Analytic reasoning asks: is one group different from another, and why? A good description often reveals the comparison worth testing. A comparison without description can answer the wrong question with great precision. Every analytic comparison needs two things: a comparison group that is alike except for the exposure, and a denominator for each group. If the groups differ in age, in how they were found, or in how their illness was measured, the difference you see may be confounding or bias, not the exposure. Confounding is a third factor linked to both exposure and outcome — for example, age can confound a comparison of two neighbourhoods if one is much older. Selection bias happens when who gets into the study depends on both exposure and outcome. Information bias happens when exposure or outcome is measured differently between groups.', '{"exampleEn": "Field case — Cases cluster near one market on weekends. Description points to a place and time. The analytic question becomes: did people who visited that market have higher risk than people who did not? The team then checks: were market visitors older? Were they more likely to be tested? If testing was offered only at the market, information bias could inflate the market group. The team records age, testing route and visit history for both groups before calculating any risk ratio.", "exampleAr": "حالة ميدانية — تتجمع الحالات قرب سوق واحد في عطلة الأسبوع. الوصف يشير إلى مكان وزمان. ويصبح السؤال التحليلي: هل كان من زاروا ذلك السوق أكثر خطرا ممن لم يزوروه؟ ثم يتحقق الفريق: هل كان زوار السوق أكبر سنا؟ هل كان احتمال فحصهم أعلى؟ إذا قُدّم الفحص عند السوق فقط، فقد يضخّم تحيز المعلومات مجموعة السوق. يسجّل الفريق العمر وطريقة الفحص وتاريخ الزيارة للمجموعتين قبل حساب أي نسبة خطر.", "fieldEn": "Draw a simple table by person, place and time before you calculate RR or OR. If the pattern is unclear, the comparison is not ready.", "fieldAr": "ارسم جدولا بسيطا حسب الشخص والمكان والزمان قبل حساب الخطر النسبي أو نسبة الأرجحية. إذا كان النمط غير واضح، فالمقارنة ليست جاهزة.", "calcTitleEn": "Worked calculation — same count, different risk", "calcTitleAr": "حساب محلول — نفس العدد، خطر مختلف", "calcStepsEn": ["Step 1 — Group A: 20 cases among 200 guests. Risk = 20 ÷ 200 = 0.10 = 10%.", "Step 2 — Group B: 20 cases among 2,000 residents. Risk = 20 ÷ 2,000 = 0.01 = 1%.", "Step 3 — Compare: 10% ÷ 1% = 10. Group A had ten times the risk, even though the count (20) is identical.", "Step 4 — Check: are the groups alike in age and in how cases were found? If not, name the possible confounder or bias."], "calcStepsAr": ["الخطوة 1 — المجموعة أ: 20 حالة بين 200 ضيف. الخطر = 20 ÷ 200 = 0.10 = 10%.", "الخطوة 2 — المجموعة ب: 20 حالة بين 2000 مقيم. الخطر = 20 ÷ 2000 = 0.01 = 1%.", "الخطوة 3 — قارن: 10% ÷ 1% = 10. المجموعة أ خطرها عشرة أضعاف، رغم أن العدد (20) متطابق.", "الخطوة 4 — تحقق: هل المجموعتان متشابهتان في العمر وفي طريقة اكتشاف الحالات؟ إن لم تكونا، سمّ الإرباك أو التحيز المحتمل."], "calcResultEn": "Result: never compare counts without denominators. A comparison needs a denominator for every group.", "calcResultAr": "النتيجة: لا تقارن الأعداد أبدا من دون مقامات. كل مقارنة تحتاج مقاما لكل مجموعة.", "terms": [{"termEn": "Comparison group", "termAr": "مجموعة المقارنة", "defEn": "A group alike in other ways, used as the reference for the exposed group.", "defAr": "مجموعة متشابهة في النواحي الأخرى، تُستخدم مرجعا للمجموعة المعرضة."}, {"termEn": "Confounding", "termAr": "الإرباك", "defEn": "A third factor linked to exposure and outcome that distorts the comparison.", "defAr": "عامل ثالث مرتبط بالتعرض والنتيجة يشوّه المقارنة."}, {"termEn": "Selection bias", "termAr": "تحيز الاختيار", "defEn": "Distortion from how people enter or stay in the study.", "defAr": "تشويه ناتج عن طريقة دخول الناس إلى الدراسة أو بقائهم فيها."}, {"termEn": "Information bias", "termAr": "تحيز المعلومات", "defEn": "Distortion from measuring exposure or outcome differently between groups.", "defAr": "تشويه ناتج عن قياس التعرض أو النتيجة بشكل مختلف بين المجموعتين."}], "objEn": ["Describe a pattern by person, place and time.", "Build a fair comparison group with a clear denominator.", "Name confounding, selection bias and information bias in an example."], "objAr": ["وصف نمط حسب الشخص والمكان والزمان.", "بناء مجموعة مقارنة عادلة بمقام واضح.", "تسمية الإرباك وتحيز الاختيار وتحيز المعلومات في مثال."]}', '[{"qEn": "Descriptive epidemiology focuses on…", "qAr": "علم الأوبئة الوصفي يركز على…", "optsEn": ["Only laboratory tests", "Person, place and time", "Only treatment cost"], "optsAr": ["الاختبارات المخبرية فقط", "الشخص والمكان والزمان", "تكلفة العلاج فقط"], "ans": 1, "explEn": "Person, place and time is the descriptive frame.", "explAr": "الشخص والمكان والزمان هو إطار الوصف."}, {"qEn": "20 cases in 200 people vs 20 in 2,000 means…", "qAr": "20 حالة بين 200 شخص مقابل 20 بين 2000 تعني…", "optsEn": ["Equal risk", "No comparison is possible", "Ten times higher risk in the first group"], "optsAr": ["خطرا متساويا", "لا مقارنة ممكنة", "خطرا أعلى عشر مرات في المجموعة الأولى"], "ans": 2, "explEn": "10% vs 1% is a tenfold difference, despite equal counts.", "explAr": "10% مقابل 1% فرق عشرة أضعاف، رغم تساوي الأعداد."}, {"qEn": "Age distorting a comparison of two neighbourhoods is an example of…", "qAr": "تشويه العمر لمقارنة حيّين مثال على…", "optsEn": ["Confounding", "A case definition", "A denominator"], "optsAr": ["الإرباك", "تعريف الحالة", "المقام"], "ans": 0, "explEn": "Age is linked to both place and illness, so it can confound.", "explAr": "العمر مرتبط بالمكان والمرض معا، لذا قد يربك المقارنة."}, {"qEn": "Measuring illness differently in exposed and unexposed groups causes…", "qAr": "قياس المرض بشكل مختلف بين المعرضين وغير المعرضين يسبب…", "optsEn": ["A larger denominator", "Information bias", "A confirmed case"], "optsAr": ["مقاما أكبر", "تحيز المعلومات", "حالة مؤكدة"], "ans": 1, "explEn": "Unequal measurement is information bias.", "explAr": "القياس غير المتساوي هو تحيز المعلومات."}]' FROM courses WHERE course_code='B-101';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 3, 'من الملاحظة إلى الفعل', 'From observation to action', '[''تحويل ملاحظة إلى سؤال وصفي وخيار قرار.'', ''رسم وقراءة منحنى وبائي.'', ''حساب معدل الهجوم وتحديد ما الإجراء الذي يبرره الآن.'']', '[''Turn an observation into a descriptive question and a decision option.'', ''Draw and read an epidemic curve.'', ''Calculate an attack rate and state what action it justifies now.'']', 'لا تتحول الملاحظة إلى فعل إلا عندما ترتبط بقرار. من يقرر؟ وما الخيارات المتاحة؟ وماذا سيتغير إذا كان التقدير خاطئا؟ يسأل السؤال الوصفي: بين من وأين ومتى، كم شخصا مرض؟ يرسم المنحنى الوبائي الحالات بحسب تاريخ (أو وقت) بدء الأعراض، ويساعد على وصف توقيت الفاشية وشكلها. قد تتفق الذروة المفردة الحادة مع تعرض لمصدر نقطي، وقد تتفق القمم المتعاقبة مع الانتشار المتتابع بين الأشخاص؛ لكن أيا من النمطين لا يثبت طريق الانتقال بمفرده. وتجيب نسبة الهجوم — التي تسمى شائعا معدل الهجوم — عن نسبة أفراد السكان المحددين والمعرضين للخطر الذين مرضوا خلال فترة الفاشية المحددة. وهي عادة نسبة (حدوث تراكمي)، وليست معدلا محسوبا باستخدام زمن الأشخاص. ويذكر عالم الوبائيات الحذر ما هو معروف وما هو مفقود وحدود الدليل والإجراء المبرر الآن. المرجع العلمي: مراكز مكافحة الأمراض والوقاية منها، مبادئ علم الوبائيات، الدرس الأول؛ ومنظمة الصحة العالمية، علم الوبائيات الأساسي، الطبعة الثانية، مقاييس وقوع المرض.', 'Observation becomes action only when it is linked to a decision. Who decides? What options exist? What would change if the estimate is wrong? A descriptive question asks: among whom, where and when, how many became ill? An epidemic curve plots cases by date (or time) of symptom onset and helps describe the timing and shape of an outbreak. A sharp single peak may be consistent with a point-source exposure, while successive peaks may be consistent with propagated spread; neither pattern proves a transmission route by itself. The so-called attack rate answers what proportion of the defined population at risk became ill during the specified outbreak period. It is ordinarily a proportion (cumulative incidence), not a rate based on person-time. A careful epidemiologist states what is known, what is missing, the limits of the evidence, and what action is justified now. Reference basis: CDC, Principles of Epidemiology, Lesson 1 (epidemiologic approach and epidemic curves); WHO, Basic Epidemiology, 2nd ed. (measures of disease occurrence).', '{"exampleEn": "Field case — At a wedding, 45 of 150 guests fall ill within two days. The team draws an epidemic curve by onset date, lists foods eaten by ill and well guests, and calculates food-specific attack rates. One dish stands out. The team does not wait for perfect data: it inspects preparation, holds the remaining food, and tells guests what is known and what is still missing. The curve, the attack rate and the honest message together turn observation into action.", "exampleAr": "حالة ميدانية — في حفل زفاف، مرض 45 من 150 ضيفا خلال يومين. يرسم الفريق منحنى وبائيا حسب تاريخ بدء الأعراض، ويسرد الأطعمة التي أكلها المرضى والأصحاء، ويحسب معدلات هجوم خاصة بكل طعام. يبرز طبق واحد. لا ينتظر الفريق بيانات كاملة: يفحص التحضير، ويحتفظ بالطعام المتبقي، ويخبر الضيوف بما هو معروف وما هو ما زال غائبا. المنحنى ومعدل الهجوم والرسالة الصادقة معا تحوّل الملاحظة إلى فعل.", "fieldEn": "End every field note with three lines: what we know, what is missing, and the next action. That is how numbers become a decision.", "fieldAr": "أنهِ كل ملاحظة ميدانية بثلاثة أسطر: ما نعرفه، وما هو غير موجود، والإجراء التالي. هكذا تتحول الأرقام إلى قرار.", "calcTitleEn": "Worked calculation — attack proportion (commonly called attack rate)", "calcTitleAr": "حساب محلول — نسبة الهجوم (وتسمى اصطلاحا معدل الهجوم)", "calcStepsEn": ["Step 1 — Count incident cases among the defined group during the specified outbreak period: 45 guests became ill.", "Step 2 — Count the people at risk in that same group and period: 150 guests ate at the event and were initially at risk.", "Step 3 — Attack proportion = cases ÷ people at risk = 45 ÷ 150 = 0.30.", "Step 4 — Convert to a percentage: 0.30 × 100 = 30%.", "Despite its conventional name, an attack rate is usually a cumulative-incidence proportion, not a person-time incidence rate."], "calcStepsAr": ["الخطوة 1 — عدّ الحالات الجديدة ضمن المجموعة المحددة وخلال فترة الفاشية: مرض 45 ضيفا.", "الخطوة 2 — عدّ الأشخاص المعرضين للخطر في المجموعة والفترة نفسيهما: تناول 150 ضيفا الطعام في المناسبة وكانوا معرضين للخطر عند البداية.", "الخطوة 3 — نسبة الهجوم = الحالات ÷ الأشخاص المعرضين للخطر = 45 ÷ 150 = 0.30.", "الخطوة 4 — حوّلها إلى نسبة مئوية: 0.30 × 100 = 30%.", "على الرغم من الاسم الشائع «معدل الهجوم»، فإنه عادة نسبة حدوث تراكمي وليس معدل حدوث يستخدم زمن الأشخاص."], "calcResultEn": "Result: the attack proportion is 30% (45/150) for the defined group and outbreak period. This descriptive measure alone does not prove which food caused illness; compare food-specific attack proportions among people who ate and did not eat each item, assess uncertainty and possible bias, and interpret the findings with the investigation evidence.", "calcResultAr": "النتيجة: نسبة الهجوم = 30% (45/150) في المجموعة المحددة وخلال فترة الفاشية. هذا المقياس الوصفي وحده لا يثبت أي طعام سبّب المرض؛ بل ينبغي مقارنة نسب الهجوم الخاصة بكل صنف بين من تناولوه ومن لم يتناولوه، وتقييم عدم اليقين والتحيز المحتمل، وتفسير النتائج مع بقية أدلة التقصي.", "terms": [{"termEn": "Epidemic curve", "termAr": "المنحنى الوبائي", "defEn": "Cases plotted by date of onset to show the outbreak over time.", "defAr": "الحالات مرسومة حسب تاريخ بدء الأعراض لإظهار الفاشية عبر الزمن."}, {"termEn": "Attack rate", "termAr": "معدل الهجوم", "defEn": "Cases divided by people at risk during the outbreak period.", "defAr": "الحالات مقسومة على المعرضين للخطر خلال فترة الفاشية."}, {"termEn": "Descriptive question", "termAr": "السؤال الوصفي", "defEn": "A question that fixes who, where, when and how many.", "defAr": "سؤال يثبّت من وأين ومتى وكم."}, {"termEn": "Proportionate action", "termAr": "الإجراء المتناسب", "defEn": "An action sized to the evidence and the risk, while checking continues.", "defAr": "إجراء بحجم الدليل والخطر، مع استمرار الفحص."}], "objEn": ["Turn an observation into a descriptive question and a decision option.", "Draw and read an epidemic curve.", "Calculate an attack rate and state what action it justifies now."], "objAr": ["تحويل ملاحظة إلى سؤال وصفي وخيار قرار.", "رسم وقراءة منحنى وبائي.", "حساب معدل الهجوم وتحديد ما الإجراء الذي يبرره الآن."]}', '[{"qEn": "45 cases among 150 people at risk gives an attack rate of…", "qAr": "45 حالة بين 150 معرضا تعطي معدل هجوم…", "optsEn": ["30%", "15%", "45%", "60%"], "optsAr": ["30%", "15%", "45%", "60%"], "ans": 0, "explEn": "45 ÷ 150 = 0.30 = 30%.", "explAr": "45 ÷ 150 = 0.30 = 30%."}, {"qEn": "An epidemic curve plots cases by…", "qAr": "المنحنى الوبائي يرسم الحالات حسب…", "optsEn": ["Date of onset", "Age only", "Hospital name"], "optsAr": ["تاريخ بدء الأعراض", "العمر فقط", "اسم المستشفى"], "ans": 0, "explEn": "Onset date shows start, peak and shape over time.", "explAr": "تاريخ بدء الأعراض يظهر البداية والذروة والشكل عبر الزمن."}, {"qEn": "A single sharp peak on a curve most suggests…", "qAr": "ذروة حادة واحدة على المنحنى توحي غالبا بـ…", "optsEn": ["No outbreak", "A point source", "A laboratory error"], "optsAr": ["عدم وجود فاشية", "مصدر نقطي", "خطأ مخبري"], "ans": 1, "explEn": "One sharp peak fits one shared exposure at one time.", "explAr": "ذروة حادة واحدة تناسب تعرضا واحدا مشتركا في وقت واحد."}, {"qEn": "A careful report should state…", "qAr": "التقرير الحذر يجب أن يذكر…", "optsEn": ["Only what supports one view", "Nothing about uncertainty", "What is known and what is missing"], "optsAr": ["ما يدعم رأيا واحدا فقط", "لا شيء عن عدم اليقين", "ما هو معروف وما هو غير موجود"], "ans": 2, "explEn": "Honest action needs both evidence and gaps.", "explAr": "الإجراء الصادق يحتاج الدليل والفجوات معا."}]' FROM courses WHERE course_code='B-101';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 1, 'البسط والمقام والمقياس', 'Numerators, denominators and scale', '[''التمييز بين العدد والنسبة والتناسب والمعدل.'', ''اختيار مقام يناسب السؤال.'', ''تحويل المقياس إلى لكل 1000 أو لكل 100000 من دون تغيير معناه.'']', '[''Distinguish a count, a proportion, a ratio and a rate.'', ''Choose a denominator that matches the question.'', ''Convert a measure to per 1,000 or per 100,000 without changing its meaning.'']', 'العدد يقول كم. والنسبة تقول أي حصة من الكل — البسط داخل المقام، ودائما بين 0 و1. والتناسب يقارن كميتين لا يحتاج أن تحتوي إحداهما الأخرى، مثل الذكور إلى الإناث. ومعدل الحدوث يقيس سرعة ظهور الحالات الجديدة: حالات جديدة مقسومة على زمن الأشخاص المعرضين للخطر. وزمن الأشخاص هو مجموع زمن متابعة كل شخص مؤهل وهو معرض للخطر. ويُبلّغ عن المعدل مع وحدة زمنية في مقامه، مثل حالات لكل 1000 سنة-شخص. شخص واحد تُبع 10 سنوات يساهم بـ 10 سنوات-شخص؛ وعشرة أشخاص تُبعوا سنة واحدة يساهمون أيضا بـ 10 سنوات-شخص. التكبير بـ 1000 أو 100000 يجعل العدد الصغير أسهل قراءة فقط؛ ولا يجعل الخطر أكبر. اكتب دائما المقياس والفترة والسكان مع الرقم.', 'A count says how many. A proportion says what share of a whole — numerator inside denominator, always between 0 and 1. A ratio compares two quantities that need not contain each other, such as males to females. An incidence rate measures how quickly new cases occur: new cases divided by person-time at risk. Person-time is the sum of each eligible person’s observed time while at risk. A rate is reported with a time unit in its denominator (for example, cases per 1,000 person-years). One person followed for 10 years contributes 10 person-years; ten people followed for 1 year also contribute 10 person-years. Scaling by 1,000 or 100,000 only makes a small number easier to read; it does not make the risk bigger. Always write the scale, the period and the population with the number.', '{"exampleEn": "Field case — Two clinics report “80 cases” each. Clinic A serves 4,000 people; Clinic B serves 800 people. Clinic A: 80 ÷ 4,000 = 20 per 1,000. Clinic B: 80 ÷ 800 = 100 per 1,000. The counts are equal; the burden is five times higher in Clinic B. The team therefore checks Clinic B first, while asking whether its catchment population was counted correctly.", "exampleAr": "حالة ميدانية — عيادتان تبلغان عن «80 حالة» لكل منهما. العيادة أ تخدم 4000 شخص؛ والعيادة ب تخدم 800 شخص. العيادة أ: 80 ÷ 4000 = 20 لكل 1000. العيادة ب: 80 ÷ 800 = 100 لكل 1000. العددان متساويان؛ والعبء أعلى خمس مرات في العيادة ب. لذا يفحص الفريق العيادة ب أولا، مع السؤال عما إذا كان سكان منطقتها قد عُدّوا بشكل صحيح.", "fieldEn": "Never report a count without its denominator, period and population. If the denominator is uncertain, say so and give the range.", "fieldAr": "لا تبلغ عن عدد أبدا من دون مقامه وفترته وسكانه. إذا كان المقام غير مؤكد، قل ذلك واعطِ المدى.", "calcTitleEn": "Worked calculation — proportion and per 1,000", "calcTitleAr": "حساب محلول — النسبة ولكل 1000", "calcStepsEn": ["Step 1 — Count: 80 new cases.", "Step 2 — Denominator: 4,000 people at risk in the same year.", "Step 3 — Proportion: 80 ÷ 4,000 = 0.02.", "Step 4 — Per 1,000: 0.02 × 1,000 = 20 per 1,000 people over the one-year period (a cumulative-incidence proportion, not a person-time rate)."], "calcStepsAr": ["الخطوة 1 — العدّ: 80 حالة جديدة.", "الخطوة 2 — المقام: 4000 شخص معرض للخطر في نفس السنة.", "الخطوة 3 — النسبة: 80 ÷ 4000 = 0.02.", "الخطوة 4 — لكل 1000: 0.02 × 1000 = 20 لكل 1000 شخص خلال فترة السنة الواحدة (حدوث تراكمي، وليس معدلًا بزمن الأشخاص)."], "calcResultEn": "Result: cumulative incidence = 2% (20 per 1,000 people) over one year. These are two scales for the same proportion, not a rate per person-year. State the population at risk at baseline and the one-year follow-up period.", "calcResultAr": "النتيجة: الحدوث التراكمي = 2% (20 لكل 1000 شخص) خلال سنة واحدة. هذان مقياسان لعرض النسبة نفسها، وليسا معدلًا لكل سنة-شخص. اذكر السكان المعرضين للخطر عند البداية وفترة المتابعة البالغة سنة.", "terms": [{"termEn": "Count", "termAr": "العدد", "defEn": "A simple number of cases or events, with no denominator.", "defAr": "عدد بسيط من الحالات أو الأحداث، من دون مقام."}, {"termEn": "Proportion", "termAr": "النسبة", "defEn": "Numerator inside denominator; ranges 0 to 1.", "defAr": "البسط داخل المقام؛ يتراوح بين 0 و1."}, {"termEn": "Ratio", "termAr": "التناسب", "defEn": "One quantity divided by another; numerator need not be inside denominator.", "defAr": "كمية مقسومة على أخرى؛ لا يحتاج البسط أن يكون داخل المقام."}, {"termEn": "Person-time", "termAr": "زمن الأشخاص", "defEn": "Total time people were observed while at risk.", "defAr": "إجمالي الزمن الذي رُوقب فيه الناس وهم معرضون للخطر."}], "objEn": ["Distinguish a count, a proportion, a ratio and a rate.", "Choose a denominator that matches the question.", "Convert a measure to per 1,000 or per 100,000 without changing its meaning."], "objAr": ["التمييز بين العدد والنسبة والتناسب والمعدل.", "اختيار مقام يناسب السؤال.", "تحويل المقياس إلى لكل 1000 أو لكل 100000 من دون تغيير معناه."]}', '[{"qEn": "A proportion always lies between…", "qAr": "النسبة تقع دائما بين…", "optsEn": ["0 and 1", "0 and 100,000", "−1 and 1"], "optsAr": ["0 و1", "0 و100000", "−1 و1"], "ans": 0, "explEn": "The numerator is inside the denominator, so a proportion cannot exceed 1.", "explAr": "البسط داخل المقام، لذا لا تتجاوز النسبة 1."}, {"qEn": "80 cases in 4,000 people equals…", "qAr": "80 حالة بين 4000 شخص تساوي…", "optsEn": ["2 per 1,000", "20 per 1,000", "200 per 1,000"], "optsAr": ["2 لكل 1000", "20 لكل 1000", "200 لكل 1000"], "ans": 1, "explEn": "80 ÷ 4,000 = 0.02; × 1,000 = 20 per 1,000.", "explAr": "80 ÷ 4000 = 0.02؛ × 1000 = 20 لكل 1000."}, {"qEn": "Person-time is…", "qAr": "زمن الأشخاص هو…", "optsEn": ["The number of clinics", "The incubation period", "Total time people were observed while at risk"], "optsAr": ["عدد العيادات", "فترة الحضانة", "إجمالي الزمن الذي رُوقب فيه الناس وهم معرضون للخطر"], "ans": 2, "explEn": "Person-time sums each person''s time at risk.", "explAr": "زمن الأشخاص يجمع زمن كل شخص وهو معرض للخطر."}, {"qEn": "Scaling to per 100,000…", "qAr": "التكبير إلى لكل 100000…", "optsEn": ["Only changes how the number is read", "Changes the risk itself", "Removes the need for a denominator"], "optsAr": ["يغير طريقة قراءة الرقم فقط", "يغير الخطر نفسه", "يلغي الحاجة إلى المقام"], "ans": 0, "explEn": "Scaling multiplies numerator and reading together; the underlying risk is unchanged.", "explAr": "التكبير يضرب البسط والقراءة معا؛ والخطر الكامن لا يتغير."}]' FROM courses WHERE course_code='B-104';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 2, 'الانتشار والحدوث', 'Prevalence and incidence', '[''التمييز بين انتشار النقطة وانتشار الفترة والحدوث التراكمي.'', ''حساب الحدوث التراكمي ومعدل الحدوث من زمن الأشخاص.'', ''شرح لماذا يرتفع الانتشار عندما يتحسن البقاء حتى لو لم يتغير الحدوث.'']', '[''Distinguish point prevalence, period prevalence and cumulative incidence.'', ''Calculate cumulative incidence and an incidence rate from person-time.'', ''Explain why prevalence rises when survival improves even if incidence is unchanged.'']', 'الانتشار يعدّ الحالات الموجودة: من لديه الحالة الآن (انتشار النقطة) أو في أي وقت خلال فترة (انتشار الفترة). والحدوث يعدّ الحالات الجديدة: الحدوث التراكمي هو حالات جديدة مقسومة على المعرضين للخطر في البداية، خلال فترة محددة؛ ومعدل الحدوث هو حالات جديدة مقسومة على زمن الأشخاص المعرضين للخطر. فكّر في الانتشار كصورة لبركة، والحدوث كالتدفق إليها. إذا عاش الناس أطول مع حالة مزمنة، تكبر البركة حتى لو بقي التدفق كما هو. لذلك ارتفاع الانتشار لا يعني دائما ارتفاع الخطر. ولمرض نادر قصير، يكون الانتشار والحدوث قريبين. ولحالة طويلة الأمد، قد يكون الانتشار أعلى من الحدوث السنوي مرات كثيرة.', 'Prevalence counts existing cases: who has the condition now (point prevalence) or at any time during a period (period prevalence). Incidence counts new cases: cumulative incidence is new cases divided by people at risk at the start, over a stated period; incidence rate is new cases divided by person-time at risk. Think of prevalence as a photograph of a pool and incidence as the flow into the pool. If people live longer with a chronic condition, the pool grows even if the flow stays the same. That is why a rising prevalence does not always mean rising risk. For a rare, short illness, prevalence and incidence are close. For a long-lasting condition, prevalence can be many times higher than yearly incidence.', '{"exampleEn": "Field case — A survey finds 120 people with diabetes in a town of 4,000: point prevalence = 120 ÷ 4,000 = 3%. Over the next year, 50 new cases occur among 2,000 people at risk: cumulative incidence = 2.5%. A manager asks why prevalence is rising. The team checks survival and case-finding: better treatment means people live longer with diabetes, and better screening finds more existing cases. Incidence alone did not explain the rise.", "exampleAr": "حالة ميدانية — مسح يجد 120 شخصا لديهم السكري في بلدة فيها 4000: انتشار النقطة = 120 ÷ 4000 = 3%. وخلال السنة التالية، تحدث 50 حالة جديدة بين 2000 معرض للخطر: الحدوث التراكمي = 2.5%. مدير يسأل لماذا يرتفع الانتشار. يتحقق الفريق من البقاء واكتشاف الحالات: علاج أفضل يعني عيشا أطول مع السكري، وفحص أفضل يكتشف حالات موجودة أكثر. الحدوث وحده لم يفسّر الارتفاع.", "fieldEn": "When you report prevalence, state the point or period. For cumulative incidence, state the baseline population at risk and the follow-up interval. For an incidence rate, state the person-time unit and observation interval. Do not label a proportion “per year” as though it were a person-time rate.", "fieldAr": "عندما تبلغ عن الانتشار، اذكر النقطة أو الفترة. وفي الحدوث التراكمي، اذكر السكان المعرضين للخطر عند البداية وفترة المتابعة. وفي معدل الحدوث، اذكر وحدة زمن الأشخاص وفترة الرصد. لا تسمِّ النسبة «لكل سنة» كما لو كانت معدلًا بزمن الأشخاص.", "calcTitleEn": "Worked calculation — cumulative incidence", "calcTitleAr": "حساب محلول — الحدوث التراكمي", "calcStepsEn": ["Step 1 — New cases in one year: 50.", "Step 2 — People at risk at the start: 2,000 (people who already had the condition are excluded).", "Step 3 — Divide: 50 ÷ 2,000 = 0.025.", "Step 4 — As a percentage: 0.025 × 100 = 2.5% over one year."], "calcStepsAr": ["الخطوة 1 — الحالات الجديدة في سنة واحدة: 50.", "الخطوة 2 — المعرضون للخطر في البداية: 2000 (من كان لديهم الحالة أُخرجوا).", "الخطوة 3 — اقسم: 50 ÷ 2000 = 0.025.", "الخطوة 4 — كنسبة مئوية: 0.025 × 100 = 2.5% خلال سنة واحدة."], "calcResultEn": "Result: cumulative incidence = 2.5% over the one-year follow-up (50 new cases ÷ 2,000 people at risk at baseline). If 50 new cases arose during 8,000 person-years at risk, the incidence rate would be 50 ÷ 8,000 = 6.25 cases per 1,000 person-years. These measures have different denominators and units.", "calcResultAr": "النتيجة: الحدوث التراكمي = 2.5% خلال متابعة السنة الواحدة (50 حالة جديدة ÷ 2000 شخص معرض للخطر عند البداية). وإذا نشأت 50 حالة جديدة خلال 8000 سنة-شخص معرضة للخطر، فمعدل الحدوث = 50 ÷ 8000 = 6.25 حالة لكل 1000 سنة-شخص. للمقياسين مقامان ووحدتان مختلفتان.", "terms": [{"termEn": "Point prevalence", "termAr": "انتشار النقطة", "defEn": "Existing cases at one point in time divided by population at that point.", "defAr": "الحالات الموجودة عند نقطة زمنية واحدة مقسومة على السكان عندها."}, {"termEn": "Period prevalence", "termAr": "انتشار الفترة", "defEn": "Number of people who had the condition at any time during the specified period (pre-existing at its start or becoming a case during it) divided by the average or mid-period population.", "defAr": "عدد الأشخاص الذين كانت لديهم الحالة في أي وقت خلال الفترة المحددة (موجودة عند بدايتها أو ظهرت خلالها) مقسومًا على متوسط السكان أو عددهم في منتصف الفترة."}, {"termEn": "Cumulative incidence", "termAr": "الحدوث التراكمي", "defEn": "New cases divided by people at risk at the start, over a stated period.", "defAr": "حالات جديدة مقسومة على المعرضين للخطر في البداية، خلال فترة محددة."}, {"termEn": "Incidence rate", "termAr": "معدل الحدوث", "defEn": "New cases divided by person-time at risk.", "defAr": "حالات جديدة مقسومة على زمن الأشخاص المعرضين للخطر."}], "objEn": ["Distinguish point prevalence, period prevalence and cumulative incidence.", "Calculate cumulative incidence and an incidence rate from person-time.", "Explain why prevalence rises when survival improves even if incidence is unchanged."], "objAr": ["التمييز بين انتشار النقطة وانتشار الفترة والحدوث التراكمي.", "حساب الحدوث التراكمي ومعدل الحدوث من زمن الأشخاص.", "شرح لماذا يرتفع الانتشار عندما يتحسن البقاء حتى لو لم يتغير الحدوث."]}', '[{"qEn": "50 new cases among 2,000 people at risk gives…", "qAr": "50 حالة جديدة بين 2000 معرض تعطي…", "optsEn": ["25% prevalence", "2.5% cumulative incidence", "0.25 per 1,000"], "optsAr": ["25% انتشارا", "2.5% حدوثا تراكميا", "0.25 لكل 1000"], "ans": 1, "explEn": "50 ÷ 2,000 = 0.025 = 2.5%.", "explAr": "50 ÷ 2000 = 0.025 = 2.5%."}, {"qEn": "Point prevalence counts…", "qAr": "انتشار النقطة يعدّ…", "optsEn": ["Only deaths", "Only new cases", "Existing cases at one point in time"], "optsAr": ["الوفيات فقط", "الحالات الجديدة فقط", "الحالات الموجودة عند نقطة زمنية واحدة"], "ans": 2, "explEn": "Point prevalence is a snapshot of existing cases.", "explAr": "انتشار النقطة لقطة للحالات الموجودة."}, {"qEn": "Prevalence can rise while incidence is unchanged if…", "qAr": "قد يرتفع الانتشار مع ثبات الحدوث إذا…", "optsEn": ["People live longer with the condition", "No one is screened", "The population shrinks to zero"], "optsAr": ["عاش الناس أطول مع الحالة", "لم يُفحص أحد", "تقلص السكان إلى صفر"], "ans": 0, "explEn": "Longer survival keeps more existing cases in the pool.", "explAr": "البقاء الأطول يبقي حالات موجودة أكثر في البركة."}, {"qEn": "Incidence rate uses which denominator?", "qAr": "معدل الحدوث يستخدم أي مقام؟", "optsEn": ["Total hospital beds", "Person-time at risk", "Number of clinics"], "optsAr": ["إجمالي أسرة المستشفيات", "زمن الأشخاص المعرضين للخطر", "عدد العيادات"], "ans": 1, "explEn": "Incidence rate = new cases ÷ person-time at risk.", "explAr": "معدل الحدوث = حالات جديدة ÷ زمن الأشخاص المعرضين للخطر."}]' FROM courses WHERE course_code='B-104';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 3, 'إماتة الحالات والوفيات ومعدل الهجوم', 'Case-fatality, mortality and attack rate', '[''حساب نسبة إماتة الحالات ومعدل الهجوم والوفيات الخام.'', ''التمييز بين المعدلات الخام والمعدلات الخاصة بالعمر.'', ''شرح لماذا قد تضلل المقارنة الخام عندما تختلف البنية العمرية.'']', '[''Calculate case-fatality ratio, attack rate and crude mortality.'', ''Distinguish crude from age-specific rates.'', ''Explain why a crude comparison can mislead when age structures differ.'']', 'نسبة إماتة الحالات هي الوفيات بسبب الحالة بين مجموعة محددة من الحالات الجديدة مقسومة على تلك الحالات الجديدة نفسها، مع متابعتها خلال فترة معلومة؛ وتجيب عن «بين من ظهرت لديهم الحالة، ما نسبة من توفوا بسببها أثناء المتابعة؟» يجب أن يشير البسط والمقام إلى تعريف الحالة والمكان والمجموعة نفسها؛ وقد يؤدي عدم اكتمال المتابعة إلى خفض تقدير الإماتة المؤقت. يستخدم مقياس وفيات السكان الوفيات في المجتمع المحدد بسطًا، والسكان المعرضين للخطر مقامًا للمكان والفترة نفسيهما. وعند استخدام عدد السكان في منتصف الفترة، يُعرض عادةً كوفيات لكل 1000 أو 100000 من السكان خلال تلك الفترة؛ وعند استخدام مجموع زمن الأشخاص، يكون المقام زمن الأشخاص. أما خطر الوفاة السكاني (نسبة الوفيات التراكمية) فيستخدم الأشخاص المعرضين للخطر عند البداية، ويعرض نسبة من توفوا خلال متابعة محددة. ومعدل الهجوم هو حدوث تراكمي أثناء الفاشية، وليس معدلًا حقيقيًا بزمن الأشخاص: الحالات الجديدة التي تستوفي تعريف حالة الفاشية خلال فترة الفاشية المحددة ÷ السكان المعرضين للخطر عند بداية تلك الفترة (أو المجموعة الفرعية المعرضة ذات الصلة عند حساب معدل هجوم خاص بغذاء معين). تستخدم الوفيات الخام كل السكان المؤهلين؛ أما معدل الوفيات الخاص بالعمر فيقصر الوفيات والمقام على الفئة العمرية نفسها. المقارنة الخام قد تضلل: بلدة فيها مسنون كثيرون قد تكون وفياتها الخام أعلى حتى لو كانت وفياتها الخاصة بالعمر هي نفسها. انظر دائما إلى المعدلات الخاصة قبل أن تستنتج أن مكانا «أسوأ».', 'Case-fatality ratio (CFR) is deaths due to the condition among a defined group of incident cases divided by those same incident cases, followed over a stated period: it answers “among people who developed the condition, what share died from it during follow-up?” The numerator and denominator must refer to the same case definition, place and cohort; incomplete follow-up can bias a provisional CFR downward. A population mortality measure uses deaths in the defined population as the numerator and the population at risk as the denominator for the same place and period. With a mid-period population denominator it is conventionally reported as deaths per 1,000 or 100,000 population for that period; with summed person-time it is deaths per person-time. A mortality risk (cumulative mortality proportion) instead uses people at risk at baseline and reports the proportion dying over a stated follow-up. Attack rate is cumulative incidence during an outbreak, not a true person-time rate: new cases meeting the outbreak case definition during the stated outbreak period ÷ the population at risk at the start of that period (or the relevant exposed subgroup for a food-specific attack rate). Crude mortality uses the whole eligible population; an age-specific mortality rate restricts both deaths and the denominator to the same age group. A crude mortality comparison can mislead: a town with many older residents can have higher crude mortality even if age-specific mortality is the same. Always look at specific rates before concluding that one place is “worse.”', '{"exampleEn": "Field case — Two towns each report 12 deaths. Town A has 300 cases (CFR 4%) and 9,000 people. Town B has 120 cases (CFR 10%) and 3,000 people. Town B''s CFR is higher, suggesting later care or a more vulnerable case mix, while Town A''s crude mortality (1.3 per 1,000) is lower than Town B''s (4 per 1,000). The team then splits both towns by age: Town B has far more residents aged 65+, so it compares age-specific rates before blaming care quality.", "exampleAr": "حالة ميدانية — بلدتان تبلغان عن 12 وفاة لكل منهما. البلدة أ فيها 300 حالة (إماتة 4%) و9000 شخص. والبلدة ب فيها 120 حالة (إماتة 10%) و3000 شخص. إماتة البلدة ب أعلى، مما يوحي برعاية متأخرة أو مزيج حالات أكثر هشاشة، بينما وفيات البلدة أ الخام (1.3 لكل 1000) أقل من البلدة ب (4 لكل 1000). ثم يقسّم الفريق البلدتين حسب العمر: البلدة ب فيها مقيمون أعمارهم 65+ أكثر بكثير، لذا يقارن المعدلات الخاصة بالعمر قبل لوم جودة الرعاية.", "fieldEn": "When you compare two places, compare specific rates first. Report CFR with its period and case definition — a CFR without them cannot be compared.", "fieldAr": "عندما تقارن مكانين، قارن المعدلات الخاصة أولا. أبلغ عن نسبة الإماتة مع فترتها وتعريف حالتها — نسبة بلا هما لا يمكن مقارنتها.", "calcTitleEn": "Worked calculation — CFR", "calcTitleAr": "حساب محلول — نسبة إماتة الحالات", "calcStepsEn": ["Step 1 — Denominator: 300 incident confirmed cases meeting the same case definition and followed over the stated period.", "Step 2 — Numerator: 12 deaths due to the condition among those 300 incident cases during follow-up.", "Step 3 — Divide: 12 ÷ 300 = 0.04.", "Step 4 — As a percentage: 0.04 × 100 = 4%."], "calcStepsAr": ["الخطوة 1 — المقام: 300 حالة مؤكدة جديدة تستوفي تعريف الحالة نفسه وتُتابع خلال الفترة المحددة.", "الخطوة 2 — البسط: 12 وفاة بسبب الحالة بين تلك الحالات الجديدة الـ300 خلال المتابعة.", "الخطوة 3 — اقسم: 12 ÷ 300 = 0.04.", "الخطوة 4 — كنسبة مئوية: 0.04 × 100 = 4%."], "calcResultEn": "Result: CFR = 4% (12 deaths among 300 incident cases). If those 12 deaths occurred in the same town during the same one-year period and the mid-year population was 9,000, the crude cause-specific mortality rate is 12 ÷ 9,000 × 1,000 = 1.33 deaths per 1,000 population during that year. The population, place, cause, period and denominator must match; CFR and mortality measure different outcomes.", "calcResultAr": "النتيجة: نسبة إماتة الحالات = 4% (12 وفاة بين 300 حالة جديدة). وإذا حدثت الوفيات الـ12 في البلدة نفسها وخلال فترة السنة نفسها وكان عدد السكان في منتصف السنة 9000، فإن معدل الوفيات الخام النوعي للسبب = 12 ÷ 9000 × 1000 = 1.33 وفاة لكل 1000 من السكان خلال تلك السنة. يجب أن يتطابق المجتمع والمكان والسبب والفترة والمقام؛ فنسبة إماتة الحالات والوفيات تقيسان نتيجتين مختلفتين.", "terms": [{"termEn": "Case-fatality ratio (CFR)", "termAr": "نسبة إماتة الحالات", "defEn": "Deaths due to the condition among a defined group of incident cases divided by those same cases, followed over a stated period.", "defAr": "الوفيات بسبب الحالة بين مجموعة محددة من الحالات الجديدة مقسومة على تلك الحالات نفسها، مع متابعتها خلال فترة معلومة."}, {"termEn": "Attack rate (cumulative incidence)", "termAr": "معدل الهجوم (الحدوث التراكمي)", "defEn": "New outbreak cases during a stated outbreak period divided by the population at risk at its start; for a food-specific attack rate, restrict both numerator and denominator to the relevant exposed group.", "defAr": "الحالات الجديدة أثناء فترة فاشية محددة مقسومة على السكان المعرضين للخطر عند بدايتها؛ وفي معدل الهجوم الخاص بغذاء معين، يُقصر البسط والمقام على المجموعة المعرضة ذات الصلة."}, {"termEn": "Crude mortality rate", "termAr": "معدل الوفيات الخام", "defEn": "Deaths in a defined population during a stated period divided by the mid-period population at risk (or by summed person-time when that is the chosen design); report the time period and scale.", "defAr": "وفيات السكان المحددين خلال فترة معلومة مقسومة على عدد السكان المعرضين للخطر في منتصف الفترة (أو على مجموع زمن الأشخاص عند استخدام هذا التصميم)؛ ويجب ذكر الفترة ومقياس العرض."}, {"termEn": "Crude rate", "termAr": "المعدل الخام", "defEn": "A rate for the whole population, without splitting by group.", "defAr": "معدل لكل السكان، من دون تقسيم حسب المجموعة."}, {"termEn": "Age-specific mortality rate", "termAr": "معدل الوفيات الخاص بالعمر", "defEn": "Deaths in a specified age group during a stated period divided by the mid-period population at risk in that same age group; report the period and scale.", "defAr": "وفيات فئة عمرية محددة خلال فترة معلومة مقسومة على عدد السكان المعرضين للخطر في منتصف الفترة ضمن الفئة العمرية نفسها؛ ويجب ذكر الفترة ومقياس العرض."}], "objEn": ["Calculate case-fatality ratio, attack rate and crude mortality.", "Distinguish crude from age-specific rates.", "Explain why a crude comparison can mislead when age structures differ."], "objAr": ["حساب نسبة إماتة الحالات ومعدل الهجوم والوفيات الخام.", "التمييز بين المعدلات الخام والمعدلات الخاصة بالعمر.", "شرح لماذا قد تضلل المقارنة الخام عندما تختلف البنية العمرية."]}', '[{"qEn": "12 deaths due to the disease among 300 incident cases followed over the same period gives a CFR of…", "qAr": "12 وفاة بسبب المرض بين 300 حالة جديدة تمت متابعتها خلال الفترة نفسها تعطي نسبة إماتة…", "optsEn": ["0.4%", "25%", "4%"], "optsAr": ["0.4%", "25%", "4%"], "ans": 2, "explEn": "12 ÷ 300 = 0.04 = 4%.", "explAr": "12 ÷ 300 = 0.04 = 4%."}, {"qEn": "Crude mortality rate for a stated period divides deaths by…", "qAr": "معدل الوفيات الخام خلال فترة محددة يقسم الوفيات على…", "optsEn": ["The mid-period population at risk in the same place and period", "Only cases", "Only survivors"], "optsAr": ["عدد السكان المعرضين للخطر في منتصف الفترة نفسها والمكان نفسه", "الحالات فقط", "الناجون فقط"], "ans": 0, "explEn": "Mortality uses the whole population; CFR uses cases.", "explAr": "الوفيات تستخدم كل السكان؛ والإماتة تستخدم الحالات."}, {"qEn": "An age-specific rate is…", "qAr": "المعدل الخاص بالعمر هو…", "optsEn": ["Always larger than the crude rate", "Restricted to one age group", "A count with no denominator"], "optsAr": ["دائما أكبر من المعدل الخام", "مقتصر على فئة عمرية واحدة", "عدد بلا مقام"], "ans": 1, "explEn": "Specific rates restrict numerator and denominator to the same group.", "explAr": "المعدلات الخاصة تقصر البسط والمقام على نفس المجموعة."}, {"qEn": "A crude comparison can mislead because…", "qAr": "المقارنة الخام قد تضلل لأن…", "optsEn": ["Counts are always wrong", "CFR is never useful", "Age structures may differ"], "optsAr": ["الأعداد دائما خاطئة", "الإماتة ليست مفيدة أبدا", "البنى العمرية قد تختلف"], "ans": 2, "explEn": "Different age structures can drive crude differences even when specific rates match.", "explAr": "البنى العمرية المختلفة قد تقود الفروق الخام حتى عندما تتطابق المعدلات الخاصة."}]' FROM courses WHERE course_code='B-104';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 1, 'جدول 2×2 والخطر النسبي', 'The 2×2 table and relative risk', '[''بناء جدول 2×2 بالتعرض في الصفوف والنتيجة في الأعمدة.'', ''حساب الخطر في المعرضين وغير المعرضين.'', ''حساب الخطر النسبي وتفسيره بلغة بسيطة.'']', '[''Build a 2×2 table with exposure in rows and outcome in columns.'', ''Calculate risk in exposed and unexposed groups.'', ''Calculate and interpret RR in plain language.'']', 'جدول 2×2 يحوّل المقارنة إلى أربعة أرقام: أ = حالات معرضة، ب = غير حالات معرضة، ج = حالات غير معرضة، د = غير حالات غير معرضة. الخطر في المعرضين هو أ ÷ (أ+ب). والخطر في غير المعرضين هو ج ÷ (ج+د). وفي دراسة أترابية أو تجربة عشوائية ذات مقامات صحيحة وفترة متابعة محددة، يكون الخطر النسبي هو الخطر الأول مقسوما على الثاني. اذكر تعريف النتيجة وفترة المتابعة؛ ولا تحسب نسبة مخاطر من عينة حالات وشواهد تقليدية لأن أعداد الحالات والشواهد المختارة لا تمثل مخاطر السكان. الخطر النسبي = 1 يعني خطرا متساويا. فوق 1 يعني خطرا أعلى لدى المعرضين. تحت 1 يعني خطرا أقل لدى المعرضين. الخطر النسبي نسبة، لا فرق نقاط مئوية: الخطر النسبي 2.67 لا يعني «267% من الناس مرضوا». بل يعني أن الخطر كان 2.67 ضعف الخطر لدى غير المعرضين. أبلغ دائما عن الخطرين مع الخطر النسبي، حتى يرى القارئ الحجم المطلق خلف النسبة.', 'A 2×2 table turns a comparison into four numbers: a = exposed cases, b = exposed non-cases, c = unexposed cases, d = unexposed non-cases. Risk in the exposed group is a ÷ (a+b). Risk in the unexposed group is c ÷ (c+d). In a cohort study or randomized trial with valid group denominators and a defined follow-up horizon, relative risk (RR) is the first divided by the second. State the outcome definition and follow-up period; do not calculate a risk ratio from a conventional case-control sample because the sampled case/control totals do not represent population risks. RR = 1 means equal risk. RR above 1 means higher risk in the exposed group. RR below 1 means lower risk in the exposed group. RR is a ratio, not a percentage-point difference: RR 2.67 does not mean “267% of people became ill.” It means the risk was 2.67 times the risk in the unexposed group. Always report the two risks with the RR, so the reader can see the absolute size behind the ratio.', '{"exampleEn": "Field case — At a canteen, 30 people ate a salad and 120 did not. Among salad eaters, 18 became ill; among others, 27 became ill. The team builds the 2×2 table above, calculates RR 2.67, and checks age and other foods before acting. The salad is held and preparation is inspected, while the team says the comparison is still being checked for confounding.", "exampleAr": "حالة ميدانية — في مقصف، أكل 30 شخصا سلطة ولم يأكلها 120. بين آكلي السلطة، مرض 18؛ وبين الآخرين، مرض 27. يبني الفريق جدول 2×2 أعلاه، ويحسب الخطر النسبي 2.67، ويتحقق من العمر والأطعمة الأخرى قبل التصرف. تُحجز السلطة ويُفحص التحضير، مع قول إن المقارنة ما زالت قيد الفحص من الإرباك.", "fieldEn": "Always show the 2×2 counts with any RR. A ratio without its counts hides whether the numbers were tiny or large.", "fieldAr": "أظهر دائما أعداد 2×2 مع أي خطر نسبي. النسبة بلا أعدادها تخفي ما إذا كانت الأرقام صغيرة أم كبيرة.", "calcTitleEn": "Worked calculation — RR", "calcTitleAr": "حساب محلول — الخطر النسبي", "calcStepsEn": ["Step 1 — Build the table: exposed 18 cases / 12 non-cases (total 30); unexposed 27 cases / 93 non-cases (total 120).", "Step 2 — Risk exposed: 18 ÷ 30 = 0.60 = 60%.", "Step 3 — Risk unexposed: 27 ÷ 120 = 0.225 = 22.5%.", "Step 4 — RR: 0.60 ÷ 0.225 = 2.67."], "calcStepsAr": ["الخطوة 1 — ابنِ الجدول: معرضون 18 حالة / 12 غير حالة (المجموع 30)؛ غير معرضين 27 حالة / 93 غير حالة (المجموع 120).", "الخطوة 2 — خطر المعرضين: 18 ÷ 30 = 0.60 = 60%.", "الخطوة 3 — خطر غير المعرضين: 27 ÷ 120 = 0.225 = 22.5%.", "الخطوة 4 — الخطر النسبي: 0.60 ÷ 0.225 = 2.67."], "calcResultEn": "Result: RR = 2.67. The exposed group had 2.67 times the risk of the unexposed group. In plain words: 60 of every 100 exposed people became ill, compared with about 23 of every 100 unexposed people.", "calcResultAr": "النتيجة: الخطر النسبي = 2.67. المجموعة المعرضة خطرها 2.67 ضعف خطر غير المعرضة. ببساطة: 60 من كل 100 معرض مرضوا، مقابل نحو 23 من كل 100 غير معرض.", "terms": [{"termEn": "2×2 table", "termAr": "جدول 2×2", "defEn": "Exposure by outcome counts: a, b, c, d.", "defAr": "أعداد التعرض حسب النتيجة: أ، ب، ج، د."}, {"termEn": "Risk", "termAr": "الخطر", "defEn": "Cases divided by people at risk in a group.", "defAr": "الحالات مقسومة على المعرضين للخطر في مجموعة."}, {"termEn": "Relative risk (RR)", "termAr": "الخطر النسبي", "defEn": "Risk in exposed divided by risk in unexposed.", "defAr": "الخطر في المعرضين مقسوما على الخطر في غير المعرضين."}, {"termEn": "Reference group", "termAr": "المجموعة المرجعية", "defEn": "The unexposed group used as the comparison.", "defAr": "المجموعة غير المعرضة المستخدمة للمقارنة."}], "deepSections": [{"titleEn": "From counts to a valid comparison", "titleAr": "من الأعداد إلى مقارنة صالحة", "bodyEn": "A 2×2 table is not merely a layout; it encodes the study design and the denominator behind each estimate. Before calculating, define the exposure, outcome, eligibility criteria, time zero, and follow-up horizon. The exposed risk is a/(a+b), because a and b together are all exposed participants at risk. The unexposed risk is c/(c+d). The denominator must exclude people who already had the outcome at baseline when estimating first occurrence. If follow-up differs materially between participants, a simple cumulative risk may not be comparable; consider person-time methods or a time-to-event analysis instead. Check that each person contributes to one mutually exclusive exposure group and one outcome category for the chosen analysis.", "bodyAr": "جدول 2×2 ليس مجرد ترتيب شكلي؛ بل يعبّر عن تصميم الدراسة والمقام الذي يقوم عليه كل تقدير. قبل الحساب، عرّف التعرض والنتيجة ومعايير الأهلية ونقطة بدء المتابعة ومدتها. خطر المعرضين هو أ/(أ+ب)، لأن أ وب معاً يمثلان جميع المعرضين للخطر. وخطر غير المعرضين هو ج/(ج+د). ينبغي أن يستبعد المقام من كانت لديهم النتيجة عند خط الأساس عند تقدير حدوثها لأول مرة. إذا اختلفت مدة المتابعة بين المشاركين اختلافاً مهماً، فقد لا يكون الخطر التراكمي البسيط قابلاً للمقارنة؛ وقد يلزم استخدام زمن الأشخاص أو تحليل الزمن حتى الحدث. تحقق من أن كل شخص ينتمي إلى مجموعة تعرض واحدة متبادلة الاستبعاد وإلى فئة نتيجة واحدة في التحليل المحدد."}, {"titleEn": "Interpreting the relative risk without exaggeration", "titleAr": "تفسير الخطر النسبي دون مبالغة", "bodyEn": "For the training table, risk among salad eaters is 18/30 = 0.60 (60%); risk among non-eaters is 27/120 = 0.225 (22.5%). RR = 0.60/0.225 = 2.6667, reported as 2.67. The correct interpretation is that the observed risk over the specified outbreak period was 2.67 times as high among eaters. It is not a 267-percentage-point increase, and it does not mean 267% of exposed people became ill. Always report both component risks, the follow-up period, and the number of people in each group. A ratio can look dramatic while the absolute difference is small, or look modest while the population burden is substantial.", "bodyAr": "في جدول التدريب، خطر المرض بين آكلي السلطة هو 18/30 = 0.60 (60%)؛ وبين غير الآكلين 27/120 = 0.225 (22.5%). الخطر النسبي = 0.60/0.225 = 2.6667، ويُعرض 2.67. التفسير الصحيح أن الخطر المرصود خلال فترة الفاشية المحددة كان أعلى بمقدار 2.67 مرة لدى الآكلين. لا يعني ذلك زيادة قدرها 267 نقطة مئوية، ولا يعني أن 267% من المعرضين مرضوا. اعرض دائماً الخطرين المكوّنين وفترة المتابعة وعدد الأشخاص في كل مجموعة. قد تبدو النسبة كبيرة بينما يكون الفرق المطلق صغيراً، أو تبدو متواضعة بينما يكون العبء السكاني كبيراً."}, {"titleEn": "Design determines which measure is estimable", "titleAr": "تصميم الدراسة يحدد المقياس القابل للتقدير", "bodyEn": "In a cohort study, investigators identify exposed and unexposed groups and observe new outcomes; with valid denominators and follow-up, risks and RR can be estimated. In a randomized trial, random allocation can support a causal treatment contrast when allocation is preserved and outcome ascertainment is adequate. In a conventional case-control study, participants are sampled according to outcome status; the sampled case and control totals are set by design, so risks and RR cannot ordinarily be calculated from those totals. The odds ratio is the usual association measure, provided controls represent the exposure distribution in the source population that produced the cases. A nested case-control or incidence-density sampling design has additional interpretation: its odds ratio can estimate an incidence rate ratio under the relevant sampling scheme.", "bodyAr": "في الدراسة الأترابية، يحدد الباحثون مجموعتي المعرضين وغير المعرضين ثم يرصدون النتائج الجديدة؛ ومع صحة المقامات والمتابعة يمكن تقدير المخاطر والخطر النسبي. وفي التجربة العشوائية قد يدعم التوزيع العشوائي مقارنة سببية للتدخل إذا حُفظ التوزيع وكان رصد النتائج كافياً. أما في دراسة الحالات والشواهد التقليدية، فيُختار المشاركون بحسب حالة النتيجة؛ وتُحدد أعداد الحالات والشواهد وفق التصميم، لذلك لا يمكن عادة حساب المخاطر والخطر النسبي من هذه الأعداد. وتكون نسبة الأرجحية مقياس الارتباط المعتاد بشرط أن تمثل الشواهد توزيع التعرض في المجتمع المصدر الذي نشأت منه الحالات. وفي دراسة الحالات والشواهد المتداخلة أو المعاينة بكثافة الحدوث توجد دلالة إضافية: فقد تقدر نسبة الأرجحية نسبة معدلات الحدوث وفق آلية المعاينة المناسبة."}, {"titleEn": "Field decision and uncertainty", "titleAr": "القرار الميداني وعدم اليقين", "bodyEn": "An RR above 1 is a signal for investigation, not a verdict that exposure caused disease. In the canteen example, the team should preserve the line list, verify onset dates and food histories, inspect food preparation, and compare other menu items. It should check whether salad eaters differed in age, attendance time, or consumption of other foods. Small groups create imprecision; a point estimate alone does not show uncertainty. Where feasible, calculate a confidence interval using an appropriate method and interpret it alongside design limitations, missing data, and the plausibility of the exposure pathway. Immediate proportionate control measures need not wait for causal certainty when the potential harm is serious.", "bodyAr": "الخطر النسبي الأكبر من 1 إشارة تستدعي التقصي، وليس حكماً بأن التعرض سبب المرض. في مثال المقصف، ينبغي للفريق حفظ قائمة الحالات والتحقق من تواريخ البدء وتاريخ تناول الطعام وفحص تحضير السلطة ومقارنة بقية أصناف القائمة. كما ينبغي فحص ما إذا كان آكلو السلطة يختلفون في العمر أو وقت الحضور أو تناول أطعمة أخرى. تؤدي المجموعات الصغيرة إلى عدم دقة؛ والتقدير النقطي وحده لا يوضح عدم اليقين. وحيثما أمكن، احسب فترة ثقة بطريقة مناسبة وفسرها مع حدود التصميم والبيانات المفقودة ومعقولية مسار التعرض. ولا يلزم تأخير تدابير السيطرة المتناسبة والعاجلة حتى يتحقق اليقين السببي إذا كان الضرر المحتمل جسيماً."}], "objEn": ["Build a 2×2 table with exposure in rows and outcome in columns.", "Calculate risk in exposed and unexposed groups.", "Calculate and interpret RR in plain language."], "objAr": ["بناء جدول 2×2 بالتعرض في الصفوف والنتيجة في الأعمدة.", "حساب الخطر في المعرضين وغير المعرضين.", "حساب الخطر النسبي وتفسيره بلغة بسيطة."]}', '[{"qEn": "Risk in the exposed group here is…", "qAr": "الخطر في المجموعة المعرضة هنا هو…", "optsEn": ["60%", "18%", "22.5%"], "optsAr": ["60%", "18%", "22.5%"], "ans": 0, "explEn": "18 ÷ 30 = 0.60 = 60%.", "explAr": "18 ÷ 30 = 0.60 = 60%."}, {"qEn": "RR = 2.67 means…", "qAr": "الخطر النسبي 2.67 يعني…", "optsEn": ["267% of exposed people became ill", "Risk was 2.67 times higher in the exposed group", "No one in the unexposed group became ill"], "optsAr": ["267% من المعرضين مرضوا", "الخطر أعلى 2.67 ضعف لدى المعرضين", "لم يمرض أحد من غير المعرضين"], "ans": 1, "explEn": "RR is a ratio of two risks, not a percentage of people.", "explAr": "الخطر النسبي نسبة بين خطرين، لا نسبة مئوية من الناس."}, {"qEn": "In a 2×2 table, “a” is…", "qAr": "في جدول 2×2، «أ» هي…", "optsEn": ["Unexposed non-cases", "Total population", "Exposed cases"], "optsAr": ["غير حالات غير معرضة", "إجمالي السكان", "حالات معرضة"], "ans": 2, "explEn": "a = exposed cases; b = exposed non-cases; c = unexposed cases; d = unexposed non-cases.", "explAr": "أ = حالات معرضة؛ ب = غير حالات معرضة؛ ج = حالات غير معرضة؛ د = غير حالات غير معرضة."}, {"qEn": "RR = 1 means…", "qAr": "الخطر النسبي = 1 يعني…", "optsEn": ["Equal risk in both groups", "No one became ill", "The exposure prevents all illness"], "optsAr": ["خطرا متساويا في المجموعتين", "لم يمرض أحد", "التعرض يمنع كل المرض"], "ans": 0, "explEn": "RR 1 means the two risks are equal.", "explAr": "الخطر النسبي 1 يعني أن الخطرين متساويان."}]' FROM courses WHERE course_code='B-105';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 2, 'نسبة الأرجحية وفرق الخطر', 'Odds ratio and risk difference', '[''حساب نسبة الأرجحية كـ أ د / ب ج وفرق الخطر كفرق الخطرين.'', ''شرح متى تقترب نسبة الأرجحية من الخطر النسبي.'', ''الاختيار بين الخطر النسبي ونسبة الأرجحية وفرق الخطر حسب السؤال.'']', '[''Calculate OR as ad/bc and RD as risk difference.'', ''Explain when OR approximates RR.'', ''Choose between RR, OR and RD for a given question.'']', 'الأرجحية هي الحالات مقسومة على غير الحالات في مجموعة — مختلفة عن الخطر الذي يقسم على المجموعة كلها. نسبة الأرجحية = (أ×د) ÷ (ب×ج). وفرق الخطر = خطر المعرضين ناقص خطر غير المعرضين، بنقاط مئوية. الخطر النسبي ونسبة الأرجحية يجيبان عن «كم ضعفا أعلى؟» وفرق الخطر يجيب عن «كم حالة إضافية لكل 100 شخص؟» تقريب النتيجة النادرة قاعدة إرشادية لا قانونًا عامًا بحد 10%: عندما يكون خطر النتيجة منخفضًا في مجموعتي المقارنة، تتقارب الأرجحية والخطر عدديًا، وقد تقترب نسبة الأرجحية من الخطر النسبي. وكلما شاعت النتيجة، قد تبتعد نسبة الأرجحية عن 1 أكثر بكثير من الخطر النسبي؛ ففي مثال السلطة الخطر النسبي = 2.67 ونسبة الأرجحية = 5.17، وهذا ليس خطأ حسابيًا. في دراسة الحالات والشواهد التقليدية يحدد الباحث عدد الحالات والشواهد أو يسحبها بالعينة؛ لذلك لا يمكن قراءة المخاطر أو فروق المخاطر مباشرة من هذه الأعداد المختارة. ويمكن عادة تقدير نسبة الأرجحية إذا كانت الشواهد تمثل توزيع التعرض في المجتمع المصدر الذي نشأت منه الحالات. فرق الخطر مقارنة مطلقة ويجب عرضه بنقاط مئوية (وعند الحاجة حالات زائدة لكل 100 أو 1000 شخص) خلال فترة المتابعة نفسها. وفي الدراسات الأترابية والتجارب: فرق الخطر = خطر المعرضين − خطر غير المعرضين؛ وتتوقف إشارته على ترتيب الطرح.', 'Odds are cases divided by non-cases in a group — different from risk, which divides by the whole group. Odds ratio (OR) = (a×d) ÷ (b×c). Risk difference (RD) = risk in exposed minus risk in unexposed, in percentage points. RR and OR answer “how many times higher?” RD answers “how many extra cases per 100 people?” The rare-outcome approximation is a rule of thumb, not a universal 10% law: when the outcome risk is low in both comparison groups, odds and risks are numerically similar, so OR may approximate RR. As the outcome becomes common, OR can be materially farther from 1 than RR; in this salad example RR = 2.67 but OR = 5.17. That is not a calculation error. In a conventional case-control study, the investigator fixes or samples the number of cases and controls, so risks and risk differences cannot be read directly from those sampled totals; OR is generally estimable when controls represent the exposure distribution in the source population that generated the cases. RD is an absolute contrast and must be reported in percentage points (and, where useful, excess cases per 100 or 1,000 people) over the same follow-up horizon. For cohort studies and trials, RD = risk exposed − risk unexposed; its sign depends on which group is subtracted first.', '{"exampleEn": "Field case — A case-control study of a rare illness finds OR 3.1. Because the illness is rare, the team reads OR as roughly RR 3.1. In the salad outbreak, illness was common, so the team does not do that: it reports RR 2.67 for “how many times higher” and RD 37.5 points for “how many extra cases per 100 salad eaters.” The RD, not the ratio, drives the decision about how many people to warn.", "exampleAr": "حالة ميدانية — دراسة حالات وشواهد لمرض نادر تجد نسبة أرجحية 3.1. ولأن المرض نادر، يقرأ الفريق نسبة الأرجحية تقريبا كخطر نسبي 3.1. وفي فاشية السلطة، كان المرض شائعا، لذا لا يفعل الفريق ذلك: يبلغ عن الخطر النسبي 2.67 لـ «كم ضعفا أعلى» وعن فرق الخطر 37.5 نقطة لـ «كم حالة إضافية لكل 100 آكل سلطة». فرق الخطر، لا النسبة، هو ما يقود قرار كم شخصا يجب تحذيرهم.", "fieldEn": "If a report gives only OR for a common outcome, ask for the two risks and the RD before you act on it.", "fieldAr": "إذا أعطى تقرير نسبة أرجحية فقط لنتيجة شائعة، اطلب الخطرين وفرق الخطر قبل أن تتصرف بناء عليه.", "calcTitleEn": "Worked calculation — OR and RD from the same table", "calcTitleAr": "حساب محلول — نسبة الأرجحية وفرق الخطر من نفس الجدول", "calcStepsEn": ["Step 1 — Table: a=18, b=12, c=27, d=93.", "Step 2 — OR: (18 × 93) ÷ (12 × 27) = 1,674 ÷ 324 = 5.17.", "Step 3 — Risks: exposed 60%, unexposed 22.5%.", "Step 4 — RD: 60% − 22.5% = 37.5 percentage points."], "calcStepsAr": ["الخطوة 1 — الجدول: أ=18، ب=12، ج=27، د=93.", "الخطوة 2 — نسبة الأرجحية: (18 × 93) ÷ (12 × 27) = 1674 ÷ 324 = 5.17.", "الخطوة 3 — الخطر: المعرضون 60%، غير المعرضين 22.5%.", "الخطوة 4 — فرق الخطر: 60% − 22.5% = 37.5 نقطة مئوية."], "calcResultEn": "Result: OR = 5.17, RD = 37.5 percentage points, RR = 2.67. Same table, three answers to three questions. Because illness was common (60% in exposed), OR is much larger than RR — report both, and do not read OR as RR.", "calcResultAr": "النتيجة: نسبة الأرجحية = 5.17، فرق الخطر = 37.5 نقطة مئوية، الخطر النسبي = 2.67. نفس الجدول، ثلاث إجابات لثلاثة أسئلة. ولأن المرض كان شائعا (60% لدى المعرضين)، نسبة الأرجحية أكبر بكثير من الخطر النسبي — أبلغ عن كليهما، ولا تقرأ نسبة الأرجحية كخطر نسبي.", "terms": [{"termEn": "Odds", "termAr": "الأرجحية", "defEn": "Cases divided by non-cases in a group.", "defAr": "الحالات مقسومة على غير الحالات في مجموعة."}, {"termEn": "Odds ratio (OR)", "termAr": "نسبة الأرجحية", "defEn": "(a×d) ÷ (b×c). Compares odds between groups.", "defAr": "(أ×د) ÷ (ب×ج). تقارن الأرجحية بين المجموعتين."}, {"termEn": "Risk difference (RD)", "termAr": "فرق الخطر", "defEn": "Risk exposed minus risk unexposed, in percentage points.", "defAr": "خطر المعرضين ناقص خطر غير المعرضين، بنقاط مئوية."}, {"termEn": "Rare-outcome rule", "termAr": "قاعدة النتيجة النادرة", "defEn": "A useful approximation when outcome risk is low in both groups; not an exact threshold or a universal identity.", "defAr": "تقريب مفيد عندما يكون خطر النتيجة منخفضًا في المجموعتين؛ وليس حدًا فاصلًا دقيقًا أو تطابقًا عامًا."}], "deepSections": [{"titleEn": "Risk, odds and the cross-product", "titleAr": "الخطر والأرجحية والضرب التبادلي", "bodyEn": "Risk is cases divided by all people in the group. Odds are cases divided by non-cases. For exposed participants, odds = a/b; for unexposed participants, odds = c/d. The odds ratio is (a/b)/(c/d) = ad/bc. In the salad table, exposed odds = 18/12 = 1.5; unexposed odds = 27/93 = 0.2903; OR = 1.5/0.2903 = 5.17. The cross-product formula is convenient, but only after the row and column orientation is verified. If cells are rearranged, the reciprocal or a different contrast may result. Label the table before inserting numbers, and state which group is the reference.", "bodyAr": "الخطر هو الحالات مقسومة على جميع أفراد المجموعة. أما الأرجحية فهي الحالات مقسومة على غير الحالات. أرجحية المعرضين = أ/ب؛ وأرجحية غير المعرضين = ج/د. نسبة الأرجحية = (أ/ب)/(ج/د) = أ د/ب ج. في جدول السلطة، أرجحية المعرضين = 18/12 = 1.5؛ وأرجحية غير المعرضين = 27/93 = 0.2903؛ ونسبة الأرجحية = 1.5/0.2903 = 5.17. صيغة الضرب التبادلي مريحة، لكن لا تستخدم إلا بعد التحقق من اتجاه الصفوف والأعمدة. قد يؤدي تبديل الخلايا إلى النسبة المقلوبة أو إلى مقارنة مختلفة. سمِّ خلايا الجدول قبل إدخال الأرقام وحدد المجموعة المرجعية."}, {"titleEn": "Why the odds ratio can look larger", "titleAr": "لماذا قد تبدو نسبة الأرجحية أكبر", "bodyEn": "The OR and RR are not interchangeable. In the same table RR = 2.67 while OR = 5.17 because the outcome is common: 60% in the exposed group and 22.5% in the unexposed group. When outcome risks are low in both groups, odds and risks are numerically close and OR may approximate RR. There is no universal threshold that makes the approximation automatically safe; assess the actual risks and the study design. For common outcomes, describing OR 5.17 as “5.17 times the risk” is incorrect. Say “5.17 times the odds.” If readers need an absolute interpretation, provide risks from a cohort or trial with valid denominators, or present standardized predicted risks from an appropriate model.", "bodyAr": "نسبة الأرجحية والخطر النسبي ليسا مقياساً واحداً. في الجدول نفسه الخطر النسبي = 2.67 بينما نسبة الأرجحية = 5.17 لأن النتيجة شائعة: 60% لدى المعرضين و22.5% لدى غير المعرضين. عندما تكون مخاطر النتيجة منخفضة في المجموعتين، تتقارب الأرجحية والمخاطر عددياً وقد تقارب نسبة الأرجحية الخطر النسبي. لا توجد عتبة عالمية تجعل هذا التقريب آمناً تلقائياً؛ بل قيّم المخاطر الفعلية وتصميم الدراسة. عند شيوع النتيجة، يكون وصف نسبة الأرجحية 5.17 بأنها «5.17 ضعف الخطر» خطأ. قل «5.17 ضعف الأرجحية». وإذا احتاج القارئ تفسيراً مطلقاً، فاعرض المخاطر من دراسة أترابية أو تجربة ذات مقامات صحيحة، أو المخاطر المتوقعة المعيارية من نموذج مناسب."}, {"titleEn": "Absolute risk difference", "titleAr": "فرق الخطر المطلق", "bodyEn": "Risk difference (RD) = risk exposed − risk unexposed = 0.60 − 0.225 = 0.375, or +37.5 percentage points over the outbreak period. This corresponds to 37.5 additional cases per 100 exposed people compared with the unexposed risk, if the contrast is valid. The sign depends on subtraction order; reversing the groups gives −37.5 percentage points. RD communicates absolute impact and is sensitive to baseline risk. Report the time horizon and avoid confusing a 37.5 percentage-point difference with a 37.5% relative increase. A useful report presents risks, RR or OR as appropriate, and RD when estimable.", "bodyAr": "فرق الخطر = خطر المعرضين − خطر غير المعرضين = 0.60 − 0.225 = 0.375، أي +37.5 نقطة مئوية خلال فترة الفاشية. ويعادل ذلك 37.5 حالة إضافية لكل 100 شخص معرض مقارنة بخطر غير المعرضين، إذا كانت المقارنة صالحة. وتتوقف الإشارة على ترتيب الطرح؛ فعكس المجموعتين يعطي −37.5 نقطة مئوية. يوضح فرق الخطر الأثر المطلق ويتأثر بالخطر الأساسي. اذكر الأفق الزمني ولا تخلط بين فرق 37.5 نقطة مئوية وزيادة نسبية قدرها 37.5%. ويعرض التقرير الجيد المخاطر والخطر النسبي أو نسبة الأرجحية بحسب التصميم، وفرق الخطر عندما يكون قابلاً للتقدير."}, {"titleEn": "Case-control interpretation and reporting", "titleAr": "تفسير دراسة الحالات والشواهد والإبلاغ عنها", "bodyEn": "Suppose investigators enrol 100 people with illness and 100 without illness, then compare prior exposure. Because the investigator chose the number of cases and controls, 100/200 is not the population risk and cannot be used as an attack rate. The OR compares exposure odds among cases with exposure odds among controls. Its validity depends on appropriate control selection, comparable exposure measurement, and avoiding selection and information bias. Report the case definition, source population, control-selection method, exposure window, adjusted and crude estimates where relevant, and limitations. Do not convert a case-control OR into an absolute risk without external baseline-risk information and a justified model.", "bodyAr": "لنفترض أن الباحثين ضمّوا 100 شخص مصاب و100 غير مصاب ثم قارنوا التعرض السابق. لأن الباحث اختار عدد الحالات والشواهد، فإن 100/200 ليس خطر المجتمع ولا يجوز استخدامه كمعدل هجوم. تقارن نسبة الأرجحية أرجحية التعرض بين الحالات وأرجحية التعرض بين الشواهد. وتعتمد صلاحيتها على اختيار الشواهد بصورة مناسبة وقياس التعرض بصورة قابلة للمقارنة وتجنب تحيز الاختيار والمعلومات. أبلغ عن تعريف الحالة والمجتمع المصدر وطريقة اختيار الشواهد ونافذة التعرض والتقديرات الخام والمعدلة عند اللزوم والقيود. لا تحوّل نسبة أرجحية من دراسة حالات وشواهد إلى خطر مطلق دون معلومات خارجية عن الخطر الأساسي ونموذج مبرر."}], "objEn": ["Calculate OR as ad/bc and RD as risk difference.", "Explain when OR approximates RR.", "Choose between RR, OR and RD for a given question."], "objAr": ["حساب نسبة الأرجحية كـ أ د / ب ج وفرق الخطر كفرق الخطرين.", "شرح متى تقترب نسبة الأرجحية من الخطر النسبي.", "الاختيار بين الخطر النسبي ونسبة الأرجحية وفرق الخطر حسب السؤال."]}', '[{"qEn": "OR from a=18, b=12, c=27, d=93 is…", "qAr": "نسبة الأرجحية من أ=18، ب=12، ج=27، د=93 هي…", "optsEn": ["2.67", "5.17", "37.5"], "optsAr": ["2.67", "5.17", "37.5"], "ans": 1, "explEn": "(18×93) ÷ (12×27) = 1,674 ÷ 324 = 5.17.", "explAr": "(18×93) ÷ (12×27) = 1674 ÷ 324 = 5.17."}, {"qEn": "RD here is…", "qAr": "فرق الخطر هنا هو…", "optsEn": ["2.67 times", "5.17 times", "37.5 percentage points"], "optsAr": ["2.67 ضعف", "5.17 ضعف", "37.5 نقطة مئوية"], "ans": 2, "explEn": "60% − 22.5% = 37.5 percentage points.", "explAr": "60% − 22.5% = 37.5 نقطة مئوية."}, {"qEn": "OR approximates RR when…", "qAr": "تقترب نسبة الأرجحية من الخطر النسبي عندما…", "optsEn": ["The outcome is rare", "The outcome is common", "The sample is large"], "optsAr": ["تكون النتيجة نادرة", "تكون النتيجة شائعة", "تكون العينة كبيرة"], "ans": 0, "explEn": "With a rare outcome, odds ≈ risk, so OR ≈ RR.", "explAr": "مع نتيجة نادرة، الأرجحية ≈ الخطر، لذا نسبة الأرجحية ≈ الخطر النسبي."}, {"qEn": "In a case-control study, OR is natural because…", "qAr": "في دراسة الحالات والشواهد، نسبة الأرجحية طبيعية لأن…", "optsEn": ["RR is always wrong", "Risk cannot be calculated directly from sampled controls", "Counts are not needed"], "optsAr": ["الخطر النسبي دائما خاطئ", "لا يمكن حساب الخطر مباشرة من شواهد مأخوذة بالعينة", "الأعداد غير لازمة"], "ans": 1, "explEn": "Controls were sampled, so the denominators for risk are not the true population.", "explAr": "الشواهد أُخذت بالعينة، لذا مقامات الخطر ليست السكان الحقيقيين."}]' FROM courses WHERE course_code='B-105';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 3, 'الكسر المنسوب والكسر المنسوب السكاني وعدد المعالجة اللازم', 'Attributable fraction, PAF and NNT', '[''حساب الكسر المنسوب لدى المعرضين من الخطر النسبي.'', ''شرح الكسر المنسوب السكاني بلغة بسيطة.'', ''حساب عدد المعالجة اللازم من فرق الخطر وشرح حدوده.'']', '[''Calculate attributable fraction in the exposed from RR.'', ''Explain PAF in plain language.'', ''Calculate NNT from RD and explain its limits.'']', 'الخطر النسبي يخبرك كم ضعفا أعلى الخطر. ومقاييس الأثر تسأل سؤالا مختلفا: كم من المرض يمكن إزالته لو أُزيل التعرض؟ الكسر المنسوب لدى المعرضين = (الخطر النسبي − 1) ÷ الخطر النسبي. وهو حصة الحالات بين المعرضين «المنسوبة» إلى التعرض — تحت افتراض قوي أن الارتباط سببي وأن إزالة التعرض تزيل تلك الحصة. ويقدّر الكسر المنسوب السكاني حصة الحالات في جميع السكان التي يمكن منعها لو أزيل التعرض، وفق نموذج سببي. للتعرض الثنائي البسيط ومع افتراض خطر نسبي سببي مشترك: الكسر المنسوب السكاني = [نسبة التعرض في جميع السكان × (الخطر النسبي − 1)] ÷ [1 + نسبة التعرض في جميع السكان × (الخطر النسبي − 1)]. ويمكن حسابه أيضًا = (خطر السكان − خطر غير المعرضين) ÷ خطر السكان عندما تكون المخاطر مقدرة بصورة صحيحة. تتطلب هذه الصيغ مقارنة سببية صالحة وقياسًا صحيحًا لشيوع التعرض وضبط الإرباك والتحيز؛ ولا تستبدل انتشار المرض بنسبة التعرض. عدد المعالجة اللازم مقياس لتدخل علاجي/وقائي: عدد المعالجة اللازم = 1 ÷ الانخفاض المطلق في الخطر، حيث الانخفاض المطلق = خطر مجموعة الضبط − خطر مجموعة التدخل خلال فترة متابعة محددة، مع مجموعتين قابلتين للمقارنة ونتيجة نافعة محددة. يُقرب العدد إلى العدد الصحيح الأعلى، ويجب ذكر النتيجة والفترة؛ ويتغير العدد بتغير الخطر الأساسي ومدة المتابعة. لا تسمِّ 1/فرق الخطر في جدول السلطة الرصدي الضار «عدد المعالجة اللازم»؛ فالجدول يقدّر زيادة مرتبطة بالتعرض، لا فائدة علاجية من تجربة عشوائية. تتطلب الكسور المنسوبة تفسيرًا سببيًا يمكن الدفاع عنه؛ فالارتباط وحده لا يثبت السببية.', 'RR tells you how many times higher the risk is. Impact measures ask a different question: how much of the illness could be removed if the exposure were removed? Attributable fraction in the exposed (AFexp) = (RR − 1) ÷ RR. It is the share of cases among exposed people that is “attributable” to the exposure — under the strong assumption that the association is causal and that removing the exposure removes that share. Population attributable fraction (PAF) estimates the share of all cases in the population that would be prevented if the exposure were removed, under a causal model. For a simple binary exposure with a common causal RR, PAF = Pe(RR − 1) ÷ [1 + Pe(RR − 1)], where Pe is the proportion of the whole source population exposed; alternatively PAF = (Ipopulation − Iunexposed) ÷ Ipopulation when those risks are validly estimated. These formulae require a valid causal contrast, correct exposure prevalence and adequate control of confounding and bias. Do not substitute the disease prevalence for Pe. NNT is a treatment/intervention measure: NNT = 1 ÷ ARR, where ARR = risk in control − risk in intervention over a stated follow-up period, using comparable groups and a clearly defined beneficial outcome. Round NNT up to the next whole person and report the outcome and time horizon; NNT changes with baseline risk and follow-up. Do not call 1/RD from this harmful observational salad-exposure table an NNT. That table estimates an exposure-associated excess risk, not a randomized treatment benefit. All attributable fractions require a defensible causal interpretation; association alone does not prove causation.', '{"exampleEn": "Field case — A town considers removing one exposure that has RR 2.67 but is rare: only 5% of people are exposed. AFexp is 62.5%, but PAF for the whole town is much smaller, because few people are exposed. The team therefore reports both: a large share among the exposed, a small share in the whole population. The decision weighs how common the exposure is, not only how strong the RR is.", "exampleAr": "حالة ميدانية — بلدة تفكر في إزالة تعرض واحد خطره النسبي 2.67 لكنه نادر: 5% فقط من الناس معرضون. الكسر المنسوب لدى المعرضين 62.5%، لكن الكسر المنسوب السكاني لكل البلدة أصغر بكثير، لأن قلة معرضون. لذا يبلغ الفريق عن كليهما: حصة كبيرة بين المعرضين، وحصة صغيرة في كل السكان. القرار يزن مدى شيوع التعرض، لا قوة الخطر النسبي فقط.", "fieldEn": "Never report AF or PAF without saying “if causal.” For NNT, name the intervention, comparator, beneficial outcome and follow-up period; calculate it from absolute risk reduction in a valid intervention comparison, not from an observational harmful exposure table.", "fieldAr": "لا تبلغ عن الكسر المنسوب أو السكاني من دون قول «إذا كان سببيًا». وعند عرض عدد المعالجة اللازم، سمِّ التدخل والمقارن والنتيجة النافعة وفترة المتابعة؛ واحسبه من الانخفاض المطلق في الخطر في مقارنة تدخل صالحة، لا من جدول رصدي لتعرض ضار.", "calcTitleEn": "Worked calculation — AFexp, PAF and a separate trial NNT", "calcTitleAr": "حساب محلول — الكسر المنسوب لدى المعرضين والسكاني وعدد المعالجة في تجربة منفصلة", "calcStepsEn": ["Step 1 — Salad table: exposed risk = 18/30 = 0.60; unexposed risk = 27/120 = 0.225; RR = 0.60/0.225 = 2.67.", "Step 2 — AFexp = (RR−1)/RR = (2.67−1)/2.67 = 0.625 = 62.5%, if the association is causal.", "Step 3 — Exposure prevalence Pe = 30/150 = 0.20. PAF = Pe(RR−1)/[1+Pe(RR−1)] = 0.20×1.67/[1+0.20×1.67] = 0.25 = 25%, if causal and model assumptions hold.", "Step 4 — Separate one-year trial example: control risk 20%, intervention risk 15%; ARR = 0.20−0.15 = 0.05. NNT = 1/0.05 = 20 people treated for one year to prevent one additional event, on average. This is not calculated from the salad exposure table."], "calcStepsAr": ["الخطوة 1 — جدول السلطة: خطر المعرضين = 18/30 = 0.60؛ خطر غير المعرضين = 27/120 = 0.225؛ الخطر النسبي = 0.60/0.225 = 2.67.", "الخطوة 2 — الكسر المنسوب لدى المعرضين = (الخطر النسبي−1)/الخطر النسبي = (2.67−1)/2.67 = 0.625 = 62.5%، إذا كان الارتباط سببيًا.", "الخطوة 3 — نسبة التعرض في السكان = 30/150 = 0.20. الكسر المنسوب السكاني = [0.20×1.67]/[1+0.20×1.67] = 0.25 = 25%، إذا صحت السببية وافتراضات النموذج.", "الخطوة 4 — مثال منفصل لتجربة مدتها سنة: خطر مجموعة الضبط 20%، وخطر مجموعة التدخل 15%؛ الانخفاض المطلق = 0.20−0.15 = 0.05. عدد المعالجة اللازم = 1/0.05 = 20 شخصًا يعالجون سنة لمنع حدث إضافي واحد في المتوسط. لا يُحسب هذا من جدول التعرض للسلطة."], "calcResultEn": "Interpretation: AFexp 62.5% is the hypothetical attributable share among exposed people; PAF 25% is the hypothetical attributable share in the whole population, because only 20% were exposed. Neither is a causal fact unless confounding, selection and measurement bias are adequately addressed. The NNT example is a separate one-year intervention comparison: NNT 20, with the outcome and horizon stated. For the salad table, RD = +37.5 percentage points is an exposure-associated absolute excess risk; it is not an NNT.", "calcResultAr": "التفسير: الكسر المنسوب لدى المعرضين 62.5% هو الحصة الافتراضية المنسوبة بين المعرضين؛ والكسر المنسوب السكاني 25% هو الحصة الافتراضية في جميع السكان لأن 20% فقط تعرضوا. ولا يصبح أي منهما حقيقة سببية ما لم يُعالج الإرباك وتحيز الاختيار والقياس بما يكفي. مثال عدد المعالجة منفصل ويخص مقارنة تدخل لمدة سنة: العدد 20 مع ذكر النتيجة والفترة. أما جدول السلطة فيعطي فرق خطر مطلقًا مرتبطًا بالتعرض قدره +37.5 نقطة مئوية، وليس عدد معالجة لازمًا.", "terms": [{"termEn": "Attributable fraction in exposed (AFexp)", "termAr": "الكسر المنسوب لدى المعرضين", "defEn": "(RR − 1) ÷ RR. Share of exposed cases attributable to exposure, if causal.", "defAr": "(الخطر النسبي − 1) ÷ الخطر النسبي. حصة حالات المعرضين المنسوبة للتعرض، إذا كان سببيا."}, {"termEn": "Population attributable fraction (PAF)", "termAr": "الكسر المنسوب السكاني", "defEn": "Pe(RR−1) ÷ [1+Pe(RR−1)] in a simple binary-exposure model; Pe is exposure prevalence in the source population. Interpret causally only under valid assumptions.", "defAr": "[نسبة التعرض في السكان × (الخطر النسبي−1)] ÷ [1+نسبة التعرض في السكان × (الخطر النسبي−1)] في نموذج بسيط لتعرض ثنائي؛ ونسبة التعرض هي شيوعه في المجتمع المصدر. لا يفسر سببيًا إلا مع تحقق الافتراضات."}, {"termEn": "Number needed to treat (NNT)", "termAr": "عدد المعالجة اللازم", "defEn": "1 ÷ absolute risk reduction (control risk − intervention risk) over a stated follow-up; round up to a whole person.", "defAr": "1 ÷ الانخفاض المطلق في الخطر (خطر الضبط − خطر التدخل) خلال متابعة محددة؛ ويقرب إلى العدد الصحيح الأعلى."}, {"termEn": "Causal assumption", "termAr": "الافتراض السببي", "defEn": "Impact measures assume the association is causal.", "defAr": "مقاييس الأثر تفترض أن الارتباط سببي."}], "deepSections": [{"titleEn": "Attributable fractions require causal assumptions", "titleAr": "الكسور المنسوبة تتطلب افتراضات سببية", "bodyEn": "Among the exposed, the attributable fraction is (RR−1)/RR when the risk ratio is a valid causal contrast. With RR 2.67, AFexp = (2.67−1)/2.67 ≈ 0.625 (62.5%). This is not simply the proportion of exposed cases who reported the exposure; it estimates the fraction of outcome among exposed that would be prevented under a causal intervention removing the exposure, under assumptions. Population attributable fraction (PAF) also depends on exposure prevalence and a causal effect estimate. With Pe = 30/150 = 0.20, PAF = Pe(RR−1)/[1+Pe(RR−1)] = 0.25 (25%). These estimates require exchangeability/no uncontrolled confounding, consistency, positivity, correct measurement, and a well-defined intervention; observational association alone does not establish them.", "bodyAr": "الكسر المنسوب بين المعرضين هو (الخطر النسبي−1)/الخطر النسبي عندما تكون نسبة المخاطر مقارنة سببية صالحة. ومع خطر نسبي 2.67، يكون الكسر المنسوب = (2.67−1)/2.67 ≈ 0.625 (62.5%). لا يعني ذلك ببساطة نسبة الحالات المعرضة التي أبلغت عن التعرض؛ بل يقدّر الجزء من النتائج بين المعرضين الذي كان يمكن منعه بتدخل سببي يزيل التعرض، وفق افتراضات. ويعتمد الكسر المنسوب السكاني أيضاً على انتشار التعرض وتقدير الأثر السببي. ومع نسبة تعرض Pe = 30/150 = 0.20، يكون الكسر المنسوب السكاني = Pe(الخطر النسبي−1)/[1+Pe(الخطر النسبي−1)] = 0.25 (25%). تتطلب هذه التقديرات قابلية التبادل/غياب الإرباك غير المضبوط، والاتساق، والإيجابية، والقياس الصحيح، وتدخلاً محدد التعريف؛ فالارتباط الرصدي وحده لا يثبتها."}, {"titleEn": "NNT belongs to an intervention contrast", "titleAr": "عدد المعالجة اللازم يخص مقارنة تدخلية", "bodyEn": "Number needed to treat (NNT) is the reciprocal of an absolute risk reduction over a specified period, usually in a trial or a defensible causal treatment comparison. In a separate example, control risk is 20% and intervention risk is 15% over one year. Absolute risk reduction = 0.20−0.15 = 0.05; NNT = 1/0.05 = 20. This means treating 20 comparable people for one year rather than using the control strategy would prevent one additional outcome on average, under the trial conditions. If the value is not an integer, round NNT up to the next whole person. State outcome, time horizon, comparator, and uncertainty. Do not calculate NNT from the observational salad exposure table: salad eating is not a randomized treatment allocation and the causal assumptions are not established.", "bodyAr": "عدد المعالجة اللازم (NNT) هو مقلوب الانخفاض المطلق في الخطر خلال فترة محددة، وغالباً ما يستخدم في تجربة أو مقارنة علاجية سببية مبررة. في مثال منفصل، خطر مجموعة الضبط 20% وخطر التدخل 15% خلال سنة. الانخفاض المطلق في الخطر = 0.20−0.15 = 0.05؛ وعدد المعالجة اللازم = 1/0.05 = 20. يعني ذلك أن معالجة 20 شخصاً متشابهاً لمدة سنة بدلاً من استراتيجية الضبط تمنع نتيجة إضافية واحدة في المتوسط، ضمن ظروف التجربة. إذا لم تكن القيمة عدداً صحيحاً، فقرب NNT إلى العدد الصحيح الأعلى. اذكر النتيجة والأفق الزمني والمقارن وعدم اليقين. لا تحسب NNT من جدول التعرض للسلطة: فتناول السلطة ليس توزيعاً عشوائياً لعلاج، والافتراضات السببية غير مثبتة."}, {"titleEn": "Confounding, stratification and effect modification", "titleAr": "الإرباك والتقسيم الطبقي وتعديل الأثر", "bodyEn": "A crude association can differ from stratum-specific associations when a third variable is related to exposure and outcome but is not an intermediate on the causal pathway. Age is a common example: if older guests were more likely to eat a particular dish and also more likely to become ill, age may confound the crude association. Calculate risks within meaningful age strata, inspect whether stratum estimates are similar, and compare them with the crude estimate. A common adjusted estimate may be appropriate when effects are sufficiently homogeneous and assumptions hold. If stratum-specific effects genuinely differ, this may be effect modification rather than confounding; report the differences instead of hiding them in one pooled number. Stratification does not automatically remove unmeasured confounding or repair poor measurement.", "bodyAr": "قد يختلف الارتباط الخام عن الارتباطات داخل الطبقات عندما يرتبط متغير ثالث بالتعرض والنتيجة دون أن يكون وسيطاً في المسار السببي. العمر مثال شائع: إذا كان الضيوف الأكبر سناً أكثر احتمالاً لتناول صنف معين وأكثر عرضة للمرض أيضاً، فقد يربك العمر الارتباط الخام. احسب المخاطر داخل طبقات عمرية ذات معنى، وافحص مدى تشابه تقديرات الطبقات وقارنها بالتقدير الخام. قد يكون التقدير المعدل المشترك مناسباً عندما تكون التأثيرات متجانسة بما يكفي وتتحقق الافتراضات. وإذا اختلفت التأثيرات داخل الطبقات فعلاً، فقد يكون ذلك تعديلاً للأثر لا إرباكاً؛ اعرض الاختلافات بدلاً من إخفائها في رقم مجمع واحد. ولا يزيل التقسيم الطبقي تلقائياً الإرباك غير المقاس أو يصلح القياس الرديء."}, {"titleEn": "From estimates to a defensible public-health decision", "titleAr": "من التقديرات إلى قرار صحة عامة يمكن الدفاع عنه", "bodyEn": "A decision memo should separate what is observed, what is estimated, what is assumed, and what action is proposed. For the salad investigation: observed counts are 18/30 versus 27/120; estimated RR is 2.67, OR is 5.17, and RD is +37.5 percentage points. The outcome is common, so OR must not be described as RR. AFexp and PAF are conditional causal quantities, not proven preventable fractions. The team should combine epidemiologic measures with food histories, laboratory evidence, environmental inspection, timing, and operational feasibility. Record who owns each action, its deadline, and the evidence that will trigger review or reversal. Communicate uncertainty without delaying proportionate action to prevent ongoing exposure.", "bodyAr": "ينبغي لمذكرة القرار أن تفصل بين ما لوحظ وما قُدّر وما افتُرض والإجراء المقترح. في تقصي السلطة: الأعداد المرصودة 18/30 مقابل 27/120؛ والخطر النسبي المقدّر 2.67، ونسبة الأرجحية 5.17، وفرق الخطر +37.5 نقطة مئوية. النتيجة شائعة، لذلك لا يجوز وصف نسبة الأرجحية بأنها خطر نسبي. الكسر المنسوب لدى المعرضين والكسر المنسوب السكاني كميتان سببيتان مشروطتان وليستا كسوراً مثبتة قابلة للمنع. ينبغي للفريق دمج المقاييس الوبائية مع تاريخ الطعام والدليل المخبري والتفتيش البيئي والتوقيت والجدوى التشغيلية. وثّق المسؤول عن كل إجراء وموعده والدليل الذي سيؤدي إلى مراجعته أو إلغائه. تواصل بشأن عدم اليقين دون تأخير إجراء متناسب يمنع استمرار التعرض."}], "objEn": ["Calculate attributable fraction in the exposed from RR.", "Explain PAF in plain language.", "Calculate NNT from RD and explain its limits."], "objAr": ["حساب الكسر المنسوب لدى المعرضين من الخطر النسبي.", "شرح الكسر المنسوب السكاني بلغة بسيطة.", "حساب عدد المعالجة اللازم من فرق الخطر وشرح حدوده."]}', '[{"qEn": "AFexp when RR = 2.67 is…", "qAr": "الكسر المنسوب عندما يكون الخطر النسبي 2.67 هو…", "optsEn": ["37.5%", "267%", "62.5%"], "optsAr": ["37.5%", "267%", "62.5%"], "ans": 2, "explEn": "(2.67 − 1) ÷ 2.67 = 1.67 ÷ 2.67 = 0.625 = 62.5%.", "explAr": "(2.67 − 1) ÷ 2.67 = 1.67 ÷ 2.67 = 0.625 = 62.5%."}, {"qEn": "AFexp means…", "qAr": "الكسر المنسوب لدى المعرضين يعني…", "optsEn": ["Share of exposed cases attributable to exposure, if causal", "Share of all people who are exposed", "The number needed to treat"], "optsAr": ["حصة حالات المعرضين المنسوبة للتعرض، إذا كان سببيا", "حصة كل الناس المعرضين", "عدد المعالجة اللازم"], "ans": 0, "explEn": "AFexp is about cases among the exposed, under a causal assumption.", "explAr": "الكسر المنسوب لدى المعرضين يتعلق بحالات المعرضين، تحت افتراض سببي."}, {"qEn": "Why is NNT not calculated from the salad exposure table?", "qAr": "لماذا لا يُحسب عدد المعالجة اللازم من جدول التعرض للسلطة؟", "optsEn": ["Because RD cannot be calculated", "It is an observational exposure comparison, not a treatment-versus-control benefit comparison", "Because NNT has no time horizon"], "optsAr": ["لأن فرق الخطر لا يمكن حسابه", "لأنه مقارنة رصدية للتعرض وليست مقارنة فائدة بين علاج وضبط", "لأن عدد المعالجة اللازم لا يرتبط بفترة زمنية"], "ans": 1, "explEn": "NNT requires an intervention benefit contrast and a stated follow-up period; the salad table is a harmful exposure association.", "explAr": "يتطلب عدد المعالجة مقارنة فائدة لتدخل وفترة متابعة محددة؛ أما جدول السلطة فيقارن ارتباط تعرض ضار."}, {"qEn": "PAF is smaller than AFexp when…", "qAr": "الكسر المنسوب السكاني أصغر من الكسر المنسوب لدى المعرضين عندما…", "optsEn": ["Everyone is exposed", "RR equals 1", "The exposure is uncommon in the whole population"], "optsAr": ["يكون الجميع معرضين", "يكون الخطر النسبي = 1", "يكون التعرض غير شائع في كل السكان"], "ans": 2, "explEn": "PAF weighs AF by how common the exposure is in the population.", "explAr": "الكسر المنسوب السكاني يزن الكسر المنسوب بمدى شيوع التعرض في السكان."}]' FROM courses WHERE course_code='B-105';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 1, 'الشخص والمكان والزمان', 'Person, place and time', '[''بناء وصف الشخص والمكان والزمان من قائمة حالات.'', ''مقارنة أنماط العمر والجنس والمكان من دون القفز إلى السبب.'', ''تسمية ما يمكن أن يثبته النمط الوصفي وما لا يمكنه.'']', '[''Build a person-place-time description from a line list.'', ''Compare age, sex and place patterns without jumping to cause.'', ''Name what a descriptive pattern can and cannot prove.'']', 'علم الأوبئة الوصفي يبدأ بثلاثة أسئلة: من (العمر والجنس والمهنة والحالات الكامنة)، وأين (البيت والمدرسة والسوق والجناح ومصدر المياه)، ومتى (تاريخ بدء الأعراض والأسبوع والموسم). قائمة الحالات هي المادة الخام: صف واحد لكل حالة، بأعمدة الشخص والمكان والزمان. ومنها تصنع جداول بسيطة: الحالات حسب الفئة العمرية والجنس والحي والأسبوع. النمط دليل، لا حكم. إذا كانت أغلب الحالات أطفالا، فقد يعني ذلك تعرضا أعلى أو قابلية أعلى أو مجرد إبلاغ أفضل عن الأطفال. مهمتك في هذه المرحلة أن تصف بعناية وتولّد فرضية قابلة للاختبار — مثلا «الحالات متمركزة في حي واحد وعند أطفال دون 10» — لا أن تعلن السبب. قاعدة مهمة للمقام: نسبة الحالات المدرجة التي تسكن الشمال هي توزيع للحالات (50% من الحالات المبلّغ عنها)، وليست خطر المرض بين سكان الشمال. لمقارنة مخاطر الأحياء، اقسم حالات كل حي على سكانه المعرضين للخطر في المكان والفترة نفسيهما، وتحقق من تكافؤ اكتشاف الحالات.', 'Descriptive epidemiology starts with three questions: who (age, sex, occupation, underlying conditions), where (home, school, market, ward, water source), and when (onset date, week, season). A line list is the raw material: one row per case, with person, place and time columns. From it you make simple tables: cases by age group, by sex, by neighbourhood, by week. A pattern is a clue, not a verdict. If most cases are children, it may mean higher exposure, higher susceptibility, or simply better reporting in children. Your job at this stage is to describe carefully and to generate a testable hypothesis — for example, “cases are concentrated in one neighbourhood and in children under 10” — not to declare the cause. Important denominator rule: the percentage of all listed cases who live in North is a case distribution (50% of reported cases), not the risk of illness for North residents. To compare neighbourhood risks, divide cases in each neighbourhood by the corresponding population at risk for the same place and period, and assess whether case finding was comparable.', '{"exampleEn": "Field case — A town reports 90 cases. The line list shows 45 from North, 25 from East, 20 from South. Children under 10 are 40 of 90 cases. The team does not yet claim a cause. It writes a hypothesis: “Illness is concentrated in North and in young children.” It then checks water sources, schools and reporting routes in North, and asks whether children were tested more often than adults.", "exampleAr": "حالة ميدانية — بلدة تبلغ عن 90 حالة. قائمة الحالات تظهر 45 من الشمال و25 من الشرق و20 من الجنوب. والأطفال دون 10 هم 40 من 90 حالة. لا يدّعي الفريق سببا بعد. يكتب فرضية: «المرض متمركز في الشمال وعند الأطفال الصغار». ثم يتحقق من مصادر المياه والمدارس وطرق الإبلاغ في الشمال، ويسأل عما إذا كان الأطفال قد فُحصوا أكثر من البالغين.", "fieldEn": "Always attach a denominator to a place pattern. “Most cases are in North” means little until you know North''s population.", "fieldAr": "أرفق دائما مقاما بنمط المكان. «أغلب الحالات في الشمال» تعني القليل حتى تعرف سكان الشمال.", "calcTitleEn": "Worked calculation — share by place", "calcTitleAr": "حساب محلول — الحصة حسب المكان", "calcStepsEn": ["Step 1 — Total listed cases: 90.", "Step 2 — Listed cases from North: 45.", "Step 3 — Case distribution: 45 ÷ 90 = 0.50 = 50% of reported cases.", "Step 4 — Interpretation: this does not mean that 50% of North residents became ill. To calculate neighbourhood risk, obtain the population at risk in North and the other areas for the same period."], "calcStepsAr": ["الخطوة 1 — مجموع الحالات المدرجة: 90.", "الخطوة 2 — الحالات المدرجة من الشمال: 45.", "الخطوة 3 — توزيع الحالات: 45 ÷ 90 = 0.50 = 50% من الحالات المبلّغ عنها.", "الخطوة 4 — التفسير: لا يعني ذلك أن 50% من سكان الشمال مرضوا. لحساب خطر المرض في الحي، احصل على عدد السكان المعرضين للخطر في الشمال وبقية المناطق للفترة نفسها."], "calcResultEn": "Result: 50% of cases are from one neighbourhood. Before concluding North is “worse,” check denominators: does North hold 50% of the population, or far less? A share of cases without a share of population is only half the picture.", "calcResultAr": "النتيجة: 50% من الحالات من حي واحد. قبل أن تستنتج أن الشمال «أسوأ»، تحقق من المقامات: هل يضم الشمال 50% من السكان، أم أقل بكثير؟ حصة الحالات بلا حصة السكان هي نصف الصورة فقط.", "terms": [{"termEn": "Line list", "termAr": "قائمة الحالات", "defEn": "One row per case, with person, place, time and exposure columns.", "defAr": "صف واحد لكل حالة، بأعمدة الشخص والمكان والزمان والتعرض."}, {"termEn": "Person", "termAr": "الشخص", "defEn": "Who is affected: age, sex, occupation, risk factors.", "defAr": "من المصاب: العمر والجنس والمهنة وعوامل الخطر."}, {"termEn": "Place", "termAr": "المكان", "defEn": "Where cases live, work, eat or meet.", "defAr": "أين يعيش المصابون أو يعملون أو يأكلون أو يجتمعون."}, {"termEn": "Time", "termAr": "الزمان", "defEn": "When onset occurred: date, week, season.", "defAr": "متى بدأت الأعراض: التاريخ والأسبوع والموسم."}], "deepSections": [{"titleEn": "What descriptive epidemiology can and cannot establish", "titleAr": "ما الذي يستطيع علم الأوبئة الوصفي إثباته وما الذي لا يستطيع إثباته", "bodyEn": "Descriptive epidemiology characterizes the occurrence of health events by person, place and time. It answers who is affected, where events occur, when they occur, and how many are observed. It is often the first analytic step because it identifies clusters, groups with higher observed burden, changes over time, and questions that deserve formal testing. A descriptive pattern can generate a hypothesis, but it does not by itself establish that a suspected exposure caused the outcome. Avoid causal verbs such as “caused” when the data are descriptive only. State the population, case definition, observation period, data source and denominator for every comparison.", "bodyAr": "يصف علم الأوبئة الوصفي حدوث الأحداث الصحية بحسب الشخص والمكان والزمان. ويجيب عن: من المتأثر؟ وأين تقع الأحداث؟ ومتى تقع؟ وكم عدد الحالات المرصودة؟ وغالباً ما يكون الخطوة التحليلية الأولى لأنه يكشف التجمعات والفئات ذات العبء المرصود الأعلى والتغيرات الزمنية والأسئلة التي تستحق الاختبار. يمكن للنمط الوصفي أن يولّد فرضية، لكنه لا يثبت وحده أن تعرضاً مشتبهاً به سبّب النتيجة. تجنب ألفاظ السببية مثل «سبّب» عندما تكون البيانات وصفية فقط. اذكر السكان وتعريف الحالة وفترة الرصد ومصدر البيانات ومقام كل مقارنة."}, {"titleEn": "Person: describe the population, not just the cases", "titleAr": "الشخص: صف السكان لا الحالات وحدها", "bodyEn": "Useful person variables may include age, sex, occupation, pregnancy status when relevant, vaccination status, clinical severity and other ethically justified characteristics. Report counts and denominators together. If 12 cases occur among 100 children and 12 among 1,000 adults, the counts are equal but the proportions are not: 12% versus 1.2%, assuming those denominators represent the populations at risk. Age-specific rates or proportions can reveal patterns hidden by an overall total. Check missingness and category definitions before comparing groups. Do not infer individual risk from a group average or treat social categories as biological explanations without evidence.", "bodyAr": "قد تشمل متغيرات الشخص العمر والجنس والمهنة وحالة الحمل عند الصلة وحالة التطعيم وشدة المرض وخصائص أخرى مبررة أخلاقياً. اعرض الأعداد والمقامات معاً. إذا حدثت 12 حالة بين 100 طفل و12 حالة بين 1000 بالغ، فالعددان متساويان لكن النسبتين مختلفتان: 12% مقابل 1.2%، بافتراض أن المقامين يمثلان السكان المعرضين للخطر. قد تكشف النسب أو المعدلات الخاصة بالعمر أنماطاً يخفيها الإجمالي. تحقق من القيم المفقودة وتعريف الفئات قبل المقارنة. لا تستنتج خطر الفرد من متوسط المجموعة ولا تعامل الفئات الاجتماعية كتفسيرات بيولوجية دون دليل."}, {"titleEn": "Place: choose a meaningful geographic unit", "titleAr": "المكان: اختر وحدة جغرافية ذات معنى", "bodyEn": "Describe cases by the smallest geographic unit that is reliable, ethical and operationally useful: district, facility catchment, village or neighbourhood. A spot map can show locations, while a choropleth map usually displays a rate or proportion by area. Mapping raw counts can mislead because populous areas often have more cases even when individual risk is lower. Use denominators that match the same geographic boundary and period. Protect confidentiality: suppress or aggregate small cells when a map could identify individuals. A spatial cluster is a signal to investigate, not proof that a local source caused disease.", "bodyAr": "صف الحالات بأصغر وحدة جغرافية موثوقة وأخلاقية ومفيدة تشغيلياً: مديرية أو نطاق منشأة أو قرية أو حي. يمكن لخريطة النقاط إظهار المواقع، بينما تعرض الخريطة المساحية المتدرجة عادة معدلاً أو نسبة لكل منطقة. قد تضلل خرائط الأعداد الخام لأن المناطق المكتظة تسجل حالات أكثر حتى عندما يكون الخطر الفردي أقل. استخدم مقامات تطابق الحدود الجغرافية والفترة الزمنية نفسها. احمِ السرية بحجب الخلايا الصغيرة أو تجميعها إذا كانت الخريطة قد تكشف هوية الأفراد. التجمع المكاني إشارة للتقصي وليس دليلاً على أن مصدراً محلياً سبب المرض."}, {"titleEn": "Time: use the date that answers the question", "titleAr": "الزمان: استخدم التاريخ الذي يجيب عن السؤال", "bodyEn": "For outbreak description, symptom-onset date is often more epidemiologically informative than report date because reporting delays can distort the apparent timing. Record onset, diagnosis, specimen collection and notification dates separately when possible. A time series can reveal a rise, peak, decline, seasonality or an unusual deviation from baseline. Compare like with like: use consistent week definitions, case definitions and reporting completeness. A rise in notifications may reflect improved detection or backlog clearance rather than a true rise in incidence. Annotate changes in testing, case finding, reporting rules and interventions on the timeline.", "bodyAr": "في وصف الفاشيات، يكون تاريخ بدء الأعراض غالباً أكثر فائدة وبائية من تاريخ الإبلاغ لأن تأخر الإبلاغ قد يشوه التوقيت الظاهر. سجّل تواريخ البدء والتشخيص وجمع العينة والإخطار كلٌّ على حدة متى أمكن. قد تكشف السلسلة الزمنية ارتفاعاً أو ذروة أو انخفاضاً أو موسمية أو انحرافاً غير معتاد عن خط الأساس. قارن أشياء متشابهة: استخدم تعريفات أسبوعية وتعريفات حالات واكتمال إبلاغ متسقة. قد تعكس زيادة الإخطارات تحسّن الاكتشاف أو تصفية تراكم التقارير لا زيادة حقيقية في الحدوث. ضع علامات زمنية على تغيّرات الاختبار واكتشاف الحالات وقواعد الإبلاغ والتدخلات."}], "objEn": ["Build a person-place-time description from a line list.", "Compare age, sex and place patterns without jumping to cause.", "Name what a descriptive pattern can and cannot prove."], "objAr": ["بناء وصف الشخص والمكان والزمان من قائمة حالات.", "مقارنة أنماط العمر والجنس والمكان من دون القفز إلى السبب.", "تسمية ما يمكن أن يثبته النمط الوصفي وما لا يمكنه."]}', '[{"qEn": "45 of 90 cases from North is…", "qAr": "45 من 90 حالة من الشمال هي…", "optsEn": ["50%", "45%", "90%"], "optsAr": ["50%", "45%", "90%"], "ans": 0, "explEn": "45 ÷ 90 = 50% of listed cases. It is not a neighbourhood-specific risk without a population denominator.", "explAr": "45 ÷ 90 = 50% من الحالات المدرجة. ولا يمثل خطرًا خاصًا بالحي دون مقام سكاني."}, {"qEn": "A line list has…", "qAr": "قائمة الحالات فيها…", "optsEn": ["One row per town only", "One row per case", "No dates"], "optsAr": ["صف واحد لكل بلدة فقط", "صف واحد لكل حالة", "لا تواريخ"], "ans": 1, "explEn": "One row per case keeps person, place and time together.", "explAr": "صف واحد لكل حالة يبقي الشخص والمكان والزمان معا."}, {"qEn": "“Most cases are children” could also mean…", "qAr": "«أغلب الحالات أطفال» قد تعني أيضا…", "optsEn": ["Adults are immune forever", "Place does not matter", "Children were tested or reported more"], "optsAr": ["أن البالغين محصنون للأبد", "أن المكان لا يهم", "أن الأطفال فُحصوا أو أُبلغ عنهم أكثر"], "ans": 2, "explEn": "A descriptive pattern can reflect reporting, not only risk.", "explAr": "النمط الوصفي قد يعكس الإبلاغ، لا الخطر فقط."}, {"qEn": "The goal of description is to…", "qAr": "هدف الوصف هو أن…", "optsEn": ["Generate a testable hypothesis", "Prove the cause immediately", "Skip denominators"], "optsAr": ["توليد فرضية قابلة للاختبار", "إثبات السبب فورا", "تخطي المقامات"], "ans": 0, "explEn": "Description generates hypotheses; analytic comparison tests them.", "explAr": "الوصف يولّد الفرضيات؛ والمقارنة التحليلية تختبرها."}]' FROM courses WHERE course_code='B-106';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 2, 'المنحنيات الوبائية', 'Epidemic curves', '[''بناء منحنى وبائي من تواريخ بدء الأعراض.'', ''إيجاد الذروة وتاريخ البدء الوسيط.'', ''تفسير أنماط المصدر النقطي والمتتابع والمستمر.'']', '[''Construct an epidemic curve from onset dates.'', ''Find the peak and the median onset date.'', ''Interpret point-source, propagated and continuous patterns.'']', 'المنحنى الوبائي مدرج تكراري للحالات حسب تاريخ أو وقت بدء الأعراض (المحور الأفقي) وعدد الحالات (المحور الرأسي). اختر فواصل زمنية متساوية وقصيرة بما يكفي مقارنة بفترة الحضانة المشتبه بها؛ وتستخدم إرشادات CDC الميدانية غالبًا فواصل تقارب ربع إلى ثلث فترة الحضانة عندما تكون معروفة. استخدم تاريخ البدء لا تاريخ الإبلاغ، لأن تأخر الإبلاغ يشوّه التوقيت. الارتفاع الحاد يتبعه انخفاض تدريجي يتفق مع تعرض لمصدر نقطي خلال فترة قصيرة؛ وعادة تقع معظم الحالات ضمن فترة حضانة واحدة. وقد يشير الثبات أو الامتداد إلى مصدر مشترك مستمر، والقمم غير المنتظمة إلى تعرض متقطع، والموجات المتعاقبة إلى انتشار متتابع. هذه قرائن وليست تشخيصات؛ فالمنحنيات الواقعية قد تتداخل وتتأثر باكتشاف الحالات وتفاوت الحضانة وتأخر الإبلاغ. إذا كان العامل وفترة حضانته معروفين، استخدم توزيع تواريخ البدء كاملًا لتقدير نافذة تعرض محتملة؛ ولا تطرح متوسط فترة حضانة واحدة آليًا من تاريخ الذروة. علّم الحالات غير المعتادة والتدخلات وأي تغير في الترصد على المنحنى.', 'An epidemic curve is a histogram of cases by symptom-onset date or time (x-axis) and case count (y-axis). Choose equal time intervals that are sufficiently short relative to the suspected incubation period; CDC field guidance commonly uses intervals around one-fourth to one-third of that period when it is known. Use onset, not report date, because reporting delays distort timing. A sharp rise followed by a more gradual decline is consistent with a point-source exposure over a brief period; most cases usually occur within one incubation period. A plateau or prolonged pattern may suggest continuous common-source exposure; irregular peaks may suggest intermittent exposure; successive waves may suggest propagated spread. These are clues, not diagnoses: real curves overlap and are affected by case finding, incubation variability and reporting. If the agent and incubation distribution are known, use the full onset distribution to estimate a plausible exposure window; do not mechanically subtract one average incubation period from the peak. Mark unusual cases, interventions and changes in surveillance on the curve.', '{"exampleEn": "Field case — A school outbreak curve rises in three waves, each peak about 2 days after the previous one. The team reads this as propagated spread, not a single meal: it checks classroom contacts and isolation, rather than only the canteen. A second curve in a neighbouring village stays flat and high for three weeks. That continuous shape points to an ongoing water source, so the team inspects the supply instead of searching for one meal.", "exampleAr": "حالة ميدانية — منحنى فاشية مدرسية يرتفع على ثلاث موجات، كل ذروة بعد نحو يومين من السابقة. يقرأ الفريق هذا كانتشار متتابع، لا وجبة واحدة: يتحقق من مخالطي الفصول والعزل، لا من المقصف فقط. ومنحنى ثان في قرية مجاورة يبقى مسطحا ومرتفعا ثلاثة أسابيع. هذا الشكل المستمر يشير إلى مصدر مياه مستمر، لذا يفحص الفريق الإمداد بدلا من البحث عن وجبة واحدة.", "fieldEn": "Always label the curve''s axes, period and onset definition. A curve by report date can look like a second wave that never happened. Reference basis: CDC Field Epidemiology Manual, “Describing Epidemiologic Data”; CDC Quick-Learn, “Using an Epi Curve to Determine Mode of Spread.”", "fieldAr": "ضع دائما تسمية لمحوري المنحنى وفترته وتعريف بدئه. منحنى حسب تاريخ الإبلاغ قد يبدو كموجة ثانية لم تحدث أبدا. مرجع المراجعة: دليل CDC الميداني للوبائيات، «وصف البيانات الوبائية»؛ ودرس CDC «استخدام المنحنى الوبائي لتحديد نمط الانتشار».", "calcTitleEn": "Worked calculation — median onset and peak", "calcTitleAr": "حساب محلول — البدء الوسيط والذروة", "calcStepsEn": ["Step 1 — Cases by onset day: Day 1: 4, Day 2: 12, Day 3: 28, Day 4: 22; total = 66.", "Step 2 — Peak: Day 3 with 28 cases.", "Step 3 — For N = 66, the median positions are cases 33 and 34. Cumulative counts are 4 by Day 1, 16 by Day 2 and 44 by Day 3; both median cases fall on Day 3.", "Step 4 — Median onset interval = Day 3. The grouped data identify the day, not an exact median time within that day."], "calcStepsAr": ["الخطوة 1 — الحالات حسب يوم البدء: اليوم 1: أربع، اليوم 2: 12، اليوم 3: 28، اليوم 4: 22؛ المجموع 66.", "الخطوة 2 — الذروة: اليوم 3 وفيه 28 حالة.", "الخطوة 3 — عندما ن = 66، يقع الوسيط عند الحالتين 33 و34. التراكم 4 بنهاية اليوم 1، و16 بنهاية اليوم 2، و44 بنهاية اليوم 3؛ لذا تقع الحالتان في اليوم 3.", "الخطوة 4 — فترة بدء الوسيط هي اليوم 3. البيانات المجمعة تحدد اليوم ولا تحدد وقت الوسيط الدقيق داخله."], "calcResultEn": "Result: peak Day 3 and median onset Day 3. The curve is compatible with a brief common-source exposure, but the curve alone cannot establish the source or exposure time. Estimate a plausible exposure window using the known incubation-period distribution and the full onset pattern; do not mechanically count back from the peak.", "calcResultAr": "النتيجة: الذروة في اليوم 3 ووسيط بدء الأعراض في اليوم 3. يتفق المنحنى مع تعرض قصير لمصدر مشترك، لكنه لا يثبت المصدر أو وقت التعرض وحده. قدّر نافذة تعرض محتملة باستخدام توزيع فترة الحضانة المعروف ونمط تواريخ البدء كاملًا، ولا ترجع آليًا من الذروة.", "terms": [{"termEn": "Onset date", "termAr": "تاريخ بدء الأعراض", "defEn": "The date symptoms began — the curve''s time axis.", "defAr": "تاريخ بدء الأعراض — محور زمن المنحنى."}, {"termEn": "Peak", "termAr": "الذروة", "defEn": "The tallest bar: the day or week with most onsets.", "defAr": "أطول شريط: اليوم أو الأسبوع بأكثر بدايات."}, {"termEn": "Median onset", "termAr": "البدء الوسيط", "defEn": "The date by which half the cases had onset.", "defAr": "التاريخ الذي بحلوله بدأت نصف الحالات."}, {"termEn": "Incubation period", "termAr": "فترة الحضانة", "defEn": "Time from exposure to symptom onset.", "defAr": "الزمن من التعرض إلى بدء الأعراض."}], "deepSections": [{"titleEn": "Constructing a defensible epidemic curve", "titleAr": "إنشاء منحنى وبائي يمكن الدفاع عنه", "bodyEn": "An epidemic curve is a histogram of cases by time of symptom onset, using equal and clearly labelled time intervals. Choose an interval appropriate to the incubation period and outbreak duration: hours for a short common-source event, days for many foodborne outbreaks, or weeks for slower processes. Each case should be counted once using the same case definition. Include a title, population, period, interval width, axis labels and data cut-off date. If onset is unknown, document how the record was handled rather than silently assigning a date. A curve based on report date should be labelled as such and not interpreted as if it were an onset curve.", "bodyAr": "المنحنى الوبائي مدرج تكراري للحالات بحسب وقت بدء الأعراض، باستخدام فترات زمنية متساوية ومحددة بوضوح. اختر فترة تناسب مدة الحضانة ومدة الفاشية: ساعات لحدث قصير ذي مصدر مشترك، وأياماً لكثير من الفاشيات المنقولة بالغذاء، أو أسابيع للعمليات الأبطأ. يجب عدّ كل حالة مرة واحدة وفق تعريف الحالة نفسه. أضف عنواناً والسكان والفترة وعرض الفاصل وتسميات المحاور وتاريخ قطع البيانات. إذا كان تاريخ البدء مجهولاً، وثّق كيفية التعامل مع السجل بدلاً من إسناد تاريخ بصمت. وإذا بُني المنحنى على تاريخ الإبلاغ، فسمّه بذلك ولا تفسره كما لو كان منحنى بدء الأعراض."}, {"titleEn": "Read the shape cautiously", "titleAr": "اقرأ شكل المنحنى بحذر", "bodyEn": "A sharp peak within roughly one incubation period can be compatible with a point-source exposure; a broad plateau may fit continuous common-source exposure; repeated peaks separated by an incubation interval may fit propagated person-to-person spread. These are pattern clues, not diagnostic signatures. Mixed exposures, incomplete onset dates, changing case finding, multiple introductions and intervention effects can produce atypical curves. The incubation period is disease-specific and varies between people. Do not infer a precise exposure time from curve shape alone; combine the curve with interviews, food histories, laboratory results and environmental findings.", "bodyAr": "قد تتوافق ذروة حادة ضمن نحو فترة حضانة واحدة مع تعرض نقطي المصدر؛ وقد تتوافق هضبة عريضة مع تعرض مستمر لمصدر مشترك؛ وقد تتوافق ذروات متكررة تفصل بينها فترة حضانة مع انتشار متسلسل من شخص إلى آخر. هذه قرائن نمطية وليست بصمات تشخيصية. قد تنتج التعرضات المختلطة ونقص تواريخ البدء وتغير اكتشاف الحالات وتعدد مرات الإدخال وتأثير التدخلات منحنيات غير نمطية. فترة الحضانة خاصة بكل مرض وتتفاوت بين الأشخاص. لا تستنتج وقت التعرض الدقيق من شكل المنحنى وحده؛ بل ادمجه مع المقابلات وتاريخ الطعام والنتائج المخبرية والمعطيات البيئية."}, {"titleEn": "Worked reading of the F-104 training series", "titleAr": "قراءة محلولة للسلسلة التدريبية في F-104", "bodyEn": "The supplied six-day training table contains daily totals of 4, 12, 28, 22, 14 and 10 cases, for 90 cases overall. Day 3 is the observed peak with 28 cases. The curve rises from Day 1 to Day 3 and then declines through Day 6. This shape describes the supplied counts; it does not by itself identify a point source or prove when exposure occurred. Before interpretation, confirm that the table uses onset date, that all six days have comparable reporting completeness, and that the 90 records are unique cases under one case definition. If the example is restricted to the first four days, the total is 66, not 90; keep the stated analytic window visible.", "bodyAr": "يحتوي جدول التدريب المرفق لستة أيام على مجاميع يومية 4 و12 و28 و22 و14 و10 حالات، بإجمالي 90 حالة. اليوم الثالث هو الذروة المرصودة وفيه 28 حالة. يرتفع المنحنى من اليوم الأول إلى الثالث ثم ينخفض حتى اليوم السادس. يصف هذا الشكل الأعداد المقدمة؛ لكنه لا يحدد وحده مصدراً نقطياً ولا يثبت وقت التعرض. قبل التفسير، تحقق من أن الجدول يستخدم تاريخ بدء الأعراض، وأن اكتمال الإبلاغ متقارب في الأيام الستة، وأن السجلات التسعين حالات فريدة وفق تعريف واحد. وإذا اقتصر المثال على الأيام الأربعة الأولى، فالإجمالي 66 لا 90؛ لذا أبقِ نافذة التحليل المحددة ظاهرة."}, {"titleEn": "Operational use and limitations", "titleAr": "الاستخدام التشغيلي والقيود", "bodyEn": "Use the curve to decide what to investigate next: identify the likely exposure window, select interview questions, plan specimen collection, monitor whether new onsets continue, and communicate the current trajectory. Mark intervention dates, public holidays, changes in testing and reporting disruptions. A declining curve after an intervention is encouraging but does not prove the intervention caused the decline; natural outbreak dynamics, behaviour changes or reporting delays may contribute. Update the curve as data are verified and label preliminary counts. Preserve the line list so the curve can be reproduced and corrected.", "bodyAr": "استخدم المنحنى لتحديد ما ينبغي تقصيه تالياً: تحديد نافذة التعرض المحتملة، واختيار أسئلة المقابلة، وتخطيط جمع العينات، ومراقبة استمرار حالات البدء الجديدة، والتواصل بشأن المسار الحالي. ضع علامات على تواريخ التدخل والعطلات والتغيرات في الاختبار واضطرابات الإبلاغ. انخفاض المنحنى بعد تدخل أمر مشجع لكنه لا يثبت أن التدخل سبّب الانخفاض؛ فقد تسهم ديناميات الفاشية الطبيعية أو تغير السلوك أو تأخر الإبلاغ. حدّث المنحنى عند التحقق من البيانات وسمِّ الأعداد الأولية بوضوح. احتفظ بقائمة الحالات كي يمكن إعادة إنتاج المنحنى وتصحيحه."}], "objEn": ["Construct an epidemic curve from onset dates.", "Find the peak and the median onset date.", "Interpret point-source, propagated and continuous patterns."], "objAr": ["بناء منحنى وبائي من تواريخ بدء الأعراض.", "إيجاد الذروة وتاريخ البدء الوسيط.", "تفسير أنماط المصدر النقطي والمتتابع والمستمر."]}', '[{"qEn": "An epidemic curve uses which date?", "qAr": "المنحنى الوبائي يستخدم أي تاريخ؟", "optsEn": ["Report date only", "Onset date", "Discharge date"], "optsAr": ["تاريخ الإبلاغ فقط", "تاريخ بدء الأعراض", "تاريخ الخروج"], "ans": 1, "explEn": "Onset date shows the true timing; report date adds delay.", "explAr": "تاريخ بدء الأعراض يظهر التوقيت الحقيقي؛ وتاريخ الإبلاغ يضيف تأخيرا."}, {"qEn": "Peak Day 3 with 28 cases, total 66, median is…", "qAr": "ذروة اليوم 3 بـ 28 حالة، المجموع 66، الوسيط هو…", "optsEn": ["Day 4", "Day 1", "Day 3"], "optsAr": ["اليوم 4", "اليوم 1", "اليوم 3"], "ans": 2, "explEn": "Cumulative 16 by Day 2, 44 by Day 3, so cases 33 and 34 are both in Day 3. Case 45 is in Day 4 but is not the median.", "explAr": "التراكمي 16 بحلول اليوم 2، و44 بحلول اليوم 3، لذا الحالتان 33 و34 كلتاهما في اليوم 3. الحالة 45 في اليوم 4 لكنها ليست الوسيط."}, {"qEn": "A single sharp peak most suggests…", "qAr": "ذروة حادة واحدة توحي غالبا بـ…", "optsEn": ["A point source", "Person-to-person waves", "An ongoing water source"], "optsAr": ["مصدر نقطي", "موجات من شخص لشخص", "مصدر مياه مستمر"], "ans": 0, "explEn": "A sharp single peak can be consistent with brief common-source exposure, but the curve alone cannot prove the source or transmission route.", "explAr": "قد تتفق الذروة المفردة الحادة مع تعرض قصير لمصدر مشترك، لكن المنحنى وحده لا يثبت المصدر أو طريق الانتقال."}, {"qEn": "Rising waves about one incubation period apart suggest…", "qAr": "موجات صاعدة تفصل بينها نحو فترة حضانة واحدة توحي بـ…", "optsEn": ["A point source", "Propagated spread", "No outbreak"], "optsAr": ["مصدر نقطي", "انتشار متتابع", "عدم وجود فاشية"], "ans": 1, "explEn": "Repeated peaks spaced by incubation fit person-to-person spread.", "explAr": "القمم المتكررة بفاصل حضانة تناسب الانتشار من شخص لشخص."}]' FROM courses WHERE course_code='B-106';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 3, 'كتابة تقرير وصفي', 'Writing a descriptive report', '[''هيكلة تقرير: مقدمة وطرق ونتائج ومناقشة وقيود وتوصيات.'', ''كتابة نتائج تطابق الطرق والجداول.'', ''كتابة توصيات تتبع الدليل — وتسمية ما ما زال غائبا.'']', '[''Structure a report: introduction, methods, results, discussion, limitations, recommendations.'', ''Write results that match the methods and the tables.'', ''Write recommendations that follow from the evidence — and name what is still missing.'']', 'التقرير الوصفي له ستة أجزاء. المقدمة: ما لوحظ وأين ومتى، وأي قرار يدعمه التقرير. الطرق: تعريف الحالة والسكان والفترة ومصادر البيانات وكيف صُنع المنحنى والمعدلات. النتائج: جداول الشخص والمكان والزمان والمنحنى الوبائي ومعدلات الهجوم — الأرقام أولا، والتفسير بعدها. المناقشة: ما يوحي به النمط، وما التفسيرات البديلة (الإبلاغ والعمر والفحص) التي قد تناسبه أيضا. القيود: ما كان غائبا أو متأخرا أو غير متساو — بصراحة. التوصيات: الإجراءات التالية ومن يملكها وما سيغيرها. التقرير الجيد لا يدّعي أبدا أكثر مما تسمح به طرقه. إذا تغير تعريف الحالة أثناء الفاشية، قل ذلك. وإذا أبلغ حي أفضل من غيره، قل ذلك. حدّد مؤشر الاكتمال المستخدم بدقة. اكتمال السجل (السجلات التي اكتملت فيها الحقول المحددة ÷ السجلات المتوقعة) يختلف عن اكتمال الحقول (الحقول المطلوبة المكتملة ÷ جميع الحقول المطلوبة المتوقعة)، وكلاهما يختلف عن اكتمال الإبلاغ (التقارير المستلمة ÷ التقارير المتوقعة).', 'A descriptive report has six parts. Introduction: what was observed, where and when, and what decision the report supports. Methods: case definition, population, period, data sources, and how the curve and rates were made. Results: person, place and time tables, the epidemic curve, and attack rates — numbers first, interpretation after. Discussion: what the pattern suggests, and what alternative explanations (reporting, age, testing) could also fit. Limitations: what was missing, late or uneven — stated plainly. Recommendations: the next actions, who owns them, and what would change them. A good report never claims more than its methods allow. If the case definition changed mid-outbreak, say so. If one neighbourhood reported better, say so. State exactly which completeness indicator is used. Record-level completeness (records with all specified fields complete ÷ expected records) differs from field-level completeness (completed required fields ÷ all required fields expected). Neither is the same as reporting completeness (reports received ÷ reports expected).', '{"exampleEn": "Mini-report example — Introduction: 66 cases of acute diarrhoea in Town X, onset 1–4 June, after a wedding and school meals. Methods: case definition (3+ loose stools in 24 hours, onset 1–4 June, resident or guest); line list from clinic + school. Results: 50% of cases from North; peak Day 3 (28 cases), median Day 3; attack rate among wedding guests 30% (45/150). Discussion: single sharp peak fits a point source; school waves need checking. Limitations: 10% of rows lack place; reporting was stronger in North. Recommendations: hold the suspected dish, inspect preparation, complete the missing 10%, re-interview school contacts, and update the curve daily.", "exampleAr": "مثال تقرير مصغر — المقدمة: 66 حالة إسهال حاد في البلدة س، بدء الأعراض 1–4 يونيو، بعد زفاف ووجبات مدرسية. الطرق: تعريف الحالة (3+ براز رخو خلال 24 ساعة، بدء 1–4 يونيو، مقيم أو ضيف)؛ قائمة حالات من العيادة + المدرسة. النتائج: 50% من الحالات من الشمال؛ الذروة اليوم 3 (28 حالة)، والوسيط اليوم 3؛ معدل الهجوم بين ضيوف الزفاف 30% (45/150). المناقشة: ذروة حادة واحدة تناسب مصدرا نقطيا؛ وموجات المدرسة تحتاج فحصا. القيود: 10% من الصفوف بلا مكان؛ والإبلاغ كان أقوى في الشمال. التوصيات: حجز الطبق المشتبه به، وفحص التحضير، وإكمال الـ 10% الغائبة، وإعادة مقابلة مخالطي المدرسة، وتحديث المنحنى يوميا.", "fieldEn": "Write recommendations as actions with owners and dates. “Improve hygiene” is not a recommendation; “Inspect preparation at the canteen by Thursday, owner: field team” is.", "fieldAr": "اكتب التوصيات كإجراءات بمالكين وتواريخ. «حسّن النظافة» ليست توصية؛ «افحص التحضير في المقصف بحلول الخميس، المالك: الفريق الميداني» هي توصية.", "calcTitleEn": "Worked calculation — completeness of the line list", "calcTitleAr": "حساب محلول — اكتمال قائمة الحالات", "calcStepsEn": ["Step 1 — Expected case records: 100.", "Step 2 — Records with onset date, age and place all completed: 90.", "Step 3 — Record-level completeness for these three specified fields = 90 ÷ 100 = 90%.", "Step 4 — Do not call this report completeness or field-level completeness; those require their own expected-report or expected-field denominators."], "calcStepsAr": ["الخطوة 1 — سجلات الحالات المتوقعة: 100.", "الخطوة 2 — السجلات التي اكتملت فيها حقول تاريخ البدء والعمر والمكان: 90.", "الخطوة 3 — اكتمال السجل لهذه الحقول الثلاثة المحددة = 90 ÷ 100 = 90%.", "الخطوة 4 — لا تسمِّ هذا اكتمال التقارير أو اكتمال الحقول؛ فلكل منهما مقام مستقل من التقارير أو الحقول المتوقعة."], "calcResultEn": "Result: 90% completeness. The report must say which 10% are missing and whether they cluster in one place or week — missing data that clusters can distort the curve and the place pattern.", "calcResultAr": "النتيجة: اكتمال 90%. يجب أن يقول التقرير أي 10% غائبة وهل تتجمع في مكان أو أسبوع واحد — البيانات الغائبة المتجمعة قد تشوّه المنحنى ونمط المكان.", "terms": [{"termEn": "Methods", "termAr": "الطرق", "defEn": "How cases were defined, found and counted.", "defAr": "كيف عُرّفت الحالات ووُجدت وعُدّت."}, {"termEn": "Results", "termAr": "النتائج", "defEn": "What the tables and curve show, before interpretation.", "defAr": "ما تظهره الجداول والمنحنى، قبل التفسير."}, {"termEn": "Limitations", "termAr": "القيود", "defEn": "What was missing, late or uneven in the data.", "defAr": "ما كان غائبا أو متأخرا أو غير متساو في البيانات."}, {"termEn": "Recommendations", "termAr": "التوصيات", "defEn": "Next actions, owners and what would change them.", "defAr": "الإجراءات التالية ومالكوها وما سيغيرها."}], "deepSections": [{"titleEn": "A report is an argument supported by data", "titleAr": "التقرير حجة تدعمها البيانات", "bodyEn": "A descriptive report should allow another reader to understand what was counted, in whom, where, when, and how reliably. A practical structure is: title and date; executive summary; background and objectives; methods; results; discussion; limitations; recommendations; references; and appendices. Methods must define the population, case definition, data sources, time window, geographic units, variables, denominators, missing-data handling and analysis. Results should follow the methods and present counts with denominators. Do not place interpretation in a results table or introduce a new denominator without explanation.", "bodyAr": "ينبغي أن يتيح التقرير الوصفي لقارئ آخر فهم ما الذي عُدّ، ولدى من، وأين، ومتى، وبأي درجة من الموثوقية. ومن البنى العملية: العنوان والتاريخ؛ والملخص التنفيذي؛ والخلفية والأهداف؛ والمنهجية؛ والنتائج؛ والمناقشة؛ والقيود؛ والتوصيات؛ والمراجع؛ والملاحق. يجب أن تحدد المنهجية السكان وتعريف الحالة ومصادر البيانات والنافذة الزمنية والوحدات الجغرافية والمتغيرات والمقامات والتعامل مع البيانات المفقودة والتحليل. ينبغي أن تتبع النتائج المنهجية وأن تعرض الأعداد مع المقامات. لا تضع التفسير داخل جدول النتائج ولا تقدم مقاماً جديداً دون توضيح."}, {"titleEn": "Present person-place-time results transparently", "titleAr": "اعرض نتائج الشخص والمكان والزمان بشفافية", "bodyEn": "For the F-104 six-day table, the daily totals sum to 90; place totals are North 45, East 25 and South 20. These are counts, not area-specific risks, because population denominators by neighbourhood are not supplied. North has the largest number of cases in this dataset, but it cannot be called the highest-risk area without the number of residents at risk in each neighbourhood and comparable case ascertainment. State that limitation beside the table, not only in a distant appendix. If denominators become available, calculate comparable area-specific proportions or rates and document their reference periods.", "bodyAr": "في جدول F-104 ذي الأيام الستة، يبلغ مجموع الأعداد اليومية 90؛ ومجاميع الأماكن هي الشمال 45 والشرق 25 والجنوب 20. هذه أعداد وليست مخاطر خاصة بالمناطق، لأن مقامات السكان حسب الحي غير متاحة. يسجل الشمال أكبر عدد حالات في مجموعة البيانات، لكن لا يمكن وصفه بأنه المنطقة الأعلى خطراً دون معرفة عدد السكان المعرضين للخطر في كل حي وتكافؤ اكتشاف الحالات. اذكر هذا القيد بجوار الجدول لا في ملحق بعيد فقط. وإذا توفرت المقامات، فاحسب نسباً أو معدلات قابلة للمقارنة حسب المنطقة ووثق فتراتها المرجعية."}, {"titleEn": "Separate findings, interpretation and recommendations", "titleAr": "افصل النتائج عن التفسير والتوصيات", "bodyEn": "Findings are direct descriptions: “90 records were included; 28 had onset on Day 3.” Interpretation explains what the pattern may mean and what alternative explanations remain. Recommendations specify actions, owners, timing and review triggers. A defensible recommendation is proportionate to evidence and urgency. For example, verify the apparent northern cluster and obtain neighbourhood denominators before allocating resources solely on raw counts; meanwhile, maintain case finding in all areas. Do not claim a trend if reporting completeness changed, and do not claim an association if no comparison group or denominator supports it.", "bodyAr": "النتائج أوصاف مباشرة: «أُدرج 90 سجلاً؛ وبدأت 28 حالة في اليوم الثالث». يشرح التفسير ما قد يعنيه النمط وما التفسيرات البديلة المتبقية. وتحدد التوصيات الإجراءات والمسؤولين والتوقيت ومحفزات المراجعة. تكون التوصية القابلة للدفاع متناسبة مع الدليل والاستعجال. مثال ذلك: تحقق من التجمع الظاهر في الشمال واحصل على مقامات السكان حسب الحي قبل تخصيص الموارد اعتماداً على الأعداد الخام وحدها؛ وفي الوقت نفسه حافظ على اكتشاف الحالات في جميع المناطق. لا تدّع وجود اتجاه إذا تغير اكتمال الإبلاغ، ولا تدّع وجود ارتباط إذا لم تدعمه مجموعة مقارنة أو مقامات مناسبة."}, {"titleEn": "Limitations, ethics and reproducibility", "titleAr": "القيود والأخلاقيات وقابلية إعادة الإنتاج", "bodyEn": "Common limitations include incomplete case ascertainment, changing case definitions, missing onset dates, inaccurate population denominators, duplicate records, referral bias and ecological fallacy. Describe the likely direction of bias only when justified; otherwise say it is uncertain. Use the minimum identifiable information needed, restrict access, aggregate small cells and follow local reporting and data-protection rules. Keep a dated analysis script or calculation sheet, data dictionary, versioned line list and a record of exclusions. A second analyst should be able to reproduce the tables from the documented dataset and methods. Never publish identifiable line-list details in a public report.", "bodyAr": "تشمل القيود الشائعة نقص اكتشاف الحالات وتغير تعريف الحالة وغياب تواريخ البدء وعدم دقة مقامات السكان والسجلات المكررة وتحيز الإحالة والمغالطة البيئية. اذكر اتجاه التحيز المحتمل فقط عندما يكون مبرراً؛ وإلا فقل إنه غير معلوم. استخدم الحد الأدنى من المعلومات التي تكشف الهوية، وقيّد الوصول، واجمع الخلايا الصغيرة، واتبع قواعد الإبلاغ وحماية البيانات المحلية. احتفظ بنص تحليل أو ورقة حساب مؤرخة، وقاموس بيانات، وقائمة حالات ذات إصدارات، وسجل للاستبعادات. ينبغي لمحلل ثانٍ أن يستطيع إعادة إنتاج الجداول من مجموعة البيانات والمنهجية الموثقتين. لا تنشر أبداً تفاصيل قائمة حالات تكشف الهوية في تقرير عام."}], "objEn": ["Structure a report: introduction, methods, results, discussion, limitations, recommendations.", "Write results that match the methods and the tables.", "Write recommendations that follow from the evidence — and name what is still missing."], "objAr": ["هيكلة تقرير: مقدمة وطرق ونتائج ومناقشة وقيود وتوصيات.", "كتابة نتائج تطابق الطرق والجداول.", "كتابة توصيات تتبع الدليل — وتسمية ما ما زال غائبا."]}', '[{"qEn": "90 complete rows of 100 expected is…", "qAr": "90 صفا مكتملا من 100 متوقعة هي…", "optsEn": ["10% complete", "9% complete", "90% complete"], "optsAr": ["10% مكتملة", "9% مكتملة", "90% مكتملة"], "ans": 2, "explEn": "90 ÷ 100 = 90% record-level completeness for the three named fields, not necessarily reporting completeness.", "explAr": "90 ÷ 100 = 90% لاكتمال السجلات في الحقول الثلاثة المحددة، وليس بالضرورة لاكتمال الإبلاغ."}, {"qEn": "Results should come…", "qAr": "النتائج يجب أن تأتي…", "optsEn": ["Before interpretation, matching the methods", "After recommendations", "Without any tables"], "optsAr": ["قبل التفسير، مطابقة للطرق", "بعد التوصيات", "من دون أي جداول"], "ans": 0, "explEn": "Results report what was found; discussion interprets it.", "explAr": "النتائج تبلغ عما وُجد؛ والمناقشة تفسّره."}, {"qEn": "A good recommendation is…", "qAr": "التوصية الجيدة هي…", "optsEn": ["A vague wish", "An action with owner and date", "A repeat of the introduction"], "optsAr": ["أمنية غامضة", "إجراء بمالك وتاريخ", "تكرار للمقدمة"], "ans": 1, "explEn": "Actionable recommendations name who does what by when.", "explAr": "التوصيات القابلة للتنفيذ تسمي من يفعل ماذا ومتى."}, {"qEn": "Limitations should…", "qAr": "القيود يجب أن…", "optsEn": ["Be hidden", "Blame one clinic", "State plainly what was missing or uneven"], "optsAr": ["تُخفى", "تلوم عيادة واحدة", "تذكر بصراحة ما كان غائبا أو غير متساو"], "ans": 2, "explEn": "Honest limitations let readers judge how far the results reach.", "explAr": "القيود الصادقة تدع القارئ يحكم إلى أي مدى تصل النتائج."}]' FROM courses WHERE course_code='B-106';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 1, 'مصادر البيانات في علم الأوبئة', 'Data sources in epidemiology', '[''تسمية خمسة مصادر بيانات روتينية وما يعده كل منها.'', ''مطابقة السؤال مع أفضل مصدر له.'', ''شرح لماذا لا يجيب مصدر واحد عن كل سؤال.'']', '[''Name five routine data sources and what each one counts.'', ''Match a question to the best source for it.'', ''Explain why no single source answers every question.'']', 'علم الأوبئة نادرا ما يبدأ ببيانات كاملة. بل يبدأ بما هو موجود أصلا. الترصد الروتيني يجمع بلاغات الحالات من العيادات والمختبرات بشكل مستمر. والمسوح تسأل عينة من الناس نفس الأسئلة في وقت واحد، لذا يمكنها تقدير الانتشار والسلوكيات. وتسجيل الأحوال المدنية يسجّل المواليد والوفيات، مما يجعل تحليل الوفيات وأسبابها ممكنا. وسجلات المرافق — السجلات ودفاتر الدخول ودفاتر المختبر — تظهر من رُئي وفُحص وعُولج. وقوائم الحالات هي الأداة العملية في الفاشية: صف واحد لكل حالة، فيه الشخص والمكان والزمان والأعراض والتعرضات والنتيجة المخبرية. ولكل مصدر مقام مختلف وتأخير مختلف وتحيز مختلف. المسح يمكنه تقدير الانتشار في المجتمع؛ ولا يمكنه أن يحل محل الترصد للإنذار المبكر. وسجلات المرافق تظهر من وصل إلى الرعاية؛ وتخفي من لم يأت أبدا. والممارسة الجيدة أن تسمي المصدر مع كل رقم، وتسأل من الغائب عنه، وتتحقق من مصدر ثان قبل التصرف. عند دمج المصادر، استخدم تعريف حالة تشغيليًا واحدًا، ووحّد المكان والفترة الزمنية، وأزل تكرار السجلات على مستوى الشخص قبل جمع الأعداد. لا يجوز عد الشخص نفسه ثلاث مرات إذا ظهر في الترصد وسجل المرفق والمسح. كما تتطلب تقديرات المسوح مراعاة تصميم العينة والاستجابة والأوزان؛ فالعينة الملائمة ليست ممثلة تلقائيًا.', 'Epidemiology rarely starts with perfect data. It starts with what already exists. Routine surveillance collects case reports from clinics and laboratories on an ongoing basis. Surveys ask a sample of people the same questions at one time, so they can estimate prevalence and behaviours. Vital registration records births and deaths, which makes mortality and cause-of-death analysis possible. Facility records — registers, admission logs and laboratory logbooks — show who was seen, tested and treated. Line lists are the working tool in an outbreak: one row per case, with person, place, time, symptoms, exposures and laboratory result. Each source has a different denominator, a different delay and a different bias. A survey can estimate prevalence in the community; it cannot replace surveillance for early warning. Facility records show who reached care; they hide people who never came. Good practice is to name the source with every number, ask who is missing from it, and check a second source before acting. When combining sources, use one operational case definition, align the place and time window, and deduplicate records at person level before adding counts. A person appearing in surveillance, a facility register and a survey must not be counted three times. Survey estimates also require attention to sampling design, response and weighting; a convenience sample is not automatically representative.', '{"exampleEn": "Field case — A clinic reports 28 cases. A laboratory log identifies 8 additional people not already on the surveillance line list; a community survey identifies 4 further unique people. The team links records using a protected unique identifier plus compatible onset and demographic details, reviews possible matches, and removes duplicates before reporting 40 unique identified people. The combined total is only as reliable as the linkage and the survey design.", "exampleAr": "حالة ميدانية — أبلغت عيادة عن 28 حالة. حدد سجل المختبر 8 أشخاص إضافيين غير موجودين في قائمة الترصد، وحدد مسح مجتمعي 4 أشخاص فريدين آخرين. ربط الفريق السجلات باستخدام معرّف فريد محمي مع توافق تاريخ البدء والبيانات الديموغرافية، وراجع المطابقات المحتملة وأزال التكرار قبل الإبلاغ عن 40 شخصًا فريدًا. ولا يكون المجموع المدمج موثوقًا إلا بقدر موثوقية الربط وتصميم المسح.", "fieldEn": "For every number, write its source and its denominator. Ask: who never reaches this source? Reference basis: WHO IDSR technical guidance on routine surveillance data quality and triangulation; use privacy-preserving person-level linkage.", "fieldAr": "لكل رقم، اكتب مصدره ومقامه. واسأل: من لا يصل أبدا إلى هذا المصدر؟ مرجع المراجعة: إرشادات WHO للترصد المتكامل للأمراض والاستجابة بشأن جودة بيانات الترصد والتثليث؛ مع ربط سجلات يحافظ على الخصوصية.", "calcTitleEn": "Worked calculation — cases by source", "calcTitleAr": "حساب محلول — الحالات حسب المصدر", "calcStepsEn": ["Step 1 — Routine surveillance contains 28 unique cases in the defined place and week.", "Step 2 — The facility register identifies 8 additional people not already in surveillance; deduplication leaves 36 unique people.", "Step 3 — The survey identifies 4 further unique people not present in either source; after person-level linkage, the combined count is 40.", "Step 4 — The 4 survey-only people are 4 ÷ 40 = 10% of the combined identified cases. This is not a population prevalence estimate unless the survey sampling design supports it."], "calcStepsAr": ["الخطوة 1 — يحتوي الترصد الروتيني على 28 حالة فريدة في المكان والأسبوع المحددين.", "الخطوة 2 — يحدد سجل المرفق 8 أشخاص إضافيين غير موجودين في الترصد؛ وبعد إزالة التكرار يصبح المجموع 36 شخصًا فريدًا.", "الخطوة 3 — يحدد المسح 4 أشخاص فريدين آخرين غير موجودين في المصدرين؛ وبعد الربط على مستوى الشخص يصبح العدد المدمج 40.", "الخطوة 4 — الأشخاص الأربعة الذين لم يظهروا إلا في المسح يمثلون 4 ÷ 40 = 10% من الحالات المحددة مجتمعة. وهذا ليس تقديرًا لانتشار المجتمع إلا إذا كان تصميم عينة المسح يدعم ذلك."], "calcResultEn": "Result: 40 cases in total, and 10% were visible only in the survey. One source alone would have under-counted the outbreak.", "calcResultAr": "النتيجة: 40 حالة في المجموع، و10% ظهرت في المسح فقط. مصدر واحد وحده كان سيقلل عدد الفاشية.", "terms": [{"termEn": "Routine surveillance", "termAr": "الترصد الروتيني", "defEn": "Ongoing, systematic collection of case reports from clinics and laboratories.", "defAr": "جمع مستمر ومنهجي لبلاغات الحالات من العيادات والمختبرات."}, {"termEn": "Survey", "termAr": "المسح", "defEn": "The same questions asked to a sample at one time to estimate prevalence or behaviour.", "defAr": "نفس الأسئلة تُطرح على عينة في وقت واحد لتقدير الانتشار أو السلوك."}, {"termEn": "Vital registration", "termAr": "تسجيل الأحوال المدنية", "defEn": "Official records of births and deaths, used for mortality and cause-of-death analysis.", "defAr": "سجلات رسمية للمواليد والوفيات، تُستخدم لتحليل الوفيات وأسبابها."}, {"termEn": "Line list", "termAr": "قائمة الحالات", "defEn": "One row per case with person, place, time, symptoms, exposures and laboratory result.", "defAr": "صف واحد لكل حالة فيه الشخص والمكان والزمان والأعراض والتعرضات والنتيجة المخبرية."}], "deepSections": [{"titleEn": "Choosing a data source that can answer the question", "titleAr": "اختيار مصدر بيانات يستطيع الإجابة عن السؤال", "bodyEn": "A data source is not “good” in the abstract; it is fit or unfit for a defined question, population, period and decision. Start by writing the estimand or operational question in one sentence: for example, “How many suspected measles cases were notified in District X during epidemiological weeks 10–13?” is a surveillance question, while “What proportion of children aged 12–23 months in District X had received two measles-containing vaccine doses by 30 June?” is a population coverage question. The first is usually answered from notification and case-investigation systems; the second generally needs a representative household survey or a well-validated population-based immunisation information source. A facility register alone cannot estimate community coverage because children who never attend the facility are absent.\n\nRoutine surveillance is continuous and useful for trend detection, alerts and response, but it is affected by case definitions, care-seeking, diagnostic access, reporting compliance and delay. Laboratory information systems provide test results and specimen pathways, but the tested population is selected; positivity among submitted specimens is not automatically population prevalence. Facility records describe service users and care processes; they omit people who do not reach care and may contain repeat visits. Vital registration and civil registration can support births, deaths and cause-specific mortality, but completeness and cause-of-death certification vary. Population censuses provide denominators and demographic structure but are infrequent and may become outdated. Probability surveys can estimate population quantities when sampling, nonresponse, weighting and measurement are handled correctly; a convenience sample cannot be relabelled representative. Registries may be highly detailed for a defined condition but can miss people outside participating services. Administrative datasets are created for payment or management, so their coding rules may not match epidemiological case definitions.\n\nUse a source-selection matrix before analysis: (1) target population and eligibility; (2) event or variable actually captured; (3) geographic and time coverage; (4) numerator and denominator availability; (5) case definition and measurement validity; (6) expected delay; (7) missingness and selection mechanisms; (8) linkage feasibility; (9) privacy/legal authority; and (10) resources and decision deadline. If two sources disagree, do not average their counts. First compare their definitions, coverage, reporting periods, duplicate handling and update dates. Triangulation means comparing complementary sources to understand the event, not indiscriminately adding all rows.", "bodyAr": "لا يكون مصدر البيانات «جيدًا» بصورة مطلقة؛ بل يكون ملائمًا أو غير ملائم لسؤال وسكان وفترة وقرار محدد. ابدأ بكتابة الكمية المراد تقديرها أو السؤال التشغيلي في جملة واحدة. فمثلاً: «كم حالة حصبة مشتبهًا بها أُبلغ عنها في المديرية س خلال الأسابيع الوبائية 10–13؟» سؤال ترصد، بينما «ما نسبة الأطفال بعمر 12–23 شهرًا في المديرية س الذين تلقوا جرعتين من لقاح يحتوي على الحصبة حتى 30 يونيو؟» سؤال تغطية سكانية. يُجاب عن الأول عادة من نظام الإبلاغ والتحقيق في الحالات؛ أما الثاني فيحتاج غالبًا إلى مسح أسري ممثل أو مصدر معلومات تحصين سكاني جرى التحقق من صلاحيته. ولا يستطيع سجل مرفق صحي وحده تقدير التغطية المجتمعية لأن الأطفال الذين لا يزورون المرفق غير موجودين فيه.\n\nالترصد الروتيني مستمر ومفيد لاكتشاف الاتجاهات والتنبيهات والاستجابة، لكنه يتأثر بتعريف الحالة وطلب الرعاية وإمكانية التشخيص والالتزام بالإبلاغ والتأخر. وتوفر نظم معلومات المختبر نتائج الفحوص ومسار العينات، لكن السكان الذين خضعوا للفحص مجموعة منتقاة؛ وإيجابية العينات المرسلة ليست تلقائيًا انتشارًا سكانيًا. وتصف سجلات المرافق مستخدمي الخدمات وعمليات الرعاية؛ لكنها لا تشمل من لم يصلوا للرعاية وقد تتضمن زيارات متكررة. ويمكن أن يدعم التسجيل المدني تسجيل المواليد والوفيات وأسبابها، لكن الاكتمال وشهادة سبب الوفاة يختلفان. وتوفر التعدادات السكانية المقامات والتركيب الديموغرافي لكنها متباعدة وقد تصبح قديمة. ويمكن للمسوح الاحتمالية تقدير مقادير سكانية إذا عولج تصميم العينة وعدم الاستجابة والأوزان والقياس بطريقة صحيحة؛ ولا يجوز وصف عينة الملاءمة بأنها ممثلة. وقد تكون السجلات المتخصصة مفصلة لحالة محددة لكنها تفقد من هم خارج الخدمات المشاركة. أما قواعد البيانات الإدارية فقد أُنشئت للدفع أو الإدارة، ولذلك قد لا تتوافق قواعد الترميز فيها مع تعريف الحالة الوبائي.\n\nاستخدم مصفوفة لاختيار المصدر قبل التحليل: (1) السكان المستهدفون ومعايير الأهلية؛ (2) الحدث أو المتغير الذي يلتقطه المصدر فعلًا؛ (3) التغطية الجغرافية والزمنية؛ (4) توافر البسط والمقام؛ (5) تعريف الحالة وصلاحية القياس؛ (6) التأخر المتوقع؛ (7) آليات الفقد والاختيار؛ (8) إمكانية الربط؛ (9) الخصوصية والتفويض القانوني؛ و(10) الموارد والموعد النهائي للقرار. إذا اختلف مصدران فلا تحسب متوسط العددين. قارن أولًا التعريفات والتغطية وفترات الإبلاغ وإزالة التكرار وتواريخ التحديث. يعني التثليث مقارنة مصادر متكاملة لفهم الحدث، لا جمع كل الصفوف بلا تمييز."}, {"titleEn": "Record linkage, deduplication and a defensible line list", "titleAr": "ربط السجلات وإزالة التكرار وبناء قائمة حالات يمكن الدفاع عنها", "bodyEn": "When the same person appears in a clinic register, laboratory log and surveillance line list, adding source totals produces a person-count error. Define the unit of analysis before combining data: person, episode, visit, specimen or report. These units are not interchangeable. One person may have multiple visits, specimens or episodes; a recurrent episode may be counted only if the surveillance protocol defines it as a new event. Create a common data dictionary and harmonise variable names, date formats, geographic codes, age units, case classifications and missing-value codes before linkage.\n\nA defensible linkage workflow has six stages. First, document the purpose, legal authority, data minimisation plan, retention period and access roles. Second, identify a privacy-protecting linkage key where lawful, such as a locally generated coded identifier; do not place names or national identifiers in a general teaching or analysis export. Third, standardise fields used for matching (for example, date of birth format, sex coding, facility code and onset date) without overwriting original values. Fourth, use deterministic matching when a reliable unique identifier is present; use probabilistic matching only with a documented method, thresholds and clerical review for uncertain pairs. Fifth, classify pairs as confirmed match, possible match or non-match, preserve the source record IDs, and keep an audit log of every merge or split. Sixth, produce a deduplication report showing records received, exact duplicates, probable duplicates reviewed, unique people retained and unresolved pairs.\n\nDo not automatically merge records merely because names look similar. Names may be transliterated differently, several people may share a name, and a single person may use multiple spellings. Conversely, do not assume two records are different because one field differs: dates may be entered incorrectly or ages rounded. A merge decision can alter the epidemic curve, case count, denominator and laboratory positivity. Preserve a reversible crosswalk in a restricted environment, not in the public analysis file. The analysis dataset should contain only the minimum variables needed and a pseudonymous study key.\n\nWorked example: a clinic register has 31 rows, the laboratory log has 12 rows, and the surveillance list has 28 rows. These sum to 71 records, not 71 people. After standardisation and person-level linkage, the team confirms 9 overlaps between clinic and surveillance, 5 between laboratory and surveillance, and 3 additional overlaps involving all three sources. The exact unique-person total cannot be inferred by subtracting these numbers unless the overlap structure is known; calculate it from the record-level linkage table. The teaching dataset already used in this course illustrates a reconciled result of 40 unique identified people (28 surveillance, 8 additional facility records and 4 further survey-only people). The 40 is a constructed training example, not a real outbreak count. The 4/40 = 10% survey-only fraction describes the composition of those identified records; it is not population prevalence unless the survey design supports that inference.", "bodyAr": "عندما يظهر الشخص نفسه في سجل عيادة ودفتر مختبر وقائمة ترصد، فإن جمع مجاميع المصادر يؤدي إلى خطأ في عدد الأشخاص. حدّد وحدة التحليل قبل دمج البيانات: شخص أو نوبة مرضية أو زيارة أو عينة أو بلاغ. هذه الوحدات ليست مترادفة. فقد يكون للشخص الواحد زيارات أو عينات أو نوبات متعددة؛ ولا تُعد النوبة المتكررة حدثًا جديدًا إلا إذا عرّف بروتوكول الترصد ذلك صراحة.\n\nأنشئ قاموس بيانات موحدًا ووحّد أسماء المتغيرات وصيغ التواريخ والرموز الجغرافية ووحدات العمر وتصنيفات الحالة ورموز القيم المفقودة قبل الربط. ويتكون مسار الربط القابل للدفاع عن ست مراحل. أولًا: وثّق الغرض والأساس القانوني وخطة تقليل البيانات وفترة الاحتفاظ وصلاحيات الوصول. ثانيًا: حدّد مفتاح ربط يحمي الخصوصية متى كان ذلك قانونيًا، مثل معرّف مشفر يُنشأ محليًا؛ ولا تضع الأسماء أو أرقام الهوية الوطنية في ملف تحليل أو تعليم عام. ثالثًا: وحّد الحقول المستخدمة للمطابقة، مثل صيغة تاريخ الميلاد وترميز الجنس ورمز المرفق وتاريخ بدء الأعراض، دون الكتابة فوق القيم الأصلية. رابعًا: استخدم المطابقة الحتمية عند توافر معرّف فريد موثوق؛ ولا تستخدم المطابقة الاحتمالية إلا بمنهج وعتبات موثقة ومراجعة بشرية للأزواج غير المؤكدة. خامسًا: صنّف الأزواج إلى تطابق مؤكد أو محتمل أو غير متطابق، واحتفظ بمعرّفات السجلات المصدرية وسجل تدقيق لكل دمج أو فصل. سادسًا: أنشئ تقرير إزالة تكرار يبين السجلات المستلمة والتكرارات المؤكدة والمحتملة التي روجعت والأشخاص الفريدين المحتفظ بهم والأزواج غير المحسومة.\n\nلا تدمج السجلات تلقائيًا لمجرد تشابه الأسماء. فقد تُكتب الأسماء بطرق نقل صوتي مختلفة، وقد يشترك عدة أشخاص في الاسم، وقد يستخدم الشخص تهجئات متعددة. وبالعكس، لا تفترض اختلاف سجلين لمجرد اختلاف حقل واحد؛ فقد يُدخل التاريخ خطأ أو يُقرب العمر. ويمكن لقرار الدمج أن يغير المنحنى الوبائي وعدد الحالات والمقام وإيجابية المختبر. احتفظ بجدول ربط عكسي في بيئة مقيدة الصلاحيات، لا في ملف التحليل العام. ويجب أن يحتوي ملف التحليل على الحد الأدنى اللازم من المتغيرات ومفتاح دراسة مستعار الهوية.\n\nمثال محلول: يحتوي سجل عيادة على 31 صفًا، ودفتر المختبر على 12 صفًا، وقائمة الترصد على 28 صفًا. مجموع الصفوف 71 سجلًا، وليس 71 شخصًا. بعد توحيد الحقول والربط على مستوى الشخص، يؤكد الفريق وجود 9 تداخلات بين العيادة والترصد، و5 بين المختبر والترصد، و3 تداخلات إضافية تشمل المصادر الثلاثة. لا يمكن استنتاج العدد الفريد بطرح هذه القيم إلا إذا عُرفت بنية التداخل كاملة؛ بل يجب حسابه من جدول الربط على مستوى السجل. ويوضح المثال التدريبي الموجود في هذا المقرر نتيجة متصالحة قدرها 40 شخصًا فريدًا (28 من الترصد، و8 سجلات إضافية من المرفق، و4 أشخاص إضافيين ظهروا في المسح فقط). والعدد 40 مثال تدريبي مصمم، وليس عدد فاشية حقيقية. كما أن 4/40 = 10% تصف تركيب السجلات المحددة، ولا تمثل انتشارًا سكانيًا إلا إذا كان تصميم المسح يدعم هذا الاستنتاج."}, {"titleEn": "Triangulation, source disagreement and the field decision", "titleAr": "التثليث واختلاف المصادر والقرار الميداني", "bodyEn": "Triangulation is strongest when sources have different strengths and partially independent failure modes. A rise in clinic notifications, an increase in laboratory-confirmed specimens and community reports may jointly strengthen the signal, but they may also share the same referral pathway or publicity effect. Ask whether sources are genuinely independent, whether they cover the same population and time, and whether the same person or event appears in more than one source. Do not treat agreement as proof of completeness: all sources may miss remote communities. Do not treat disagreement as proof that one source is wrong: they may count different events, use different case definitions or close at different dates.\n\nA field team can use a source-concordance table with one row per source and columns for target population, case definition, time window, geographic coverage, numerator, denominator, missingness, delay, duplication handling and known limitations. Explain discrepancies explicitly. For example, surveillance may show 28 cases, facility registers may contain 36 records, and a probability survey may identify 4 people not previously captured. After verified linkage, the unique total might be 40. But if the survey uses a convenience sample, those four additional people cannot be used to estimate how many cases were missed in the whole community. The correct conclusion is that the sources identified additional people and that the magnitude of under-ascertainment remains uncertain.\n\nCase study — a district reports a sudden fall in acute watery diarrhoea notifications. The district dashboard suggests improvement. Before reducing response supplies, the epidemiologist checks: (1) whether all expected facilities submitted; (2) whether the reporting deadline changed; (3) whether a road closure interrupted access; (4) whether the case definition or reporting form changed; (5) whether laboratory referrals fell; and (6) whether a data-entry or deduplication rule changed. A phone verification finds that several facilities are holding paper forms because the network is down. The apparent decline is a reporting interruption, not evidence of reduced transmission. The team labels the current period provisional, contacts facilities through an alternative channel, preserves actual onset dates and updates the dashboard after reconciliation.\n\nThe decision rule is practical: use the best available source for the immediate question, state what it cannot answer, triangulate where feasible, and act proportionately to risk. Data-source selection is not a one-time administrative task; it is part of epidemiological reasoning. Every table and graph should disclose the source, case definition, period, denominator (if applicable), extraction date and important exclusions.", "bodyAr": "يكون التثليث أقوى عندما تمتلك المصادر نقاط قوة مختلفة وأنماط إخفاق مستقلة جزئيًا. فقد يؤدي ارتفاع بلاغات العيادات وزيادة العينات المؤكدة مخبريًا وبلاغات المجتمع معًا إلى تقوية الإشارة، لكنها قد تشترك أيضًا في مسار إحالة واحد أو تتأثر بحملة إعلامية واحدة. اسأل هل المصادر مستقلة فعلًا، وهل تغطي السكان والفترة نفسيهما، وهل يظهر الشخص أو الحدث نفسه في أكثر من مصدر. لا تعتبر الاتفاق دليلًا على الاكتمال؛ فقد تفوت جميع المصادر المجتمعات النائية. ولا تعتبر الاختلاف دليلًا على خطأ أحد المصادر؛ فقد تعد أحداثًا مختلفة أو تستخدم تعريفات حالة مختلفة أو تغلق بياناتها في تواريخ مختلفة.\n\nيمكن للفريق الميداني استخدام جدول توافق المصادر، بحيث يكون لكل مصدر صف، وتتضمن الأعمدة السكان المستهدفين وتعريف الحالة والفترة الزمنية والتغطية الجغرافية والبسط والمقام والفقد والتأخر وطريقة إزالة التكرار والقيود المعروفة. اشرح الاختلافات صراحة. فمثلًا قد يظهر الترصد 28 حالة، وسجلات المرافق 36 سجلًا، ويحدد مسح احتمالي 4 أشخاص لم يسبق التقاطهم. وبعد الربط المتحقق قد يصبح العدد الفريد 40. لكن إذا استخدم المسح عينة ملاءمة، فلا يجوز استخدام هؤلاء الأربعة لتقدير عدد الحالات التي فاتت المجتمع كله. والاستنتاج الصحيح هو أن المصادر حددت أشخاصًا إضافيين وأن حجم النقص في الاكتشاف لا يزال غير مؤكد.\n\nدراسة حالة — أبلغت مديرية عن انخفاض مفاجئ في بلاغات الإسهال المائي الحاد. وتوحي لوحة المؤشرات بتحسن الوضع. قبل خفض إمدادات الاستجابة، يتحقق الوبائي من: (1) هل أرسلت جميع المرافق المتوقعة تقاريرها؟ (2) هل تغير موعد الإبلاغ؟ (3) هل أدى إغلاق طريق إلى تعطيل الوصول؟ (4) هل تغير تعريف الحالة أو نموذج الإبلاغ؟ (5) هل انخفضت إحالات المختبر؟ (6) هل تغيرت قاعدة إدخال البيانات أو إزالة التكرار؟ ويكشف التحقق الهاتفي أن عدة مرافق تحتفظ بالنماذج الورقية بسبب انقطاع الشبكة. فالانخفاض الظاهري انقطاع في الإبلاغ، وليس دليلًا على تراجع الانتقال. يضع الفريق علامة «بيانات أولية» على الفترة الحالية، ويتواصل مع المرافق عبر قناة بديلة، ويحافظ على تواريخ بدء الأعراض الحقيقية، ثم يحدث لوحة المؤشرات بعد التسوية.\n\nقاعدة القرار عملية: استخدم أفضل مصدر متاح للسؤال العاجل، واذكر ما لا يستطيع الإجابة عنه، وثَلّث المصادر عندما يكون ذلك ممكنًا، واتخذ إجراءً متناسبًا مع الخطر. اختيار مصدر البيانات ليس مهمة إدارية تُنجز مرة واحدة؛ بل هو جزء من التفكير الوبائي. وينبغي لكل جدول ورسم أن يوضح المصدر وتعريف الحالة والفترة والمقام إن وجد وتاريخ استخراج البيانات والاستبعادات المهمة."}], "objEn": ["Name five routine data sources and what each one counts.", "Match a question to the best source for it.", "Explain why no single source answers every question."], "objAr": ["تسمية خمسة مصادر بيانات روتينية وما يعده كل منها.", "مطابقة السؤال مع أفضل مصدر له.", "شرح لماذا لا يجيب مصدر واحد عن كل سؤال."]}', '[{"qEn": "Which source is best for early warning of a new outbreak?", "qAr": "أي مصدر أفضل للإنذار المبكر بفاشية جديدة؟", "optsEn": ["Routine surveillance", "A one-off survey", "Vital registration"], "optsAr": ["الترصد الروتيني", "مسح لمرة واحدة", "تسجيل الأحوال المدنية"], "ans": 0, "explEn": "Surveillance is ongoing, so it can show a rise quickly.", "explAr": "الترصد مستمر، لذا يمكنه إظهار الارتفاع بسرعة."}, {"qEn": "Facility records mainly show…", "qAr": "سجلات المرافق تظهر أساسا…", "optsEn": ["Everyone in the community", "People who reached care", "Future cases"], "optsAr": ["كل من في المجتمع", "من وصل إلى الرعاية", "الحالات المستقبلية"], "ans": 1, "explEn": "People who never came are invisible in facility records.", "explAr": "من لم يأت لا يظهر في سجلات المرافق."}, {"qEn": "Before adding counts from surveillance, facility and survey sources, the team should first…", "qAr": "قبل جمع أعداد الترصد وسجل المرفق والمسح، ينبغي للفريق أولًا أن…", "optsEn": ["Add every source count directly", "Use the largest count only", "Deduplicate people using a common case definition and time window"], "optsAr": ["يجمع أعداد المصادر مباشرة", "يستخدم أكبر عدد فقط", "يزيل تكرار الأشخاص باستخدام تعريف حالة وفترة موحدين"], "ans": 2, "explEn": "Sources overlap. Person-level deduplication is required before counts can be combined.", "explAr": "تتداخل المصادر؛ لذا يجب إزالة تكرار الأشخاص قبل دمج الأعداد."}, {"qEn": "Vital registration is mainly used for…", "qAr": "تسجيل الأحوال المدنية يُستخدم أساسا لـ…", "optsEn": ["Mortality and cause-of-death analysis", "Daily case finding", "Testing a new drug"], "optsAr": ["تحليل الوفيات وأسبابها", "اكتشاف الحالات اليومي", "اختبار دواء جديد"], "ans": 0, "explEn": "Birth and death registration supports mortality analysis.", "explAr": "تسجيل المواليد والوفيات يدعم تحليل الوفيات."}]' FROM courses WHERE course_code='B-107';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 2, 'جودة البيانات: الاكتمال والسرعة والدقة', 'Data quality: completeness, timeliness and accuracy', '[''حساب الاكتمال والسرعة من التقارير المتوقعة.'', ''التمييز بين الاكتمال والسرعة والدقة.'', ''شرح كيف يمكن أن يشوّه الغياب المنحنى ونمط المكان.'']', '[''Calculate completeness and timeliness from expected reports.'', ''Distinguish completeness, timeliness and accuracy.'', ''Explain how missingness can distort a curve and a place pattern.'']', 'لجودة البيانات أبعاد منفصلة. اكتمال الإبلاغ = التقارير المستلمة ÷ التقارير المتوقعة. ويجب عند قياس اكتمال السجلات أو الحقول تحديد السجلات أو الحقول المتوقعة. الالتزام بالموعد = التقارير المستلمة بحلول الموعد المتفق عليه ÷ التقارير المتوقعة لذلك الموعد. أما الدقة فتتعلق بمدى توافق القيم المسجلة مع أفضل مصدر أو معيار تحقق متاح؛ فقد تكون البيانات مكتملة وفي الموعد لكنها غير دقيقة. وقد يكون الفقد منهجيًا: إذا تأخر حي في الإبلاغ فقد يبدو منحناه مسطحًا بصورة مصطنعة، وإذا غاب العمر كثيرًا عن الأطفال تشوه نمط العمر. أبلغ عن البسط والمقام والفترة والموعد ومصدر البيانات لكل مؤشر جودة، ودقق عينة بمقارنتها بالسجلات الأصلية.', 'Data quality has distinct dimensions. Reporting completeness = reports received ÷ reports expected. Record-level or field-level completeness must specify the expected records or fields. Timeliness = reports received by the agreed deadline ÷ reports expected for that deadline. Accuracy concerns whether recorded values agree with the best available source or verification standard; a value can be complete and timely but inaccurate. Missingness may be systematic: if one neighbourhood reports late, its curve may look artificially flat; if age is often missing for children, the age pattern is distorted. Report the numerator, denominator, period, deadline and data source for every quality indicator, and audit a sample against original registers.', '{"exampleEn": "Field case — A district expects 40 weekly reports. It receives 34, and only 28 on time. The six missing clinics are all in one valley. The district does not conclude the valley is safe; it calls those clinics, finds a backlog of 18 cases, and adds them with their true onset dates. The corrected curve shows the valley peak was a week earlier than the late reports suggested.", "exampleAr": "حالة ميدانية — منطقة تتوقع 40 تقريرا أسبوعيا. تستلم 34، و28 فقط في الوقت. والعيادات الست الغائبة كلها في واد واحد. لا تستنتج المنطقة أن الوادي آمن؛ بل تتصل بتلك العيادات، وتجد تراكما من 18 حالة، وتضيفها بتواريخ بدئها الحقيقية. والمنحنى المصحح يظهر أن ذروة الوادي كانت قبل أسبوع مما أوحت به التقارير المتأخرة.", "fieldEn": "Report completeness and timeliness with every rate. If missingness clusters, say where — and chase it before you interpret the pattern. Reference basis: WHO AFRO, Integrated Disease Surveillance and Response Technical Guidelines, data completeness section; CDC surveillance-system evaluation guidance.", "fieldAr": "أبلغ عن الاكتمال والسرعة مع كل معدل. وإذا تجمع الغياب، قل أين — وتابعه قبل أن تفسّر النمط. مرجع المراجعة: إرشادات WHO AFRO للترصد المتكامل للأمراض والاستجابة، قسم اكتمال بيانات الترصد؛ وإرشادات CDC لتقييم نظم الترصد.", "calcTitleEn": "Worked calculation — completeness and timeliness", "calcTitleAr": "حساب محلول — الاكتمال والسرعة", "calcStepsEn": ["Step 1 — Expected weekly reports: 40 clinics × 1 report = 40.", "Step 2 — Reporting completeness: 34 received ÷ 40 expected = 85%.", "Step 3 — Timeliness: 28 received by the deadline ÷ 40 expected = 70%.", "Step 4 — Of the 40 expected reports, 6 arrived late (34 − 28) and 6 did not arrive (40 − 34). Thus 12 were not available by the deadline; 6 were ultimately missing."], "calcStepsAr": ["الخطوة 1 — التقارير الأسبوعية المتوقعة: 40 مرفقًا × تقرير واحد = 40.", "الخطوة 2 — اكتمال الإبلاغ: 34 مستلمًا ÷ 40 متوقعًا = 85%.", "الخطوة 3 — الالتزام بالموعد: 28 تقريرًا وصل في الموعد ÷ 40 متوقعًا = 70%.", "الخطوة 4 — من أصل 40 تقريرًا متوقعًا، وصل 6 متأخرة (34 − 28)، ولم يصل 6 (40 − 34). لذلك لم تتوفر 12 بحلول الموعد، وكان 6 منها مفقودًا نهائيًا."], "calcResultEn": "Result: completeness 85%, timeliness 70%. The 15-point gap means some reports arrived, but too late to guide that week''s action. Report both numbers, not only the higher one.", "calcResultAr": "النتيجة: الاكتمال 85%، والسرعة 70%. الفجوة 15 نقطة تعني أن بعض التقارير وصلت، لكن بعد فوات وقت توجيه إجراء ذلك الأسبوع. أبلغ عن الرقمين معا، لا عن الأعلى فقط.", "terms": [{"termEn": "Completeness", "termAr": "الاكتمال", "defEn": "Expected reports or fields that actually arrived and were filled.", "defAr": "التقارير أو الحقول المتوقعة التي وصلت ومُلئت فعلا."}, {"termEn": "Timeliness", "termAr": "السرعة", "defEn": "Reports arriving in time to act.", "defAr": "التقارير التي تصل في الوقت المناسب للتصرف."}, {"termEn": "Accuracy", "termAr": "الدقة", "defEn": "Values matching the truth — correct dates, diagnoses and counts.", "defAr": "القيم المطابقة للحقيقة — تواريخ وتشخيصات وأعداد صحيحة."}, {"termEn": "Missingness", "termAr": "الغياب", "defEn": "Fields or reports that are absent, often clustered in one place or group.", "defAr": "الحقول أو التقارير الغائبة، وغالبا تتجمع في مكان أو مجموعة واحدة."}], "deepSections": [{"titleEn": "The data-quality dimensions and their operational definitions", "titleAr": "أبعاد جودة البيانات وتعريفاتها التشغيلية", "bodyEn": "Data quality is multidimensional. Completeness, accuracy and timeliness are core surveillance dimensions, but they do not exhaust the question. Validity asks whether a value or classification measures what it is intended to measure. Reliability asks whether the same process produces sufficiently consistent results under comparable conditions. Consistency asks whether values obey internal rules and agree across files or time. Comparability asks whether definitions, units, populations and time periods are sufficiently aligned to support comparison. Representativeness asks whether the observed records reflect the target population and distribution. Uniqueness asks whether each intended unit is represented once. Integrity asks whether data remain complete and unaltered except through authorised, traceable changes. Accessibility and confidentiality determine whether authorised users can use the data safely.\n\nOperational definitions must be written before calculating indicators. Reporting completeness may be defined as the number of expected reports received by the extraction cut-off divided by the number expected. Timeliness may be defined as reports received by a stated deadline divided by reports expected for that deadline. These measures are not interchangeable. A report received late contributes to eventual completeness but not to timeliness at the deadline. Field completeness is different again: for example, the percentage of case records with a known onset date among all records for which onset date is required. Do not mix report-level completeness with variable-level completeness.\n\nAccuracy cannot be established by a high completeness percentage. It requires verification against an appropriate reference, such as a source register, laboratory result, chart review or repeat interview. A small audit sample can estimate the frequency and type of discrepancies, but the sample selection and verification standard must be documented. Validity checks include plausible date order (onset cannot ordinarily precede birth), valid age units, permissible codes, and agreement between case classification and the documented criteria. Automated checks detect impossible or inconsistent values; they do not prove that plausible values are true. For example, an age of 35 may be syntactically valid but still belong to the wrong person.\n\nTimeliness should be measured as a process, not just one overall interval. Useful intervals include event onset to care seeking, care seeking to diagnosis, diagnosis to notification, notification to district review, and review to response. Define the start and end timestamps, time zone, working-day rules and acceptable threshold. Report median and distribution where delays are skewed; the mean alone can be dominated by a few extreme delays. In emergencies, a timely but incomplete alert may be more useful than a perfect report received too late, but the uncertainty must be stated and the record updated later.", "bodyAr": "جودة البيانات متعددة الأبعاد. ويعد الاكتمال والدقة والالتزام بالوقت أبعادًا أساسية في الترصد، لكنها لا تستنفد المسألة. تسأل الصلاحية هل تقيس القيمة أو الفئة ما يُراد قياسه؟ وتسأل الموثوقية هل تنتج العملية نفسها نتائج متسقة بما يكفي في ظروف قابلة للمقارنة؟ ويسأل الاتساق هل تلتزم القيم بالقواعد الداخلية وتتوافق بين الملفات أو عبر الزمن؟ وتسأل قابلية المقارنة هل تتوافق التعريفات والوحدات والسكان والفترات بما يكفي لإجراء مقارنة؟ وتسأل التمثيلية هل تعكس السجلات المرصودة السكان المستهدفين وتوزيعهم؟ وتسأل الوحدانية هل مُثّل كل عنصر مطلوب مرة واحدة؟ أما سلامة البيانات فتسأل هل بقيت كاملة وغير معدلة إلا بتغييرات مصرح بها وقابلة للتتبع؟ وتحدد سهولة الوصول والسرية ما إذا كان المستخدمون المخولون يستطيعون استخدامها بأمان.\n\nيجب كتابة التعريفات التشغيلية قبل حساب المؤشرات. فقد يُعرّف اكتمال الإبلاغ بأنه عدد التقارير المتوقعة التي وصلت حتى موعد استخراج البيانات مقسومًا على العدد المتوقع. وقد يُعرّف الالتزام بالموعد بأنه التقارير التي وصلت بحلول موعد محدد مقسومة على التقارير المتوقعة لذلك الموعد. هذان المقياسان غير مترادفين. فالتقرير المتأخر يسهم في الاكتمال النهائي لكنه لا يسهم في الالتزام بالموعد عند حلول الأجل. واكتمال الحقول مختلف أيضًا؛ فمثلًا هو نسبة سجلات الحالات التي تحتوي تاريخ بدء أعراض معروفًا من بين جميع السجلات التي يُطلب فيها هذا التاريخ. لا تخلط اكتمال التقارير باكتمال المتغيرات.\n\nلا تثبت نسبة اكتمال مرتفعة دقة البيانات. فالدقة تتطلب التحقق بمصدر مرجعي مناسب، مثل سجل أصلي أو نتيجة مختبر أو مراجعة ملف طبي أو إعادة مقابلة. ويمكن لعينة تدقيق صغيرة تقدير تكرار الاختلافات وأنواعها، لكن يجب توثيق طريقة اختيار العينة ومعيار التحقق. وتشمل فحوص الصلاحية ترتيب التواريخ المعقول (فلا يسبق بدء الأعراض الميلاد عادة)، ووحدات العمر الصحيحة، والرموز المسموح بها، والتوافق بين تصنيف الحالة والمعايير الموثقة. تكشف الفحوص الآلية القيم المستحيلة أو غير المتسقة، لكنها لا تثبت أن القيم المعقولة صحيحة. فالعمر 35 قد يكون صالحًا من ناحية التنسيق لكنه يخص الشخص الخطأ.\n\nينبغي قياس الالتزام بالوقت بوصفه سلسلة عمليات، لا مدة إجمالية واحدة فقط. وتشمل الفواصل المفيدة: بدء الحدث إلى طلب الرعاية، وطلب الرعاية إلى التشخيص، والتشخيص إلى الإبلاغ، والإبلاغ إلى مراجعة المديرية، والمراجعة إلى الاستجابة. حدّد الطوابع الزمنية للبداية والنهاية والمنطقة الزمنية وقواعد أيام العمل والحد المقبول. وأبلغ عن الوسيط والتوزيع عندما تكون التأخيرات منحرفة؛ فقد يتأثر المتوسط وحده ببعض التأخيرات الشديدة. وفي الطوارئ قد يكون التنبيه السريع غير المكتمل أكثر فائدة من تقرير مثالي يصل متأخرًا، لكن يجب التصريح بعدم اليقين وتحديث السجل لاحقًا."}, {"titleEn": "Worked audit of the F-105 training dataset", "titleAr": "تدقيق محلول لمجموعة بيانات F-105 التدريبية", "bodyEn": "The following values are the course’s constructed training dataset, not observations from a real district. Four clinics each expect 10 weekly reports. Clinic A receives 9, of which 8 arrive on time; B receives 8, of which 6 are on time; C receives 9, of which 7 are on time; D receives 8, of which 7 are on time. The expected total is 4 × 10 = 40 reports. Received reports = 9 + 8 + 9 + 8 = 34. Completeness at the extraction cut-off = 34/40 × 100 = 85%. Reports received by the deadline = 8 + 6 + 7 + 7 = 28. Timeliness = 28/40 × 100 = 70%.\n\nThe six reports that arrived late by the extraction cut-off are 34 − 28 = 6. The six not received by the extraction cut-off are 40 − 34 = 6. Therefore, 12 of 40 were unavailable by the deadline; six subsequently arrived late and six remained unreceived at extraction. Do not call all 12 “missing forever”: status depends on the defined cut-off. At clinic level: A completeness 9/10 = 90%, timeliness 8/10 = 80%; B 80% and 60%; C 90% and 70%; D 80% and 70%. These figures identify where follow-up may be needed, but do not by themselves explain why the reports were delayed.\n\nThe case columns require a separate interpretation. The table lists 28, 18, 22 and 20 cases reported by clinics (88 in total), and 4, 12, 5 and 3 cases found through active case finding (24 in total). The absolute numerical differences are 24, 6, 17 and 17 respectively. Clinic A therefore has the largest numerical difference (24). However, before calling this a “reporting gap” or treating the 24 as missed unique cases, verify that the active-finding count covers the same case definition, population, period and case unit; establish whether actively found cases overlap with reported cases; and deduplicate person-level records. The column labels alone do not establish whether these are disjoint groups, overlaps or a validation sample. The safe lab answer is to report the numerical difference and explicitly state the comparability limitation.\n\nA quality dashboard should display numerator, denominator, period, cut-off and definition next to every percentage. It should show clinic-level variation rather than only a district average, because an overall 85% can conceal a remote clinic at 50%. It should also display trends over time and annotate changes in reporting forms, staffing, connectivity, catchment area and case definitions. Never rank clinics as “poor performers” before checking whether the reporting burden, connectivity and support are comparable.", "bodyAr": "القيم الآتية هي مجموعة بيانات تدريبية مصممة لهذا المقرر، وليست مشاهدات من مديرية حقيقية. تتوقع كل واحدة من أربع عيادات 10 تقارير أسبوعية. تستلم العيادة أ 9 تقارير يصل 8 منها في الوقت؛ وتستلم ب 8 يصل 6 منها في الوقت؛ وتستلم ج 9 يصل 7 منها في الوقت؛ وتستلم د 8 يصل 7 منها في الوقت. إجمالي التقارير المتوقعة = 4 × 10 = 40 تقريرًا. والتقارير المستلمة = 9 + 8 + 9 + 8 = 34. اكتمال الإبلاغ عند موعد استخراج البيانات = 34/40 × 100 = 85%. والتقارير التي وصلت في الموعد = 8 + 6 + 7 + 7 = 28. الالتزام بالموعد = 28/40 × 100 = 70%.\n\nعدد التقارير الستة التي وصلت متأخرة حتى موعد الاستخراج = 34 − 28 = 6. وعدد التقارير الستة التي لم تصل حتى موعد الاستخراج = 40 − 34 = 6. لذلك لم يكن 12 تقريرًا من أصل 40 متاحًا بحلول الموعد؛ وصل ستة منها لاحقًا، وظل ستة غير مستلمة عند الاستخراج. لا تسمِّ التقارير الاثني عشر كلها «مفقودة نهائيًا»؛ فالحالة تعتمد على موعد القطع المحدد. وعلى مستوى العيادة: اكتمال أ 9/10 = 90%، والالتزام بالموعد 8/10 = 80%؛ وب 80% و60%؛ وج 90% و70%؛ ود 80% و70%. تحدد هذه الأرقام مواضع قد تحتاج متابعة، لكنها لا تفسر وحدها سبب التأخير.\n\nتحتاج أعمدة الحالات إلى تفسير منفصل. يعرض الجدول 28 و18 و22 و20 حالة أبلغت عنها العيادات (88 إجمالًا)، و4 و12 و5 و3 حالات اكتُشفت بالبحث النشط (24 إجمالًا). والفروق العددية المطلقة هي 24 و6 و17 و17 على التوالي. لذلك تسجل العيادة أ أكبر فرق عددي (24). لكن قبل تسمية ذلك «فجوة إبلاغ» أو اعتبار الـ24 حالات فريدة فات اكتشافها، تحقق من أن عدد البحث النشط يغطي تعريف الحالة والسكان والفترة ووحدة العد نفسها؛ وحدد هل تتداخل الحالات المكتشفة نشطًا مع الحالات المبلغ عنها؛ وأزل التكرار على مستوى الشخص. لا تثبت عناوين الأعمدة وحدها ما إذا كانت المجموعتان منفصلتين أو متداخلتين أو أن إحداهما عينة تحقق. والإجابة الآمنة في المختبر هي الإبلاغ عن الفرق العددي والتصريح صراحة بقيد قابلية المقارنة.\n\nينبغي أن تعرض لوحة جودة البيانات البسط والمقام والفترة وموعد القطع والتعريف بجوار كل نسبة. كما ينبغي أن تعرض التباين بين العيادات بدل المتوسط العام فقط، لأن اكتمالًا إجماليًا قدره 85% قد يخفي عيادة نائية عند 50%. وينبغي أيضًا عرض الاتجاهات عبر الزمن ووضع علامات عند تغير نماذج الإبلاغ أو الموظفين أو الاتصال أو منطقة الخدمة أو تعريف الحالة. لا تصنف العيادات على أنها «ضعيفة الأداء» قبل التحقق من أن عبء الإبلاغ والاتصال والدعم متقاربة."}, {"titleEn": "Missing data mechanisms and a corrective-action cycle", "titleAr": "آليات البيانات المفقودة ودورة الإجراء التصحيحي", "bodyEn": "Missing data are not one condition. A report may be absent because the facility did not detect a case, detected it but did not record it, recorded it but did not submit it, submitted it after the cut-off, or submitted a file that failed ingestion. A field may be blank because it was not asked, was unknown to the respondent, was not documented, was skipped incorrectly or was lost during transfer. These mechanisms have different remedies. Distinguish “not applicable,” “unknown,” “not asked,” “not recorded,” “pending” and “not received”; do not code all of them as zero or as the same blank.\n\nIn statistical terminology, missing completely at random (MCAR) means missingness is unrelated to observed or unobserved data; missing at random (MAR) means missingness can be explained by observed information; missing not at random (MNAR) means missingness still depends on the unobserved value or an unmeasured process. These assumptions are difficult to prove from the dataset alone. For example, if remote facilities with poor connectivity are more likely to submit late, missingness is associated with observed facility location/connectivity and may be explainable by observed data. If patients with severe stigma-related symptoms are less likely to disclose them even after measured characteristics are considered, missingness may depend on the unobserved response. Do not choose an imputation method until the variable, mechanism, analysis purpose and assumptions are described. For routine surveillance, operational follow-up and transparent provisional reporting may be more appropriate than statistical imputation.\n\nUse a root-cause cycle: detect the pattern; locate the process step; interview the staff who generate the data; inspect source documents and system logs; agree a corrective action with an owner and deadline; monitor whether the indicator improves; and document unintended consequences. If onset dates are missing in one clinic, the remedy may be a revised form and coaching, not deleting those cases. If reports are late because the network is unavailable, an approved offline form and later reconciliation may help. If duplicate records rise after a software change, review the identifier and matching rules. If the case definition changed, do not splice old and new series without an explicit bridge or reclassification plan.\n\nFor analysis, describe the extent and pattern of missingness by variable, clinic, age, sex, place and time when lawful and relevant. State the denominator used for each percentage. Avoid complete-case analysis as an automatic default: it can change the analytic population and introduce selection bias if completeness is associated with exposure or outcome. Do not impute identifiers or fabricate onset dates. Any imputation for analytical variables must be justified, reproducible, and accompanied by sensitivity analysis where assumptions are uncertain.", "bodyAr": "ليست البيانات المفقودة حالة واحدة. فقد يغيب التقرير لأن المرفق لم يكتشف الحالة، أو اكتشفها ولم يسجلها، أو سجلها ولم يرسلها، أو أرسلها بعد موعد القطع، أو أرسل ملفًا فشل النظام في إدخاله. وقد يكون الحقل فارغًا لأنه لم يُسأل، أو لم يعرفه المجيب، أو لم يوثق، أو تم تجاوزه خطأ، أو فُقد أثناء النقل. ولكل آلية علاج مختلف. ميّز بين «لا ينطبق» و«غير معروف» و«لم يُسأل» و«لم يُسجل» و«قيد الانتظار» و«لم يُستلم»؛ ولا ترمز إليها كلها بصفر أو فراغ واحد.\n\nفي المصطلحات الإحصائية، يعني الفقد العشوائي تمامًا أن الفقد لا يرتبط بالبيانات المرصودة أو غير المرصودة؛ ويعني الفقد العشوائي المشروط أن الفقد يمكن تفسيره بمعلومات مرصودة؛ أما الفقد غير العشوائي فيعني أن الفقد يظل معتمدًا على القيمة غير المرصودة أو عملية غير مقاسة. يصعب إثبات هذه الافتراضات من مجموعة البيانات وحدها. فمثلًا إذا كانت المرافق النائية ذات الاتصال الضعيف أكثر عرضة للتأخر، يرتبط الفقد بمعلومات مرصودة عن الموقع والاتصال وقد يمكن تفسيره بها. أما إذا كان المرضى ذوو الأعراض المرتبطة بالوصمة أقل إفصاحًا عنها حتى بعد مراعاة الخصائص المقاسة، فقد يعتمد الفقد على الإجابة غير المرصودة. لا تختر طريقة تعويض إحصائي قبل وصف المتغير والآلية وغرض التحليل والافتراضات. وفي الترصد الروتيني قد تكون المتابعة التشغيلية والإبلاغ المؤقت الشفاف أنسب من التعويض الإحصائي.\n\nاستخدم دورة لمعالجة السبب الجذري: اكتشف النمط؛ وحدد خطوة العملية التي حدث فيها؛ وقابل الموظفين الذين ينتجون البيانات؛ وافحص المستندات الأصلية وسجلات النظام؛ واتفق على إجراء تصحيحي له مسؤول وموعد؛ وراقب تحسن المؤشر؛ ووثق الآثار غير المقصودة. إذا كانت تواريخ بدء الأعراض مفقودة في عيادة واحدة فقد يكون العلاج تعديل النموذج والتدريب، لا حذف الحالات. وإذا تأخرت التقارير بسبب انقطاع الشبكة فقد يساعد نموذج غير متصل مع تسوية لاحقة معتمدة. وإذا زادت السجلات المكررة بعد تحديث برمجي، فراجع المعرّف وقواعد المطابقة. وإذا تغير تعريف الحالة، فلا تصل السلسلة القديمة بالجديدة دون خطة ربط أو إعادة تصنيف واضحة.\n\nفي التحليل، صف مقدار الفقد ونمطه حسب المتغير والعيادة والعمر والجنس والمكان والزمن عندما يكون ذلك قانونيًا وذا صلة. واذكر المقام المستخدم لكل نسبة. لا تجعل تحليل الحالات المكتملة الخيار الافتراضي تلقائيًا؛ فقد يغير السكان التحليليين ويُدخل تحيز اختيار إذا ارتبط الاكتمال بالتعرض أو النتيجة. لا تعوض المعرّفات ولا تختلق تواريخ بدء الأعراض. ويجب تبرير أي تعويض لمتغيرات التحليل وجعله قابلًا لإعادة الإنتاج، مع تحليل حساسية عندما تكون الافتراضات غير مؤكدة."}], "objEn": ["Calculate completeness and timeliness from expected reports.", "Distinguish completeness, timeliness and accuracy.", "Explain how missingness can distort a curve and a place pattern."], "objAr": ["حساب الاكتمال والسرعة من التقارير المتوقعة.", "التمييز بين الاكتمال والسرعة والدقة.", "شرح كيف يمكن أن يشوّه الغياب المنحنى ونمط المكان."]}', '[{"qEn": "34 of 40 expected reports is…", "qAr": "34 من 40 تقريرا متوقعا هي…", "optsEn": ["70% complete", "85% complete", "34% complete"], "optsAr": ["70% مكتملة", "85% مكتملة", "34% مكتملة"], "ans": 1, "explEn": "34 ÷ 40 = 0.85 = 85%.", "explAr": "34 ÷ 40 = 0.85 = 85%."}, {"qEn": "28 of 40 reports on time is…", "qAr": "28 من 40 تقريرا في الوقت هي…", "optsEn": ["85% timely", "28% timely", "70% timely"], "optsAr": ["85% في الوقت", "28% في الوقت", "70% في الوقت"], "ans": 2, "explEn": "28 ÷ 40 = 70% of expected reports received by the stated deadline; state the deadline and denominator.", "explAr": "28 ÷ 40 = 70% من التقارير المتوقعة التي وصلت بحلول الموعد المحدد؛ اذكر الموعد والمقام."}, {"qEn": "Completeness and timeliness differ because…", "qAr": "الاكتمال والسرعة يختلفان لأن…", "optsEn": ["A report can arrive but too late to act", "They use different populations", "One is a count and one is a ratio"], "optsAr": ["التقرير قد يصل لكن بعد فوات وقت التصرف", "يستخدمان سكانا مختلفين", "أحدهما عدد والآخر نسبة"], "ans": 0, "explEn": "Completeness counts arrival; timeliness counts arrival in time.", "explAr": "الاكتمال يعدّ الوصول؛ والسرعة تعدّ الوصول في الوقت."}, {"qEn": "If missing reports cluster in one valley, you should…", "qAr": "إذا تجمعت التقارير الغائبة في واد واحد، يجب أن…", "optsEn": ["Conclude the valley is safe", "Chase those clinics before interpreting the pattern", "Delete the other reports"], "optsAr": ["تستنتج أن الوادي آمن", "تتابع تلك العيادات قبل تفسير النمط", "تحذف التقارير الأخرى"], "ans": 1, "explEn": "Clustered missingness can hide a real rise.", "explAr": "الغياب المتجمع قد يخفي ارتفاعا حقيقيا."}]' FROM courses WHERE course_code='B-107';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 3, 'التحيز: الاختيار والمعلومات والإرباك', 'Bias: selection, information and confounding', '[''تسمية تحيز الاختيار والمعلومات والإرباك في مثال.'', ''شرح كيف يدفع كل منها النتيجة بعيدا عن الحقيقة.'', ''اختيار طريقة عملية واحدة للكشف عن كل تحيز وواحدة للحد منه.'']', '[''Name selection, information and confounding bias in an example.'', ''Explain how each one moves a result away from the truth.'', ''Choose one practical way to detect and one to reduce each bias.'']', 'التحيز خطأ منهجي. ينشأ تحيز الاختيار عندما يرتبط الإدراج في الدراسة أو الاستمرار فيها بالتعرض والنتيجة. وينشأ تحيز المعلومات عندما يُقاس التعرض أو النتيجة أو المتغيرات المصاحبة أو تُصنف بصورة غير دقيقة أو مختلفة بين المجموعات. العامل المربك سبب مشترك سابق للتعرض (أو بديل مناسب له) يرتبط بالتعرض والنتيجة، وليس متغيرًا وسيطًا على المسار السببي؛ وليس كل متغير يرتبط بكليهما عاملًا مربكًا. استخدم المعرفة الموضوعية ومخططًا سببيًا قبل الضبط؛ فالتحكم في وسيط أو متغير مصادم قد يُدخل تحيزًا. وقد يكشف التقسيم الطبقي اختلاف الارتباط الخام عبر مستويات العامل المربك، لكن تقديرًا معدلًا يتطلب بيانات صحيحة لكل طبقة وطرقًا مناسبة.', 'Bias is systematic error. Selection bias arises when inclusion or retention in a study is related to exposure and outcome. Information bias arises when exposure, outcome or covariates are measured or classified inaccurately or differently between groups. A confounder is a pre-exposure common cause (or a suitable proxy) associated with both exposure and outcome, and is not an intermediate on the causal pathway; not every variable associated with both is a confounder. Use subject-matter knowledge and a causal diagram before adjustment: controlling for a mediator or collider can introduce bias. Stratification can reveal whether a crude association differs across levels of a confounder, but adjusted estimates require valid stratum-specific data and appropriate methods.', '{"exampleEn": "Field case — Two clinics appear to have different crude case-fatality proportions. Clinic A treats a larger share of older patients. After age stratification, the age-specific proportions are similar. Before adjustment, the team checks whether age is a genuine pre-exposure confounder for the question, and whether testing, referral and case definitions differ between clinics. It reports the crude and stratum-specific results with denominators instead of ranking clinics from the crude figure alone.", "exampleAr": "حالة ميدانية — يبدو أن نسب إماتة الحالات الخام تختلف بين عيادتين. تعالج العيادة أ نسبة أكبر من المرضى الأكبر سنًا. وبعد التقسيم حسب العمر، تتشابه النسب الخاصة بكل فئة عمرية. قبل الضبط، يتحقق الفريق مما إذا كان العمر عاملًا مربكًا سابقًا للتعرض فعلًا بالنسبة للسؤال، وما إذا كان الفحص والإحالة وتعريف الحالة تختلف بين العيادتين. ويبلغ النتائج الخام ونتائج الطبقات مع المقامات بدل ترتيب العيادات اعتمادًا على الرقم الخام وحده.", "fieldEn": "Before you calculate, list three suspects: who was selected, how was it measured, and what third factor could explain it? Reference basis: CDC Principles of Epidemiology; causal diagrams and confounder selection should be based on temporal and subject-matter knowledge.", "fieldAr": "قبل أن تحسب، اسرد ثلاثة مشتبهين: من تم اختياره، وكيف قيس، وأي عامل ثالث قد يفسره؟ مرجع المراجعة: مبادئ علم الوبائيات لدى CDC؛ ويجب أن يستند اختيار العوامل المربكة ومخططات السببية إلى المعرفة الموضوعية والترتيب الزمني.", "calcTitleEn": "Worked calculation — confounding by age", "calcTitleAr": "حساب محلول — الإرباك بالعمر", "calcStepsEn": ["Step 1 — Group A: 400 younger people, 40 cases (10%); 600 older people, 240 cases (40%). Overall: 280/1,000 = 28%.", "Step 2 — Group B: 1,300 younger people, 130 cases (10%); 200 older people, 80 cases (40%). Overall: 210/1,500 = 14%.", "Step 3 — Crude RR = 28% ÷ 14% = 2.0. Within younger people RR = 10% ÷ 10% = 1.0; within older people RR = 40% ÷ 40% = 1.0.", "Step 4 — The crude contrast is explained by the different age composition in this constructed example. This illustrates confounding; a real analysis must assess design, measurement and causal assumptions."], "calcStepsAr": ["الخطوة 1 — المجموعة أ: 400 أصغر سنًا، بينهم 40 حالة (10%)؛ و600 أكبر سنًا، بينهم 240 حالة (40%). الإجمالي: 280/1000 = 28%.", "الخطوة 2 — المجموعة ب: 1300 أصغر سنًا، بينهم 130 حالة (10%)؛ و200 أكبر سنًا، بينهم 80 حالة (40%). الإجمالي: 210/1500 = 14%.", "الخطوة 3 — الخطر النسبي الخام = 28% ÷ 14% = 2.0. وبين الأصغر سنًا = 10% ÷ 10% = 1.0؛ وبين الأكبر سنًا = 40% ÷ 40% = 1.0.", "الخطوة 4 — يفسر اختلاف التركيب العمري المقارنة الخام في هذا المثال المصمم. وهذا يوضح الإرباك؛ أما التحليل الحقيقي فيتطلب تقييم التصميم والقياس والافتراضات السببية."], "calcResultEn": "Result: crude RR 2.0, age-specific RR 1.0 in both strata. Stratification revealed the confounding. Always look at stratified results before trusting a crude ratio.", "calcResultAr": "النتيجة: الخطر النسبي الخام 2.0، والخطر النسبي الخاص بالعمر 1.0 في الطبقتين. التقسيم الطبقي كشف الإرباك. انظر دائما إلى النتائج المقسمة قبل الوثوق بنسبة خام.", "terms": [{"termEn": "Selection bias", "termAr": "تحيز الاختيار", "defEn": "Distortion from how people enter or stay in the study.", "defAr": "تشويه ناتج عن طريقة دخول الناس إلى الدراسة أو بقائهم فيها."}, {"termEn": "Information bias", "termAr": "تحيز المعلومات", "defEn": "Distortion from measuring exposure or outcome differently between groups.", "defAr": "تشويه ناتج عن قياس التعرض أو النتيجة بشكل مختلف بين المجموعتين."}, {"termEn": "Confounding", "termAr": "الإرباك", "defEn": "A third factor linked to exposure and outcome that distorts the comparison.", "defAr": "عامل ثالث مرتبط بالتعرض والنتيجة يشوّه المقارنة."}, {"termEn": "Stratification", "termAr": "التقسيم الطبقي", "defEn": "Splitting the analysis by the confounder, e.g. by age group, to compare like with like.", "defAr": "تقسيم التحليل حسب الإرباك، مثلا حسب الفئة العمرية، لمقارنة المتشابه بالمتشابه."}], "deepSections": [{"titleEn": "Selection bias: who enters, remains and is observed", "titleAr": "تحيز الاختيار: من يدخل الدراسة ويبقى فيها ويُلاحظ", "bodyEn": "Selection bias occurs when the process determining who is included, observed or retained creates a distorted exposure–outcome comparison. It is not simply “a small sample” or “a sample that differs from the population”; the critical issue is whether selection is related to exposure and outcome, or their causes, in a way that changes the association being estimated. Examples include hospital-based studies in which both exposure and disease severity influence admission; nonresponse that differs by exposure and outcome; loss to follow-up related to prognosis; and testing restricted to people with particular symptoms or access to care.\n\nAsk three questions: Who was eligible? Who was actually included? Who was not observed or was lost, and why? Compare included and excluded people using available characteristics. Examine recruitment and follow-up separately by exposure and outcome. Record refusal, ineligibility, non-contact, transfer and loss-to-follow-up reasons using standard categories. If a sample is designed for surveillance or sentinel monitoring rather than population estimation, describe its coverage and do not claim population representativeness without a valid sampling framework.\n\nPractical prevention begins at design: define the source population and eligibility criteria before recruitment; use the same recruitment pathway for comparison groups where possible; maximise follow-up; document reasons for non-participation; and avoid conditioning on variables that are consequences of both exposure and outcome. Statistical weighting or sensitivity analysis may help under explicit assumptions, but cannot guarantee removal of unmeasured selection bias. A larger sample reduces random error, not systematic selection error.\n\nCase example: investigators compare severe outcomes among patients referred to a tertiary hospital. Exposure may increase disease severity and therefore referral; an unrelated condition may also increase referral and independently affect outcome. Restricting analysis to referred patients can induce an association between exposure and the unrelated condition even if none exists in the source population. The hospital sample is useful for describing its admitted patients, but the crude association should not be generalised to all community cases without addressing the referral process.", "bodyAr": "ينشأ تحيز الاختيار عندما تؤدي العملية التي تحدد من يُدرج أو يُلاحظ أو يستمر في الدراسة إلى تشويه مقارنة التعرض بالنتيجة. ولا يعني ببساطة «عينة صغيرة» أو «عينة تختلف عن السكان»؛ فالمسألة الحاسمة هي ما إذا كان الاختيار مرتبطًا بالتعرض والنتيجة، أو بأسبابهما، بطريقة تغير الارتباط المراد تقديره. ومن أمثلته الدراسات المعتمدة على المستشفيات عندما يؤثر كل من التعرض وشدة المرض في الدخول؛ وعدم الاستجابة المختلف حسب التعرض والنتيجة؛ والفقد من المتابعة المرتبط بالتنبؤ المرضي؛ وقصر الفحص على أشخاص لديهم أعراض معينة أو إمكانية وصول للرعاية.\n\nاطرح ثلاثة أسئلة: من كان مؤهلًا؟ ومن أُدرج فعليًا؟ ومن لم يُلاحظ أو فُقد، ولماذا؟ قارن المشاركين وغير المشاركين باستخدام الخصائص المتاحة. وافحص الاستقطاب والمتابعة بصورة منفصلة حسب التعرض والنتيجة. وسجل الرفض وعدم الأهلية وتعذر الاتصال والتحويل والفقد من المتابعة ضمن فئات موحدة. وإذا صُممت العينة للترصد أو الرصد الحارسي لا للتقدير السكاني، فصف تغطيتها ولا تدّع تمثيل السكان دون إطار معاينة صالح.\n\nتبدأ الوقاية العملية من التصميم: عرّف المجتمع المصدر ومعايير الأهلية قبل التجنيد؛ واستخدم مسار تجنيد واحدًا لمجموعات المقارنة متى أمكن؛ وعظّم المتابعة؛ ووثق أسباب عدم المشاركة؛ وتجنب الاشتراط على متغيرات ناتجة عن كل من التعرض والنتيجة. وقد تساعد الأوزان الإحصائية أو تحليلات الحساسية عند إعلان افتراضاتها، لكنها لا تضمن إزالة تحيز اختيار غير مقاس. فزيادة حجم العينة تقلل الخطأ العشوائي، لا خطأ الاختيار المنهجي.\n\nمثال حالة: يقارن باحثون النتائج الشديدة بين المرضى المحالين إلى مستشفى مرجعي ثالثي. قد يزيد التعرض شدة المرض وبالتالي الإحالة؛ وقد تزيد حالة أخرى غير مرتبطة بالتعرض احتمال الإحالة وتؤثر بصورة مستقلة في النتيجة. إن قصر التحليل على المحالين قد ينشئ ارتباطًا بين التعرض والحالة الأخرى حتى لو لم يوجد ذلك في المجتمع المصدر. وتفيد عينة المستشفى في وصف المرضى المقبولين فيه، لكن لا يجوز تعميم الارتباط الخام على جميع حالات المجتمع دون معالجة عملية الإحالة."}, {"titleEn": "Information bias and misclassification", "titleAr": "تحيز المعلومات وسوء التصنيف", "bodyEn": "Information bias is systematic error arising from how exposure, outcome or covariates are elicited, measured, recorded, coded or classified. Common mechanisms include recall bias, interviewer bias, observer bias, diagnostic suspicion bias, inaccurate instruments, inconsistent case definitions, proxy reporting and data-entry errors. A variable may be missing, measured with error, or classified differently across comparison groups. Distinguish random measurement error from systematic measurement error: random error often reduces precision and may dilute an association in some settings, whereas systematic error can move an estimate in either direction.\n\nMisclassification is non-differential when the probability of classification error does not differ by the other variable of interest, and differential when it does. Do not teach that non-differential misclassification always biases results toward the null; that simplification is not universally true, especially with multiple exposure/outcome categories, dependent errors or complex designs. The direction and magnitude depend on the classification structure and analysis. For a binary outcome, sensitivity and specificity of case ascertainment can help characterise misclassification if a credible reference standard and suitable validation sample exist. Positive predictive value depends on prevalence in the tested population, so a PPV from a hospital sample may not transfer to a community setting.\n\nPrevention is procedural: use a stable written case definition; train interviewers; standardise question wording and recall periods; use calibrated equipment; blind outcome assessors to exposure where feasible; validate a sample against records or laboratory standards; add range, logic and skip checks; and maintain a change log for form versions. A validation study should report how records were sampled, the reference standard, the time interval between measurements, and uncertainty around sensitivity and specificity. Do not “correct” the entire dataset using one validation estimate without checking whether error rates vary by clinic, age, severity or time.\n\nWorked diagnostic example: suppose a training exercise includes 100 people with a reference-standard disease status, and a screening classification identifies 80 true positives, 10 false positives, 5 false negatives and 5 true negatives. Sensitivity = 80/(80+5) = 94.1%; specificity = 5/(5+10) = 33.3%. The exercise illustrates that high sensitivity can coexist with poor specificity. These constructed numbers are not evidence about any real test. The correct response is to examine the intended screening purpose, confirm the reference standard, and assess whether false positives create avoidable workload or harm.", "bodyAr": "ينشأ تحيز المعلومات من خطأ منهجي في كيفية استقصاء التعرض أو النتيجة أو المتغيرات المصاحبة أو قياسها أو تسجيلها أو ترميزها أو تصنيفها. وتشمل الآليات الشائعة تحيز التذكر وتحيز القائم بالمقابلة وتحيز الملاحظ وتحيز الاشتباه التشخيصي والأدوات غير الدقيقة وتعريفات الحالة غير المتسقة والإبلاغ بالوكالة وأخطاء إدخال البيانات. وقد يكون المتغير مفقودًا أو مقاسًا بخطأ أو مصنفًا بصورة مختلفة بين مجموعات المقارنة. ميّز بين خطأ القياس العشوائي والمنهجي: فالخطأ العشوائي يقلل الدقة غالبًا وقد يضعف الارتباط في بعض السياقات، بينما قد يدفع الخطأ المنهجي التقدير في أي اتجاه.\n\nيكون سوء التصنيف غير تفاضلي عندما لا يختلف احتمال خطأ التصنيف بحسب المتغير الآخر محل الاهتمام، ويكون تفاضليًا عندما يختلف. لا تدرّس أن سوء التصنيف غير التفاضلي يدفع النتائج دائمًا نحو القيمة الصفرية؛ فهذا تبسيط غير صحيح على نحو عام، خصوصًا مع فئات متعددة للتعرض أو النتيجة أو أخطاء مترابطة أو تصاميم معقدة. يعتمد الاتجاه والحجم على بنية التصنيف والتحليل. وفي النتيجة الثنائية قد تساعد الحساسية والنوعية في توصيف سوء تصنيف اكتشاف الحالات إذا توفر معيار مرجعي موثوق وعينة تحقق مناسبة. وتعتمد القيمة التنبؤية الموجبة على الانتشار في السكان المفحوصين، ولذلك قد لا تنتقل قيمة تنبؤية من عينة مستشفى إلى المجتمع.\n\nالوقاية إجرائية: استخدم تعريف حالة مكتوبًا وثابتًا؛ ودرب القائمين بالمقابلات؛ ووحّد صياغة الأسئلة وفترات التذكر؛ وعاير الأجهزة؛ وعمّ التقييم عن التعرض متى أمكن؛ وتحقق من عينة بمقارنتها بالسجلات أو المعايير المخبرية؛ وأضف فحوص المدى والمنطق والتجاوز؛ واحتفظ بسجل تغييرات إصدارات النماذج. وينبغي لدراسة التحقق أن تذكر طريقة سحب السجلات والمعيار المرجعي والفاصل الزمني بين القياسين وعدم اليقين حول الحساسية والنوعية. لا «تصحح» مجموعة البيانات كلها باستخدام تقدير تحقق واحد دون التأكد من عدم اختلاف معدلات الخطأ حسب العيادة أو العمر أو الشدة أو الزمن.\n\nمثال تشخيصي محلول: لنفترض أن تمرينًا تدريبيًا يتضمن 100 شخص مع حالة مرضية محددة بمعيار مرجعي، وأن التصنيف التحري حدد 80 إيجابيًا حقيقيًا و10 إيجابيين كاذبين و5 سلبيين كاذبين و5 سلبيين حقيقيين. الحساسية = 80/(80+5) = 94.1%؛ والنوعية = 5/(5+10) = 33.3%. يوضح المثال المصمم أن الحساسية العالية قد تجتمع مع نوعية ضعيفة. وهذه الأرقام المصطنعة ليست دليلًا عن اختبار حقيقي. والاستجابة الصحيحة هي مراجعة غرض التحري المقصود، والتحقق من المعيار المرجعي، وتقييم ما إذا كانت الإيجابيات الكاذبة تسبب عبئًا أو ضررًا يمكن تجنبه."}, {"titleEn": "Confounding, mediation, colliders and stratified analysis", "titleAr": "الإرباك والوساطة والمصادمات والتحليل الطبقي", "bodyEn": "Confounding is a distortion of the exposure–outcome contrast caused by a third variable that is associated with exposure and outcome and is not an intermediate on the causal pathway. In a causal interpretation, a candidate confounder should precede exposure (or represent a pre-exposure common cause), be associated with exposure in the source population, and predict the outcome independently of exposure. These are conceptual criteria, not a mechanical checklist: subject-matter knowledge, temporal ordering and a causal model are essential. A variable can be associated with exposure and outcome because it is a mediator or collider; adjusting for it may block part of the effect or open a non-causal path.\n\nA directed acyclic graph (DAG) is a diagram of hypothesised causal arrows. It does not prove causality; it makes assumptions explicit. A mediator lies on the pathway from exposure to outcome. If the aim is the total effect, adjusting for a mediator usually removes part of that total effect. A collider is a common effect of two variables; conditioning on it can create a spurious association between its causes. For example, both disease severity and access to care may influence hospital admission. Restricting to admitted patients can induce an association between severity-related exposure and access-related factors. Do not adjust for every variable available in the dataset.\n\nStratification compares like with like across levels of a candidate confounder. In the existing constructed example, Group A has 40/400 = 10% risk among younger people and 240/600 = 40% among older people; overall 280/1,000 = 28%. Group B has 130/1,300 = 10% among younger people and 80/200 = 40% among older people; overall 210/1,500 = 14%. The crude risk ratio is 28%/14% = 2.0, while the age-specific risk ratios are 10%/10% = 1.0 and 40%/40% = 1.0. The groups have different age compositions, and within each age stratum risks are equal; this illustrates age confounding in the constructed dataset. It does not establish that every crude/stratum difference is confounding: effect modification can also produce different stratum-specific effects. Examine stratum estimates, precision, plausibility and the causal question before combining them.\n\nWhen strata have sufficiently comparable effects and assumptions support it, a standardised or Mantel–Haenszel estimate may summarise the adjusted association. State the method, weights, strata, missing-data handling and assumptions. If stratum-specific estimates differ materially, report the heterogeneity and consider effect modification rather than forcing one pooled number. An adjusted estimate is not automatically causal; residual confounding, selection, information bias and model misspecification may remain.", "bodyAr": "الإرباك هو تشويه المقارنة بين التعرض والنتيجة بسبب متغير ثالث يرتبط بالتعرض والنتيجة ولا يقع وسيطًا على المسار السببي. وفي التفسير السببي ينبغي أن يسبق العامل المرشح للإرباك التعرض (أو يمثل سببًا مشتركًا سابقًا له)، وأن يرتبط بالتعرض في المجتمع المصدر، وأن يتنبأ بالنتيجة بصورة مستقلة عن التعرض. هذه معايير مفاهيمية وليست قائمة آلية؛ فالمعرفة الموضوعية والترتيب الزمني والنموذج السببي أساسية. وقد يرتبط متغير بالتعرض والنتيجة لأنه وسيط أو مصادم؛ وضبطه قد يحجب جزءًا من الأثر أو يفتح مسارًا غير سببي.\n\nالمخطط السببي الموجه غير الدوري (DAG) رسم للأسهم السببية المفترضة. لا يثبت السببية، بل يجعل الافتراضات صريحة. يقع الوسيط على المسار من التعرض إلى النتيجة. فإذا كان الهدف تقدير الأثر الكلي، فإن ضبط الوسيط يزيل عادة جزءًا من ذلك الأثر الكلي. أما المصادم فهو أثر مشترك لمتغيرين؛ وقد يؤدي الاشتراط عليه إلى إنشاء ارتباط زائف بين أسبابه. فمثلًا قد تؤثر شدة المرض وإمكانية الوصول للرعاية في دخول المستشفى معًا. وقصر التحليل على المرضى المقبولين قد ينشئ ارتباطًا بين التعرض المرتبط بالشدة والعوامل المرتبطة بإمكانية الوصول. لا تضبط كل متغير متاح في مجموعة البيانات.\n\nيقارن التقسيم الطبقي المتشابه بالمتشابه عبر مستويات العامل المرشح للإرباك. في المثال التدريبي المصمم الموجود، لدى المجموعة أ خطر 40/400 = 10% بين الأصغر سنًا و240/600 = 40% بين الأكبر سنًا؛ والإجمالي 280/1000 = 28%. ولدى المجموعة ب خطر 130/1300 = 10% بين الأصغر سنًا و80/200 = 40% بين الأكبر سنًا؛ والإجمالي 210/1500 = 14%. الخطر النسبي الخام = 28%/14% = 2.0، بينما الخطر النسبي الخاص بالعمر = 10%/10% = 1.0 و40%/40% = 1.0. يختلف التركيب العمري بين المجموعتين، وتتساوى المخاطر داخل كل طبقة عمرية؛ وهذا يوضح الإرباك بالعمر في مجموعة البيانات المصممة. لكنه لا يثبت أن كل اختلاف بين التقدير الخام والطبقي هو إرباك؛ فقد يعكس تعديل الأثر أيضًا اختلاف التقديرات بين الطبقات. افحص تقديرات الطبقات ودقتها ومعقوليتها والسؤال السببي قبل دمجها.\n\nعندما تكون آثار الطبقات متقاربة بما يكفي وتدعم الافتراضات ذلك، يمكن لتقدير معياري أو تقدير مانتل–هانزل تلخيص الارتباط المعدل. اذكر الطريقة والأوزان والطبقات ومعالجة البيانات المفقودة والافتراضات. وإذا اختلفت تقديرات الطبقات بصورة مهمة، فأبلغ عن عدم التجانس وفكر في تعديل الأثر بدل فرض رقم مجمع واحد. والتقدير المعدل ليس سببيًا تلقائيًا؛ فقد يبقى إرباك متبقٍ وتحيز اختيار وتحيز معلومات وخطأ في تحديد النموذج."}], "objEn": ["Name selection, information and confounding bias in an example.", "Explain how each one moves a result away from the truth.", "Choose one practical way to detect and one to reduce each bias."], "objAr": ["تسمية تحيز الاختيار والمعلومات والإرباك في مثال.", "شرح كيف يدفع كل منها النتيجة بعيدا عن الحقيقة.", "اختيار طريقة عملية واحدة للكشف عن كل تحيز وواحدة للحد منه."]}', '[{"qEn": "Only severe cases reaching hospital is an example of…", "qAr": "وصول الحالات الشديدة فقط إلى المستشفى مثال على…", "optsEn": ["Information bias", "Confounding", "Selection bias"], "optsAr": ["تحيز المعلومات", "الإرباك", "تحيز الاختيار"], "ans": 2, "explEn": "Who enters the study drives selection bias.", "explAr": "من يدخل الدراسة يقود تحيز الاختيار."}, {"qEn": "Interviewing cases longer than controls causes…", "qAr": "مقابلة الحالات أطول من الشواهد تسبب…", "optsEn": ["Information bias", "A larger denominator", "A confirmed case"], "optsAr": ["تحيز المعلومات", "مقاما أكبر", "حالة مؤكدة"], "ans": 0, "explEn": "Unequal measurement is information bias.", "explAr": "القياس غير المتساوي هو تحيز المعلومات."}, {"qEn": "Crude RR 2.0 but age-specific RR 1.0 in both strata means…", "qAr": "الخطر النسبي الخام 2.0 لكن الخاص بالعمر 1.0 في الطبقتين يعني…", "optsEn": ["Age is irrelevant", "Age confounded the crude comparison", "The crude RR was correct"], "optsAr": ["العمر غير مهم", "العمر أربك المقارنة الخام", "الخطر النسبي الخام كان صحيحا"], "ans": 1, "explEn": "Both age-specific RRs are 1.0 while age composition differs sharply; the crude RR of 2.0 is confounded by age in this example.", "explAr": "نسبتا الخطر داخل فئتي العمر تساويان 1.0 مع اختلاف واضح في التركيب العمري؛ لذا فالعمر يربك الخطر النسبي الخام 2.0 في هذا المثال."}, {"qEn": "A practical way to reduce information bias is to…", "qAr": "طريقة عملية للحد من تحيز المعلومات هي أن…", "optsEn": ["Interview only cases", "Change the case definition mid-study", "Use the same interview and case definition for everyone"], "optsAr": ["تقابل الحالات فقط", "تغير تعريف الحالة أثناء الدراسة", "تستخدم نفس المقابلة وتعريف الحالة للجميع"], "ans": 2, "explEn": "Equal measurement for all groups reduces information bias.", "explAr": "القياس المتساوي لكل المجموعات يحد من تحيز المعلومات."}]' FROM courses WHERE course_code='B-107';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 1, 'أنواع البيانات ومقاييس التلخيص', 'Types of data and summary measures', '[''التمييز بين البيانات الفئوية والمستمرة.'', ''حساب المتوسط والوسيط والمنوال والمدى والمدى الربيعي والانحراف المعياري لمجموعة صغيرة.'', ''اختيار تلخيص يناسب شكل البيانات.'']', '[''Distinguish categorical and continuous data.'', ''Calculate mean, median, mode, range, IQR and SD for a small dataset.'', ''Choose a summary that fits the shape of the data.'']', 'البيانات نوعان واسعان. البيانات الفئوية تضع الناس في مجموعات: الجنس والحي وحالة الحالة. وتلخّصها بالأعداد والنسب المئوية. والبيانات المستمرة تقيس كمية: العمر وتأخر البدء بالأيام والحرارة. وتلخّصها بمركز وانتشار. والمتوسط هو المجموع مقسوما على ن. والوسيط هو القيمة الوسطى عندما تُرتّب البيانات — نصف دونها ونصف فوقها. والمنوال هو القيمة الأكثر تكرارا. والمدى هو الأعلى ناقص الأدنى. والمدى الربيعي هو الوسط 50%: من المئين 25 إلى المئين 75. والانحراف المعياري هو المسافة النموذجية عن المتوسط. وعندما تشوّه البيانات قيمة واحدة كبيرة جدا، يُسحب المتوسط نحوها ويبقى الوسيط أكثر تمثيلا. لذلك يجب أن تنظر دائما إلى التوزع، لا إلى تلخيص واحد فقط. يعتمد الانحراف المعياري على ما إذا كانت البيانات تمثل المجتمع كله أم عينة: انحراف المجتمع المعياري يقسم مجموع مربعات الانحرافات على N، أما انحراف العينة المعياري فيستخدم n − 1 لتقدير تباين المجتمع. اذكر النوع الذي أبلغت عنه. وقد تختلف طرق حساب الربيعات في العينات الصغيرة، لذا اذكر الطريقة عند أهمية قيمة المدى الربيعي بدقة. للقيم الخمس أدناه، وباستخدام وسيط نصفي البيانات، يكون الربيع الأول 3 والثالث 7 والمدى الربيعي 4.', 'Data come in two broad types. Categorical data place people in groups: sex, neighbourhood, case status. You summarise them with counts and percentages. Continuous data measure a quantity: age, onset delay in days, temperature. You summarise them with a centre and a spread. The mean is the sum divided by n. The median is the middle value when data are ordered — half below, half above. The mode is the most frequent value. The range is max minus min. The interquartile range (IQR) is the middle 50%: from the 25th to the 75th percentile. The standard deviation (SD) is the typical distance from the mean. When data are skewed by one very large value, the mean is pulled toward it and the median stays more typical. That is why you should always look at the distribution, not only one summary. The standard deviation depends on whether the data are the whole population or a sample: population SD divides the sum of squared deviations by N; sample SD uses n − 1 to estimate population variability. State which one you report. Quartile algorithms can differ for small samples, so state the convention used when an exact IQR matters. For the five values below, using the median-of-halves convention gives Q1 = 3, Q3 = 7 and IQR = 4.', '{"exampleEn": "Field case — Five onset delays are 2, 4, 4, 5 and 9 days. Mean = 4.8 days; median = 4 days. Using the stated median-of-halves convention, Q1 = 3, Q3 = 7 and IQR = 4 days (not 4–5). The single 9-day value pulls the mean above the median. Report the convention because quartile algorithms can differ for very small samples.", "exampleAr": "حالة ميدانية — تأخرات بدء الأعراض خمسة أيام: 2 و4 و4 و5 و9. المتوسط = 4.8 أيام؛ والوسيط = 4 أيام. وباستخدام طريقة وسيط نصفي البيانات المعلنة، الربيع الأول = 3 والثالث = 7 والمدى الربيعي = 4 أيام (وليس 4–5). تسحب القيمة المفردة 9 أيام المتوسط إلى أعلى من الوسيط. اذكر طريقة حساب الربيعات لأن الخوارزميات قد تختلف في العينات الصغيرة جدًا.", "fieldEn": "Always show the distribution — a small table or dot plot — before you trust a single mean. Reference note: the sample-versus-population SD divisor and quartile convention must be stated; see OpenStax Introductory Statistics, descriptive statistics.", "fieldAr": "أظهر التوزع دائما — جدولا صغيرا أو رسم نقاط — قبل أن تثق بمتوسط واحد. ملاحظة مرجعية: يجب تحديد مقام انحراف العينة أو المجتمع وطريقة حساب الربيعات؛ انظر OpenStax، الإحصاء الوصفي.", "calcTitleEn": "Worked calculation — dataset 2, 4, 4, 5, 9", "calcTitleAr": "حساب محلول — مجموعة البيانات 2، 4، 4، 5، 9", "calcStepsEn": ["Step 1 — Order: 2, 4, 4, 5, 9; n = 5.", "Step 2 — Mean = 24 ÷ 5 = 4.8; median = 4; mode = 4; range = 9 − 2 = 7.", "Step 3 — Using the median-of-halves quartile convention: Q1 = (2 + 4) ÷ 2 = 3; Q3 = (5 + 9) ÷ 2 = 7; IQR = 7 − 3 = 4.", "Step 4 — Sum of squared deviations from the mean = 26.8. Population SD = √(26.8 ÷ 5) ≈ 2.32; sample SD = √(26.8 ÷ 4) ≈ 2.59. Use the version matching the data and report purpose."], "calcStepsAr": ["الخطوة 1 — الترتيب: 2، 4، 4، 5، 9؛ ن = 5.", "الخطوة 2 — المتوسط = 24 ÷ 5 = 4.8؛ الوسيط = 4؛ المنوال = 4؛ المدى = 9 − 2 = 7.", "الخطوة 3 — باستخدام طريقة وسيط نصفي البيانات: الربيع الأول = (2 + 4) ÷ 2 = 3؛ والربيع الثالث = (5 + 9) ÷ 2 = 7؛ والمدى الربيعي = 7 − 3 = 4.", "الخطوة 4 — مجموع مربعات الانحرافات عن المتوسط = 26.8. انحراف المجتمع المعياري = √(26.8 ÷ 5) ≈ 2.32؛ وانحراف العينة المعياري = √(26.8 ÷ 4) ≈ 2.59. استخدم النوع الذي يناسب البيانات وغرض التقرير."], "calcResultEn": "Result: mean = 4.8, median = 4, mode = 4, range = 7. Report mean with SD, or median with IQR — and say which you chose and why.", "calcResultAr": "النتيجة: المتوسط = 4.8، والوسيط = 4، والمنوال = 4، والمدى = 7. أبلغ عن المتوسط مع الانحراف المعياري، أو الوسيط مع المدى الربيعي — وقل أيهما اخترت ولماذا.", "terms": [{"termEn": "Categorical data", "termAr": "البيانات الفئوية", "defEn": "Data that place people in groups, summarised by counts and percentages.", "defAr": "بيانات تضع الناس في مجموعات، تُلخّص بالأعداد والنسب المئوية."}, {"termEn": "Continuous data", "termAr": "البيانات المستمرة", "defEn": "Data that measure a quantity, summarised by centre and spread.", "defAr": "بيانات تقيس كمية، تُلخّص بمركز وانتشار."}, {"termEn": "Median / IQR", "termAr": "الوسيط / المدى الربيعي", "defEn": "Middle value; and the range of the middle 50% of values.", "defAr": "القيمة الوسطى؛ ومدى الوسط 50% من القيم."}, {"termEn": "Standard deviation (SD)", "termAr": "الانحراف المعياري", "defEn": "Typical distance of values from the mean.", "defAr": "المسافة النموذجية للقيم عن المتوسط."}], "deepSections": [{"titleEn": "From variable type to a defensible summary: a field decision pathway", "titleAr": "من نوع المتغير إلى ملخص يمكن الدفاع عنه: مسار لاتخاذ القرار الميداني", "bodyEn": "Start every analysis by defining the observational unit and the variable. A record may represent a person, visit, specimen, household, or person-time contribution; mixing these units creates invalid denominators. For each variable, record its operational definition, unit, allowable values, and missing-value codes before calculating anything. A nominal category such as district or test result is summarized with counts and a clearly stated denominator; an ordinal category such as severity grade may also be shown in ordered categories, but the distance between grades is not automatically equal. A quantitative variable such as age or delay can be summarized numerically, but inspect its distribution first. For a roughly symmetric distribution without influential outliers, mean and standard deviation describe centre and spread. For a skewed distribution or influential extreme values, median and interquartile range are usually more robust. A count variable may be discrete even when its values are numerous. Do not calculate an average of arbitrary category codes (for example, district 1, 2, 3): the arithmetic would have no meaningful interpretation. Before reporting, state the unit, n, missing observations, summary convention, and time window. This follows the OpenStax treatment of variable type, centre, spread, and graphical inspection: https://openstax.org/books/introductory-statistics-2e/pages/2-3-measures-of-the-location-of-the-data and https://openstax.org/books/introductory-statistics-2e/pages/2-7-measures-of-the-spread-of-the-data.", "bodyAr": "ابدأ كل تحليل بتحديد وحدة الملاحظة والمتغير. فقد يمثل السجل شخصًا أو زيارة أو عينة أو أسرة أو مساهمة من زمن الأشخاص؛ وخلط هذه الوحدات ينتج مقامات غير صحيحة. ولكل متغير، دوّن تعريفه الإجرائي ووحدته وقيمه المسموح بها ورموز القيم المفقودة قبل إجراء أي حساب. تُلخّص الفئة الاسمية مثل المديرية أو نتيجة الفحص بالأعداد مع مقام معلن بوضوح؛ ويمكن أيضًا عرض الفئة الرتبية مثل درجة الشدة بترتيبها، لكن المسافة بين الدرجات ليست متساوية تلقائيًا. ويمكن تلخيص المتغير الكمي مثل العمر أو التأخر عدديًا، لكن افحص توزيعه أولًا. إذا كان التوزيع متماثلًا تقريبًا ولا توجد قيم متطرفة مؤثرة، يصف المتوسط والانحراف المعياري المركز والانتشار. أما إذا كان التوزيع ملتويًا أو احتوى قيماً متطرفة مؤثرة، فعادة يكون الوسيط والمدى الربيعي أكثر مقاومة. وقد يكون متغير العد متقطعًا حتى لو تعددت قيمه. لا تحسب متوسطًا لرموز فئات اعتباطية (مثل المديرية 1 و2 و3)، لأن الناتج الحسابي لا يحمل تفسيرًا ذا معنى. وقبل الإبلاغ، اذكر وحدة الملاحظة والعدد n والمشاهدات المفقودة وطريقة التلخيص والفترة الزمنية. يتفق ذلك مع معالجة OpenStax لأنواع المتغيرات ومقاييس المركز والانتشار والفحص البياني: https://openstax.org/books/introductory-statistics-2e/pages/2-3-measures-of-the-location-of-the-data وhttps://openstax.org/books/introductory-statistics-2e/pages/2-7-measures-of-the-spread-of-the-data."}, {"titleEn": "Worked comparison: why the graph changes the interpretation", "titleAr": "مقارنة محلولة: لماذا يغيّر الرسم طريقة التفسير؟", "bodyEn": "Consider two explicitly illustrative groups of onset delays, measured in days: Group A = 2, 3, 4, 4, 5; Group B = 2, 3, 4, 5, 20. Both have n = 5. Group A has mean 3.6 and median 4; Group B has mean 6.8 and median 4. The same median does not mean the distributions are the same: the value 20 creates a long right tail and raises the mean. Under the median-of-halves convention, Group A has Q1 = 2.5, Q3 = 4.5, IQR = 2; Group B has Q1 = 2.5, Q3 = 12.5, IQR = 10. This convention is declared because software packages may use different percentile algorithms, particularly in very small samples. A dot plot or box plot should accompany the summary. The field question is not merely “which mean is larger?” but “is the extreme value valid, does it reflect a real delayed presentation, a data-entry error, or a different case definition?” Verify the source record; never delete an extreme value simply because it changes the result. If it is valid, retain it and explain its influence. These are constructed teaching values, not surveillance observations.", "bodyAr": "قارن مجموعتين توضيحيتين صُممتا للتعليم، لزمن بدء الأعراض بالأيام: المجموعة A = 2 و3 و4 و4 و5؛ والمجموعة B = 2 و3 و4 و5 و20. في كل مجموعة n = 5. متوسط A يساوي 3.6 ووسيطها 4؛ أما متوسط B فيساوي 6.8 ووسيطها 4. تساوي الوسيط لا يعني أن التوزيعين متماثلان؛ فالقيمة 20 تنشئ ذيلًا طويلًا إلى اليمين وترفع المتوسط. وباستخدام طريقة وسيط نصفي البيانات المعلنة، يكون الربيع الأول في A = 2.5 والثالث = 4.5 والمدى الربيعي = 2؛ وفي B الربيع الأول = 2.5 والثالث = 12.5 والمدى الربيعي = 10. نعلن هذه الطريقة لأن البرامج قد تستخدم خوارزميات مختلفة للمئينات، خاصة في العينات الصغيرة جدًا. ينبغي إرفاق رسم نقاط أو صندوق وشاربين بالملخص. والسؤال الميداني ليس فقط «أي المتوسطين أكبر؟» بل «هل القيمة المتطرفة صحيحة؟ وهل تعكس تأخرًا حقيقيًا في طلب الرعاية أم خطأ إدخال أم اختلافًا في تعريف الحالة؟». تحقّق من السجل الأصلي؛ ولا تحذف قيمة متطرفة لمجرد أنها تغيّر النتيجة. إذا كانت صحيحة، احتفظ بها واشرح أثرها. هذه قيم تعليمية مصطنعة وليست مشاهدات ترصدية."}, {"titleEn": "Practical reporting checklist and common analytical failures", "titleAr": "قائمة التحقق العملية للتقرير وأخطاء التحليل الشائعة", "bodyEn": "A defensible descriptive table should identify the population and period, define each variable, show the denominator for every percentage, distinguish zero from missing, and state whether values are person-level or event-level. Report the amount and pattern of missingness: if 12 of 100 records lack age, the age summary uses 88 known ages, not 100, unless a justified imputation method is used and disclosed. Do not code missing age as zero; zero years is a valid age. Do not use mean and SD automatically for heavily skewed delays. Do not compare medians as if they were means, and do not interpret an IQR as a confidence interval: IQR describes the middle half of observed values, while a confidence interval quantifies uncertainty in an estimated parameter under a model. A practical student task is to produce a one-page table and one graph, then write three sentences: what is observed, what cannot be inferred, and what data would resolve the uncertainty. Link the output to the F-106 dataset and its laboratory: verify units, calculate summaries using the declared quartile convention, inspect the graph, and justify the chosen summary. OpenStax recommends graphical inspection alongside numerical summaries, especially when distributions are skewed: https://openstax.org/books/introductory-statistics-2e/pages/2-8-descriptive-statistics.", "bodyAr": "يجب أن يحدد الجدول الوصفي القابل للدفاع عنه السكان والفترة، ويعرّف كل متغير، ويعرض مقام كل نسبة مئوية، ويميّز بين الصفر والقيمة المفقودة، ويوضح هل القيم على مستوى الشخص أم الحدث. أبلغ عن مقدار الفقد ونمطه: إذا افتقد 12 سجلًا من أصل 100 العمر، فإن ملخص العمر يعتمد على 88 عمرًا معلومًا لا 100، ما لم تُستخدم طريقة تعويض مبررة ويُفصح عنها. لا ترمز العمر المفقود بالصفر؛ فالعمر صفر قيمة صحيحة. ولا تستخدم المتوسط والانحراف المعياري تلقائيًا مع أزمنة شديدة الالتواء. ولا تقارن الوسيطين كما لو كانا متوسطين، ولا تفسر المدى الربيعي على أنه فترة ثقة: فالمدى الربيعي يصف نصف القيم الوسطى المشاهدة، بينما تقيس فترة الثقة عدم اليقين في معلمة مقدرة وفق نموذج. ومهمة الطالب العملية هي إعداد جدول من صفحة واحدة ورسم واحد، ثم كتابة ثلاث جمل: ما الذي لوحظ، وما الذي لا يمكن استنتاجه، وما البيانات التي تحسم عدم اليقين. اربط الناتج بمجموعة بيانات F-106 ومختبرها: تحقق من الوحدات، واحسب الملخصات وفق طريقة الربيعات المعلنة، وافحص الرسم، وبرر اختيار المقياس. توصي OpenStax بالفحص البياني إلى جانب الملخصات العددية، خاصة عندما تكون التوزيعات ملتوية: https://openstax.org/books/introductory-statistics-2e/pages/2-8-descriptive-statistics."}], "objEn": ["Distinguish categorical and continuous data.", "Calculate mean, median, mode, range, IQR and SD for a small dataset.", "Choose a summary that fits the shape of the data."], "objAr": ["التمييز بين البيانات الفئوية والمستمرة.", "حساب المتوسط والوسيط والمنوال والمدى والمدى الربيعي والانحراف المعياري لمجموعة صغيرة.", "اختيار تلخيص يناسب شكل البيانات."]}', '[{"qEn": "Mean of 2, 4, 4, 5, 9 is…", "qAr": "متوسط 2، 4، 4، 5، 9 هو…", "optsEn": ["4.8", "4", "7"], "optsAr": ["4.8", "4", "7"], "ans": 0, "explEn": "(2+4+4+5+9) = 24; 24 ÷ 5 = 4.8.", "explAr": "(2+4+4+5+9) = 24؛ 24 ÷ 5 = 4.8."}, {"qEn": "Median of 2, 4, 4, 5, 9 is…", "qAr": "وسيط 2، 4، 4، 5، 9 هو…", "optsEn": ["4.8", "4", "9"], "optsAr": ["4.8", "4", "9"], "ans": 1, "explEn": "Ordered, the middle value is 4.", "explAr": "مرتبة، القيمة الوسطى هي 4."}, {"qEn": "Categorical data are summarised by…", "qAr": "البيانات الفئوية تُلخّص بـ…", "optsEn": ["Mean and SD only", "Range only", "Counts and percentages"], "optsAr": ["المتوسط والانحراف المعياري فقط", "المدى فقط", "الأعداد والنسب المئوية"], "ans": 2, "explEn": "Categories are counted, not averaged as quantities.", "explAr": "الفئات تُعدّ، لا تُحسب ككميات."}, {"qEn": "When data are skewed, the median is often…", "qAr": "عندما تكون البيانات ملتوية، الوسيط غالبا…", "optsEn": ["More typical than the mean", "Always larger than the mean", "Equal to the range"], "optsAr": ["أكثر تمثيلا من المتوسط", "دائما أكبر من المتوسط", "مساو للمدى"], "ans": 0, "explEn": "The median resists one extreme value; the mean does not.", "explAr": "الوسيط يقاوم قيمة متطرفة واحدة؛ والمتوسط لا يقاوم."}, {"qEn": "For 2, 4, 4, 5, 9, using the median-of-halves convention, the IQR is…", "qAr": "للقيم 2، 4، 4، 5، 9، وباستخدام وسيط نصفي البيانات، المدى الربيعي هو…", "optsEn": ["7", "4", "2.59"], "optsAr": ["7", "4", "2.59"], "ans": 1, "explEn": "Q1 = 3 and Q3 = 7, so IQR = 7 − 3 = 4.", "explAr": "الربيع الأول 3 والثالث 7؛ لذلك المدى الربيعي = 7 − 3 = 4."}]' FROM courses WHERE course_code='B-102';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 2, 'فترات الثقة وفترة ويلسون', 'Confidence intervals and the Wilson interval', '[''شرح ما تعنيه فترة الثقة 95% وما لا تعنيه.'', ''شرح لماذا تُفضّل ويلسون للنسب.'', ''حساب وتفسير فترة ويلسون لـ 14/20.'']', '[''Explain what a 95% confidence interval does and does not mean.'', ''Explain why Wilson is preferred for proportions.'', ''Calculate and interpret a Wilson interval for 14/20.'']', 'التقدير النقطي تخمين واحد أفضل: 14 من 20 إيجابية هي 70%. وفترة الثقة تظهر عدم اليقين حوله: مدى قيم متوافق مع البيانات. وفترة الثقة 95% لا تعني أن هناك احتمال 95% أن الحقيقة داخل هذه الفترة الواحدة. بل تعني أنه لو تكررت نفس الدراسة مرات كثيرة، فحوالى 95% من الفترات ستحتوي الحقيقة. وللنسب، فترة والد البسيطة (p ± 1.96 × الخطأ المعياري) قد تفشل عندما تكون ن صغيرة أو p قريبة من 0 أو 1: فقد تذهب دون 0 أو فوق 1، أو تكون ضيقة جدا. وفترة ويلسون تبقى داخل 0–1 وتتصرف أفضل مع العينات الصغيرة. لذلك هذا المقرر وحاسباته يستخدمان ويلسون للنسب. أبلغ دائما عن التقدير والفترة ون — فـ 70% من 20 شخصا أقل يقينا بكثير من 70% من 2000. في هذا المثال، 14/20 هي نسبة الإيجابية بين العينات التي فُحصت؛ وليست تلقائيًا انتشار الحالة بين جميع الضيوف أو حساسية الاختبار. وتقدّر فترة ويلسون عدم اليقين الناتج عن المعاينة الثنائية في العينة المفحوصة، لكنها لا تصحح عينة متحيزة أو غير ممثلة.', 'A point estimate is a single best guess: 14 of 20 positive is 70%. A confidence interval (CI) shows the uncertainty around it: a range of values compatible with the data. A 95% CI does not mean there is a 95% chance the truth is inside this one interval. It means that if the same study were repeated many times, about 95% of the intervals would contain the truth. For proportions, the simple Wald interval (p ± 1.96 × standard error) can fail when n is small or p is near 0 or 1: it can go below 0 or above 1, or be far too narrow. The Wilson interval stays inside 0–1 and behaves better for small samples. That is why this course and its calculators use Wilson for proportions. Always report the estimate, the interval, and n — a 70% from 20 people is far less certain than 70% from 2,000. In this example, 14/20 is positivity among the specimens tested; it is not automatically prevalence in all guests or sensitivity of the test. The Wilson interval quantifies binomial sampling uncertainty for the tested sample, but it does not correct a biased or non-representative sample.', '{"exampleEn": "Field case — Of 20 specimens selected for testing, 14 are positive (70%; Wilson 95% CI approximately 48%–85%). This interval describes uncertainty in the tested sample proportion. If specimens were selected preferentially from severe or highly suspected cases, neither the 70% nor its interval estimates positivity among all guests.", "exampleAr": "حالة ميدانية — من 20 عينة اختيرت للفحص، كانت 14 إيجابية (70%؛ فترة ويلسون 95% نحو 48%–85%). تصف هذه الفترة عدم اليقين في نسبة العينة المفحوصة. وإذا اختيرت العينات تفضيليًا من الحالات الشديدة أو المشتبه بها بقوة، فلا تمثل نسبة 70% ولا فترتها تقديرًا للإيجابية بين جميع الضيوف.", "fieldEn": "Report estimate + interval + n. A wide interval is information, not failure — it tells you to collect more data.", "fieldAr": "أبلغ عن التقدير + الفترة + ن. الفترة الواسعة معلومة، لا فشل — تخبرك أن تجمع بيانات أكثر.", "calcTitleEn": "Worked calculation — Wilson 95% CI for 14/20", "calcTitleAr": "حساب محلول — فترة ويلسون 95% لـ 14/20", "calcStepsEn": ["Step 1 — Point estimate: p = 14 ÷ 20 = 0.70 = 70% positivity.", "Step 2 — Use the Wilson formula with z = 1.96 and n = 20 (the calculators do this arithmetic).", "Step 3 — Wilson centre is pulled slightly toward 50% because n is small.", "Step 4 — Wilson 95% CI ≈ 48% to 85%."], "calcStepsAr": ["الخطوة 1 — التقدير النقطي: p = 14 ÷ 20 = 0.70 = 70% إيجابية.", "الخطوة 2 — استخدم صيغة ويلسون مع z = 1.96 و n = 20 (الحاسبات تفعل هذا الحساب).", "الخطوة 3 — مركز ويلسون يُسحب قليلا نحو 50% لأن ن صغيرة.", "الخطوة 4 — فترة ويلسون 95% ≈ 48% إلى 85%."], "calcResultEn": "Result: 70% (95% Wilson CI 48%–85%). With only 20 people, the truth could plausibly be below half or above four-fifths. Do not report 70% without its interval and n = 20.", "calcResultAr": "النتيجة: 70% (فترة ويلسون 95% 48%–85%). ومع 20 شخصا فقط، قد تكون الحقيقة بمعقولية دون النصف أو فوق أربعة أخماس. لا تبلغ عن 70% من دون فترتها و n = 20.", "terms": [{"termEn": "Point estimate", "termAr": "التقدير النقطي", "defEn": "A single best guess from the data, e.g. 70%.", "defAr": "تخمين واحد أفضل من البيانات، مثلا 70%."}, {"termEn": "Confidence interval (CI)", "termAr": "فترة الثقة", "defEn": "A range of values compatible with the data at a stated confidence level.", "defAr": "مدى قيم متوافق مع البيانات عند مستوى ثقة محدد."}, {"termEn": "Wilson interval", "termAr": "فترة ويلسون", "defEn": "A CI for proportions that stays in 0–1 and works better for small samples.", "defAr": "فترة ثقة للنسب تبقى في 0–1 وتعمل أفضل مع العينات الصغيرة."}, {"termEn": "Standard error", "termAr": "الخطأ المعياري", "defEn": "The typical size of sampling variation in an estimate.", "defAr": "الحجم النموذجي للتباين بالعينة في تقدير."}], "deepSections": [{"titleEn": "What a 95% confidence interval means in repeated sampling", "titleAr": "ماذا تعني فترة الثقة 95% في المعاينة المتكررة؟", "bodyEn": "A confidence interval is produced by a procedure, not by assigning a probability to a fixed parameter after the data have been observed. In the frequentist interpretation, the population parameter is fixed and the interval varies from sample to sample. A procedure with 95% coverage will contain the true parameter in about 95% of repeated samples when its assumptions hold. For one completed interval, the parameter is either inside or outside; the 95% describes the long-run performance of the method. The interval width reflects precision and is affected by sample size, observed proportion, confidence level, and design effects. A larger sample often narrows the interval, but increasing n cannot repair selection bias, non-response bias, misclassification, or a poorly defined target population. For clustered or complex samples, a simple binomial interval may be too narrow because observations are not independent; use a method consistent with the sampling design. The CDC Field Epidemiology Manual explains that confidence intervals express uncertainty and precision but do not address validity or bias: https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html.", "bodyAr": "تنتج فترة الثقة عن إجراء إحصائي، ولا تعني إسناد احتمال إلى معلمة ثابتة بعد مشاهدة البيانات. في التفسير التكراري، تكون معلمة المجتمع ثابتة بينما تتغير الفترة من عينة إلى أخرى. والإجراء الذي يحقق تغطية 95% سيحتوي المعلمة الحقيقية في نحو 95% من العينات المتكررة إذا صحت افتراضاته. أما الفترة الواحدة بعد اكتمال الدراسة، فالمعلمة إما داخلها أو خارجها؛ والـ95% تصف الأداء طويل الأمد للطريقة. يعكس عرض الفترة الدقة، ويتأثر بحجم العينة والنسبة المشاهدة ومستوى الثقة وتأثيرات تصميم العينة. وغالبًا تضيق الفترة مع زيادة حجم العينة، لكن زيادة n لا تصلح تحيز الاختيار أو عدم الاستجابة أو سوء التصنيف أو سوء تعريف المجتمع المستهدف. وفي العينات العنقودية أو المعقدة قد تكون فترة ثنائية بسيطة أضيق من اللازم لأن المشاهدات ليست مستقلة؛ لذلك استخدم طريقة تتفق مع تصميم العينة. يوضح دليل CDC الميداني أن فترات الثقة تعبّر عن عدم اليقين والدقة لكنها لا تعالج الصلاحية أو التحيز: https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html."}, {"titleEn": "Wilson score interval: calculation and interpretation for 14 of 20", "titleAr": "فترة ويلسون: الحساب والتفسير لـ14 من 20", "bodyEn": "For x = 14 positive results among n = 20 tested specimens, p-hat = 14/20 = 0.70. For a two-sided 95% Wilson score interval, use z = 1.96. The adjusted centre is [p-hat + z²/(2n)]/[1 + z²/n], and the half-width is [z/(1 + z²/n)] × √[p-hat(1−p-hat)/n + z²/(4n²)]. Substitution gives a lower limit of approximately 0.481 and an upper limit of approximately 0.855: 48.1% to 85.5%. The interval is asymmetric around 70%, which is expected. Interpretation must preserve the sampling frame: this is positivity among the 20 specimens selected and tested. It is not population prevalence unless the sampling design supports that target, and it is not test sensitivity because sensitivity requires an appropriate reference standard and all truly diseased and non-diseased classifications. NIST describes the Wilson method as an established interval procedure for proportions: https://www.itl.nist.gov/div898/handbook/prc/section2/prc241.htm.", "bodyAr": "لـx = 14 نتيجة إيجابية من n = 20 عينة مفحوصة، تكون النسبة المقدرة p-hat = 14/20 = 0.70. ولحساب فترة ويلسون ثنائية الطرف عند 95% نستخدم z = 1.96. مركز الفترة المعدّل هو [p-hat + z²/(2n)]/[1 + z²/n]، ونصف العرض هو [z/(1 + z²/n)] × √[p-hat(1−p-hat)/n + z²/(4n²)]. بالتعويض نحصل على حد أدنى يقارب 0.481 وحد أعلى يقارب 0.855؛ أي 48.1% إلى 85.5%. الفترة غير متماثلة حول 70%، وهذا متوقع. يجب أن يحافظ التفسير على إطار المعاينة: هذه نسبة الإيجابية بين العينات العشرين التي اختيرت وفُحصت. ولا تمثل انتشارًا سكانيًا إلا إذا كان تصميم المعاينة يدعم ذلك الهدف، كما أنها ليست حساسية الاختبار؛ لأن الحساسية تتطلب معيارًا مرجعيًا مناسبًا وتصنيف جميع المصابين وغير المصابين الحقيقيين. يصف NIST طريقة ويلسون بأنها إجراء راسخ لفترات الثقة للنسب: https://www.itl.nist.gov/div898/handbook/prc/section2/prc241.htm."}, {"titleEn": "Sampling frame, uncertainty and the laboratory interpretation boundary", "titleAr": "إطار المعاينة وعدم اليقين وحدود تفسير المختبر", "bodyEn": "Before calculating an interval, ask who could have entered the sample, who was actually tested, and why. If clinicians selected only severe or highly suspected patients, the observed 70% positivity may be higher than positivity among all people in the community. Wilson quantifies binomial sampling uncertainty conditional on the observed sample; it does not model the selection mechanism. Also check whether repeated specimens from one person were counted as independent observations. If 20 specimens came from 15 people, the nominal n = 20 may overstate independent information. In the F-106 laboratory, the student should report numerator, denominator, selection rule, unit of analysis, interval method, and the target population in one sentence. A useful critical question is: “What population does this estimate actually describe?” If the answer is only “the tested specimens,” keep the conclusion at that level. Do not generalize to guests, residents, or all suspected cases without a sampling design or additional evidence that supports the move.", "bodyAr": "قبل حساب فترة الثقة، اسأل من كان يمكن أن يدخل العينة، ومن فُحص فعليًا، ولماذا. إذا اختار الأطباء المرضى الشديدين أو ذوي الاشتباه المرتفع فقط، فقد تكون إيجابية 70% أعلى من الإيجابية بين جميع أفراد المجتمع. تحسب ويلسون عدم اليقين الناتج عن المعاينة الثنائية بشرط العينة المشاهدة؛ لكنها لا تصمم نموذجًا لآلية الاختيار. وتحقق أيضًا مما إذا كانت عينات متكررة من الشخص نفسه قد عُدّت مشاهدات مستقلة. فإذا جاءت العينات العشرون من 15 شخصًا، فقد يبالغ n = 20 الاسمي في مقدار المعلومات المستقلة. وفي مختبر F-106، ينبغي أن يذكر الطالب البسط والمقام وقاعدة الاختيار ووحدة التحليل وطريقة الفترة والمجتمع المستهدف في جملة واحدة. والسؤال النقدي المفيد هو: «أي مجتمع تصفه هذه النسبة فعليًا؟». إذا كانت الإجابة «العينات المفحوصة فقط»، فأبقِ الاستنتاج عند هذا المستوى. ولا تعمم على الضيوف أو السكان أو جميع الحالات المشتبه بها دون تصميم معاينة أو أدلة إضافية تدعم ذلك."}], "objEn": ["Explain what a 95% confidence interval does and does not mean.", "Explain why Wilson is preferred for proportions.", "Calculate and interpret a Wilson interval for 14/20."], "objAr": ["شرح ما تعنيه فترة الثقة 95% وما لا تعنيه.", "شرح لماذا تُفضّل ويلسون للنسب.", "حساب وتفسير فترة ويلسون لـ 14/20."]}', '[{"qEn": "14/20 positivity is…", "qAr": "إيجابية 14/20 هي…", "optsEn": ["48%", "85%", "70%"], "optsAr": ["48%", "85%", "70%"], "ans": 2, "explEn": "14 ÷ 20 = 0.70 = 70%.", "explAr": "14 ÷ 20 = 0.70 = 70%."}, {"qEn": "The Wilson 95% CI for 14/20 is about…", "qAr": "فترة ويلسون 95% لـ 14/20 نحو…", "optsEn": ["48%–85%", "68%–72%", "0%–100%"], "optsAr": ["48%–85%", "68%–72%", "0%–100%"], "ans": 0, "explEn": "Wilson for 14/20 gives about 48% to 85%.", "explAr": "ويلسون لـ 14/20 تعطي نحو 48% إلى 85%."}, {"qEn": "A 95% CI means…", "qAr": "فترة الثقة 95% تعني…", "optsEn": ["95% chance this one interval contains the truth", "About 95% of repeated intervals would contain the truth", "95% of people are positive"], "optsAr": ["احتمال 95% أن هذه الفترة الواحدة تحتوي الحقيقة", "حوالى 95% من فترات متكررة ستحتوي الحقيقة", "95% من الناس إيجابيون"], "ans": 1, "explEn": "Confidence is about the method over repeats, not one interval.", "explAr": "الثقة تتعلق بالطريقة عبر التكرار، لا بفترة واحدة."}, {"qEn": "Wilson is preferred for proportions because…", "qAr": "ويلسون مفضلة للنسب لأنها…", "optsEn": ["Always gives a narrower interval", "Needs no sample size", "Stays in 0–1 and behaves better for small samples"], "optsAr": ["تعطي دائما فترة أضيق", "لا تحتاج حجم عينة", "تبقى في 0–1 وتتصرف أفضل مع العينات الصغيرة"], "ans": 2, "explEn": "Wilson avoids impossible values and handles small n better.", "explAr": "ويلسون تتجنب قيما مستحيلة وتتعامل مع ن الصغيرة أفضل."}]' FROM courses WHERE course_code='B-102';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 3, 'أساسيات اختبار الفرضيات', 'Hypothesis testing basics', '[''صياغة فرضية صفرية وبديلة بكلمات بسيطة.'', ''شرح ما تعنيه القيمة الاحتمالية وما لا تعنيه.'', ''التمييز بين خطأ النوع الأول وخطأ النوع الثاني والقوة، وشرح لماذا تُفضّل فترة الثقة.'']', '[''State a null and an alternative hypothesis in plain words.'', ''Explain what a p-value does and does not mean.'', ''Distinguish Type I error, Type II error and power, and explain why a CI is preferred.'']', 'اختبار الفرضيات يسأل: هل هذه النتيجة مفاجئة لو لم يكن هناك فرق حقا؟ الفرضية الصفرية تقول: لا فرق، لا ارتباط. والفرضية البديلة تقول: هناك فرق. والقيمة الاحتمالية هي احتمال رؤية بيانات بهذا التطرف على الأقل لو كانت الفرضية الصفرية صحيحة. وهي ليست احتمال أن الفرضية الصفرية صحيحة، وليست حجم الأثر. وقيمة احتمالية صغيرة تعني أن البيانات مفاجئة تحت الفرضية الصفرية؛ ولا تثبت البديلة، ولا تخبرك هل الفرق مهم. وخطأ النوع الأول هو رفض فرضية صفرية صحيحة — إنذار خاطئ، يضبطه مستوى الدلالة، غالبا 0.05. وخطأ النوع الثاني هو تفويت فرق حقيقي — عدم رفض فرضية صفرية خاطئة. والقوة هي 1 ناقص خطأ النوع الثاني: فرصة إيجاد فرق حقيقي عندما يوجد. وفترة الثقة مفضلة في هذا المقرر لأنها تظهر الحجم وعدم اليقين معا. والقيمة الاحتمالية وحدها تخفي كليهما. تعتمد القيمة الاحتمالية على النموذج الإحصائي وتصميم الدراسة وافتراضاته؛ ولا تقيّم غياب التحيز أو الإرباك أو خطأ القياس. أبلغ عن تقدير الأثر وفترة الثقة، وفسّرهما في ضوء الأهمية السريرية أو الصحية العامة. وعدم الدلالة الإحصائية ليس دليلًا على انعدام الأثر.', 'Hypothesis testing asks: is this result surprising if there were really no difference? The null hypothesis (H0) says: no difference, no association. The alternative (H1) says: there is a difference. The p-value is the probability of seeing data at least this extreme if H0 were true. It is not the probability that H0 is true, and it is not the size of the effect. A small p-value means the data are surprising under H0; it does not prove H1, and it does not tell you whether the difference matters. Type I error is rejecting a true H0 — a false alarm, controlled by the significance level, often 0.05. Type II error is missing a real difference — failing to reject a false H0. Power is 1 minus Type II error: the chance of finding a real difference when it exists. A confidence interval is preferred in this course because it shows the size and the uncertainty together. A p-value alone hides both. The p-value is conditional on the statistical model, study design and assumptions; it does not assess whether bias, confounding or measurement error are absent. Report the effect estimate and confidence interval, and interpret them against clinical or public-health importance. Statistical non-significance is not proof of no effect.', '{"exampleEn": "Field case — A small study finds RR 1.4 with p = 0.14. A headline says “no link.” The epidemiologist corrects it: p = 0.14 means the data are not surprising under H0, but the CI 0.9–2.1 is also compatible with a doubling of risk. The honest message is “uncertain, needs a larger study,” not “no link.” The team plans a larger sample to raise power before repeating the claim.", "exampleAr": "حالة ميدانية — دراسة صغيرة تجد خطرا نسبيا 1.4 مع p = 0.14. عنوان يقول «لا رابط». يصحح عالم الأوبئة: p = 0.14 تعني أن البيانات ليست مفاجئة تحت الفرضية الصفرية، لكن فترة 0.9–2.1 متوافقة أيضا مع تضاعف الخطر. والرسالة الصادقة هي «غير مؤكد، يحتاج دراسة أكبر»، لا «لا رابط». ويخطط الفريق لعينة أكبر لرفع القوة قبل تكرار الادعاء.", "fieldEn": "Never report a p-value without the estimate and its CI. Ask: how big, how uncertain, and does it matter?", "fieldAr": "لا تبلغ عن قيمة احتمالية أبدا من دون التقدير وفترته. واسأل: كم الحجم، وكم عدم اليقين، وهل يهم؟", "calcTitleEn": "Worked calculation — reading a CI instead of only a p-value", "calcTitleAr": "حساب محلول — قراءة فترة الثقة بدلا من القيمة الاحتمالية فقط", "calcStepsEn": ["Step 1 — H0: RR = 1 (no association). H1: RR ≠ 1.", "Step 2 — Result: RR = 1.4, 95% CI 0.9–2.1, p = 0.14.", "Step 3 — The CI includes 1, so the data are compatible with no association — and also with RR up to 2.1.", "Step 4 — p = 0.14 is above 0.05, so we do not reject H0. It does not prove H0 is true."], "calcStepsAr": ["الخطوة 1 — الفرضية الصفرية: الخطر النسبي = 1 (لا ارتباط). والبديلة: الخطر النسبي ≠ 1.", "الخطوة 2 — النتيجة: الخطر النسبي = 1.4، وفترة الثقة 95% 0.9–2.1، و p = 0.14.", "الخطوة 3 — الفترة تتضمن 1، لذا البيانات متوافقة مع لا ارتباط — وأيضا مع خطر نسبي حتى 2.1.", "الخطوة 4 — p = 0.14 فوق 0.05، لذا لا نرفض الفرضية الصفرية. وهذا لا يثبت أن الفرضية الصفرية صحيحة."], "calcResultEn": "Result: do not claim “no effect.” Claim: the estimate is 1.4, the interval is wide (0.9–2.1), and more data are needed. The CI says what the p-value hides.", "calcResultAr": "النتيجة: لا تدّع «لا أثر». ادّع: التقدير 1.4، والفترة واسعة (0.9–2.1)، ونحتاج بيانات أكثر. الفترة تقول ما تخفيه القيمة الاحتمالية.", "terms": [{"termEn": "Null hypothesis (H0)", "termAr": "الفرضية الصفرية", "defEn": "No difference, no association — the starting assumption to test.", "defAr": "لا فرق، لا ارتباط — الافتراض الأولي للاختبار."}, {"termEn": "p-value", "termAr": "القيمة الاحتمالية", "defEn": "Probability of data at least this extreme if H0 were true.", "defAr": "احتمال بيانات بهذا التطرف على الأقل لو كانت الفرضية الصفرية صحيحة."}, {"termEn": "Type I / Type II error", "termAr": "خطأ النوع الأول / الثاني", "defEn": "False alarm (rejecting a true H0) / missed difference (keeping a false H0).", "defAr": "إنذار خاطئ (رفض فرضية صفرية صحيحة) / فرق مفتقد (إبقاء فرضية صفرية خاطئة)."}, {"termEn": "Power", "termAr": "القوة", "defEn": "Chance of finding a real difference when it exists.", "defAr": "فرصة إيجاد فرق حقيقي عندما يوجد."}], "deepSections": [{"titleEn": "Null hypotheses, error types and power: what the test can and cannot decide", "titleAr": "الفرضية الصفرية وأنواع الخطأ والقوة: ما الذي يستطيع الاختبار حسمه وما لا يستطيع؟", "bodyEn": "A hypothesis test begins with a clearly specified estimand, study design, null hypothesis H0, alternative hypothesis H1, and analysis plan. A Type I error occurs when a true H0 is rejected; its long-run probability is controlled by the preselected alpha under the model assumptions. A Type II error occurs when a false H0 is not rejected; beta is the probability of that error for a specified alternative, and power is 1−beta. For example, if a study has 80% power for a defined effect size and alpha, beta is 20% for that effect under the assumed design. This does not mean there is an 80% probability that the study will be correct. Power depends on effect size, sample size, outcome variability or event frequency, alpha, allocation, and analysis method. A non-significant result can arise because there is little or no effect, because the study is imprecise, or because assumptions are violated. Never translate “p greater than 0.05” into “no effect.” The ASA statement emphasizes that p-values do not measure the probability that a hypothesis is true or the size/importance of an effect: https://www.amstat.org/asa/files/pdfs/P-ValueStatement.pdf.", "bodyAr": "يبدأ اختبار الفرضية بتحديد واضح للمعلمة المستهدفة وتصميم الدراسة والفرضية الصفرية H0 والبديلة H1 وخطة التحليل. يحدث خطأ النوع الأول عندما نرفض H0 وهي صحيحة؛ ويُضبط احتماله طويل الأمد بمستوى ألفا المحدد مسبقًا، في ظل افتراضات النموذج. ويحدث خطأ النوع الثاني عندما لا نرفض H0 وهي خاطئة؛ وبيتا هو احتمال ذلك الخطأ لبديل محدد، والقوة الإحصائية تساوي 1−بيتا. فمثلًا، إذا كانت قوة الدراسة 80% لحجم أثر محدد ومستوى ألفا معين، فإن بيتا تساوي 20% لذلك الأثر وفق التصميم المفترض. ولا يعني ذلك أن احتمال صحة الدراسة 80%. وتعتمد القوة على حجم الأثر وحجم العينة وتباين النتيجة أو تواتر الحدث وألفا والتوزيع وطريقة التحليل. وقد تنتج النتيجة غير الدالة إحصائيًا عن غياب الأثر أو صغره، أو عن عدم دقة الدراسة، أو عن انتهاك الافتراضات. لا تحوّل أبدًا عبارة «p أكبر من 0.05» إلى «لا يوجد أثر». ويؤكد بيان الجمعية الأمريكية للإحصاء أن القيمة الاحتمالية لا تقيس احتمال صحة الفرضية ولا حجم الأثر أو أهميته: https://www.amstat.org/asa/files/pdfs/P-ValueStatement.pdf."}, {"titleEn": "Worked interpretation: RR 1.4, 95% CI 0.9–2.1, p = 0.14", "titleAr": "تفسير محلول: RR يساوي 1.4 وفترة 95% من 0.9 إلى 2.1 وp تساوي 0.14", "bodyEn": "Suppose an illustrative analytic study reports RR = 1.4, 95% CI 0.9–2.1, and p = 0.14. The point estimate suggests 40% higher risk in the exposed group, but the interval includes the null value 1 and is compatible with a small reduction as well as a doubling of risk. The p-value indicates that, if the null model and assumptions were true, data at least this incompatible with H0 would not be especially rare at conventional thresholds. It does not prove equal risks. A careful conclusion is: “The estimate was elevated, but uncertainty was substantial and the data were compatible with no association as well as a potentially important increase; further evidence is needed.” Next examine absolute risks, confidence interval method, confounding, selection, measurement error, and whether the study was adequately powered for a meaningful effect. The CDC Field Epidemiology Manual notes that confidence intervals describe precision, while neither a CI nor a test alone addresses validity or bias: https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html. The numbers here are a constructed teaching example, not a real study result.", "bodyAr": "افترض أن دراسة تحليلية توضيحية أبلغت عن RR = 1.4 وفترة ثقة 95% من 0.9 إلى 2.1 وقيمة p = 0.14. يشير التقدير النقطي إلى خطر أعلى بنسبة 40% لدى المجموعة المعرضة، لكن الفترة تشمل القيمة الصفرية للارتباط 1، وتتوافق مع انخفاض بسيط كما تتوافق مع تضاعف الخطر. وتشير القيمة الاحتمالية إلى أنه إذا كان نموذج العدم وافتراضاته صحيحين، فلن تكون بيانات لا تقل تعارضًا مع H0 نادرة على نحو خاص عند الحدود التقليدية. لكنها لا تثبت تساوي المخاطر. والاستنتاج الحذر هو: «كان التقدير مرتفعًا، لكن عدم اليقين كان كبيرًا، وكانت البيانات متوافقة مع عدم وجود ارتباط كما كانت متوافقة مع زيادة قد تكون مهمة؛ لذلك نحتاج إلى أدلة إضافية». بعد ذلك افحص المخاطر المطلقة وطريقة فترة الثقة والإرباك والاختيار وخطأ القياس، وهل كانت قوة الدراسة كافية لاكتشاف أثر ذي أهمية. ويشير دليل CDC الميداني إلى أن فترات الثقة تصف الدقة، بينما لا تعالج الفترة أو الاختبار وحدهما الصلاحية أو التحيز: https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html. والأرقام هنا مثال تعليمي مصطنع وليست نتيجة دراسة حقيقية."}, {"titleEn": "A transparent analysis and reporting plan for a field epidemiologist", "titleAr": "خطة تحليل وإبلاغ شفافة لعالم الوبائيات الميداني", "bodyEn": "Before inspecting outcomes, write down the primary outcome, exposure, target population, unit of analysis, inclusion criteria, handling of missing data, effect measure, confidence level, and planned subgroup analyses. This reduces selective reporting and post hoc threshold hunting. Distinguish exploratory analyses, which generate hypotheses, from confirmatory analyses, which test prespecified questions. Report the estimate and interval even when the p-value is not below 0.05; state the direction, magnitude, precision, and public-health relevance. A statistically detectable difference can be too small to matter operationally, while an imprecise estimate may still warrant precautionary action if the potential harm is severe and the decision is reversible. Explain assumptions and limitations, including non-independence, multiple comparisons, model fit, and missingness. In the F-106 lesson check and laboratory, students should submit a short interpretation that avoids binary “significant/not significant” language and identifies what additional data would change the decision. This is the bridge from a calculation to responsible public-health inference.", "bodyAr": "قبل فحص النتائج، دوّن النتيجة الأساسية والتعرض والمجتمع المستهدف ووحدة التحليل ومعايير الإدراج وطريقة التعامل مع البيانات المفقودة ومقياس الأثر ومستوى الثقة وتحليلات المجموعات الفرعية المخططة. يقلل ذلك من الإبلاغ الانتقائي والبحث اللاحق عن حد دلالة مناسب. ميّز التحليلات الاستكشافية التي تولّد الفرضيات عن التحليلات التأكيدية التي تختبر أسئلة محددة مسبقًا. أبلغ عن التقدير وفترته حتى عندما لا تقل القيمة الاحتمالية عن 0.05؛ واذكر الاتجاه والحجم والدقة والأهمية للصحة العامة. فقد يكون الفرق القابل للكشف إحصائيًا صغيرًا جدًا بحيث لا يؤثر عمليًا، بينما قد يستدعي التقدير غير الدقيق إجراءً احترازيًا إذا كان الضرر المحتمل شديدًا وكان القرار قابلًا للمراجعة. اشرح الافتراضات والقيود، بما فيها عدم الاستقلال وتعدد المقارنات وملاءمة النموذج والبيانات المفقودة. وفي اختبار ومختبر F-106، ينبغي للطلاب تقديم تفسير موجز يتجنب اللغة الثنائية «دال/غير دال» ويحدد البيانات الإضافية التي قد تغير القرار. هذه هي الصلة بين الحساب والاستدلال المسؤول في الصحة العامة."}], "objEn": ["State a null and an alternative hypothesis in plain words.", "Explain what a p-value does and does not mean.", "Distinguish Type I error, Type II error and power, and explain why a CI is preferred."], "objAr": ["صياغة فرضية صفرية وبديلة بكلمات بسيطة.", "شرح ما تعنيه القيمة الاحتمالية وما لا تعنيه.", "التمييز بين خطأ النوع الأول وخطأ النوع الثاني والقوة، وشرح لماذا تُفضّل فترة الثقة."]}', '[{"qEn": "The null hypothesis says…", "qAr": "الفرضية الصفرية تقول…", "optsEn": ["No difference, no association", "There is a large effect", "The study was biased"], "optsAr": ["لا فرق، لا ارتباط", "هناك أثر كبير", "الدراسة متحيزة"], "ans": 0, "explEn": "H0 is the no-difference starting assumption.", "explAr": "الفرضية الصفرية هي افتراض لا فرق الأولي."}, {"qEn": "A p-value is…", "qAr": "القيمة الاحتمالية هي…", "optsEn": ["Probability that H0 is true", "Probability of data this extreme if H0 were true", "The size of the effect"], "optsAr": ["احتمال أن الفرضية الصفرية صحيحة", "احتمال بيانات بهذا التطرف لو كانت الفرضية الصفرية صحيحة", "حجم الأثر"], "ans": 1, "explEn": "p is about the data under H0, not about H0 itself.", "explAr": "p تتعلق بالبيانات تحت الفرضية الصفرية، لا بالفرضية نفسها."}, {"qEn": "Type I error is…", "qAr": "خطأ النوع الأول هو…", "optsEn": ["Missing a real difference", "A wide confidence interval", "Rejecting a true H0 (false alarm)"], "optsAr": ["تفويت فرق حقيقي", "فترة ثقة واسعة", "رفض فرضية صفرية صحيحة (إنذار خاطئ)"], "ans": 2, "explEn": "Type I = false alarm; Type II = missed difference.", "explAr": "النوع الأول = إنذار خاطئ؛ والنوع الثاني = فرق مفتقد."}, {"qEn": "Why is a CI preferred to a p-value alone?", "qAr": "لماذا تُفضّل فترة الثقة على القيمة الاحتمالية وحدها؟", "optsEn": ["It shows size and uncertainty together", "It always proves H1", "It needs no sample size"], "optsAr": ["تظهر الحجم وعدم اليقين معا", "تثبت البديلة دائما", "لا تحتاج حجم عينة"], "ans": 0, "explEn": "The CI shows the estimate and its uncertainty; p hides both.", "explAr": "الفترة تظهر التقدير وعدم يقينه؛ وp تخفي كليهما."}]' FROM courses WHERE course_code='B-102';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 1, 'غرض ووظائف الترصد', 'Purpose and functions of surveillance', '[''تسمية الوظائف الخمس: الكشف والمراقبة والتنبيه والتقييم وتوجيه الإجراء.'', ''تتبع السلسلة: الجمع ← الإبلاغ ← التحليل ← التغذية الراجعة ← الإجراء.'', ''شرح لماذا يفشل الترصد بلا تغذية راجعة.'']', '[''Name the five functions: detect, monitor, alert, evaluate, guide action.'', ''Trace the chain: collection → reporting → analysis → feedback → action.'', ''Explain why surveillance without feedback fails.'']', 'الترصد ليس عدّا لذاته. غرضه أن يكشف الارتفاع مبكرا، ويراقب الاتجاهات، وينبّه صناع القرار، ويقيّم هل السيطرة تعمل، ويوجه الإجراء. والسلسلة لها خمس حلقات. الجمع: العيادات والمختبرات والمجتمعات تبلغ عن الحالات بالشخص والمكان والزمان. الإبلاغ: التقارير تنتقل في النظام في الوقت ومكتملة. التحليل: الفريق يحوّل التقارير إلى جداول ومنحنيات ومعدلات، ويقارن هذا الأسبوع بالأسابيع السابقة. التغذية الراجعة: الفريق يعيد التحليل إلى من أبلغوا — مع الشكر والتصحيحات والأسئلة. الإجراء: صناع القرار يستخدمون التحليل للفحص أو العلاج أو التحذير أو التطعيم. إذا انكسرت أي حلقة، تفشل السلسلة. وإذا توقفت التغذية الراجعة، يتوقف المبلغون عن الإبلاغ، لأنهم لا يرون أبدا ما غيّرته بياناتهم. الترصد الجيد يُحكم عليه بالإجراء الذي ينتجه، لا بكومة التقارير التي يجمعها. عتبة مثل «ضعف خط الأساس» قاعدة محلية توضيحية وليست حدًا وبائيًا عالميًا. قبل تفسير الارتفاع، تحقق من ثبات تعريف الحالة ومقام السكان واكتمال الإبلاغ وشدة الفحص والنمط الموسمي مقارنة بخط الأساس. والأفضل استخدام عتبة محلية محددة ومراجعة دوريًا بما يناسب المرض وهدف الترصد.', 'Surveillance is not counting for its own sake. Its purpose is to detect a rise early, monitor trends, alert decision-makers, evaluate whether control is working, and guide action. The chain has five links. Collection: clinics, laboratories and communities report cases with person, place and time. Reporting: reports move up the system on time and complete. Analysis: the team turns reports into tables, curves and rates, and compares this week with previous weeks. Feedback: the team returns the analysis to the people who reported — with thanks, corrections and questions. Action: decision-makers use the analysis to inspect, treat, warn or vaccinate. If any link breaks, the chain fails. If feedback stops, reporters stop reporting, because they never see what their data changed. Good surveillance is judged by the action it produces, not by the pile of reports it collects. A threshold such as “double the baseline” is an illustrative local rule, not a universal epidemiologic cut-off. Before interpreting a rise, check that the case definition, population denominator, reporting completeness, testing intensity and seasonal pattern are comparable with the baseline. Prefer a locally defined and periodically reviewed threshold appropriate to the disease and surveillance objective.', '{"exampleEn": "Field case — A district''s weekly bulletin shows 24 cases, up from a baseline of 10. The team sends feedback the same day: a one-page bulletin to every clinic, naming the rise, the most affected neighbourhood, and the next step — active case finding there. Reporting rises the next week, because clinics see that their reports produced a visit and a bulletin, not silence.", "exampleAr": "حالة ميدانية — نشرة أسبوعية لمنطقة تظهر 24 حالة، ارتفاعا من خط أساس 10. يرسل الفريق تغذية راجعة في نفس اليوم: نشرة صفحة واحدة لكل عيادة، تسمي الارتفاع والحي الأكثر تأثرا والخطوة التالية — البحث النشط عن الحالات هناك. ويرتفع الإبلاغ الأسبوع التالي، لأن العيادات ترى أن تقاريرها أنتجت زيارة ونشرة، لا صمتا.", "fieldEn": "End every surveillance week with feedback and one action. If there is no action, say so — and fix the chain. Reference basis: CDC field epidemiology guidance on interpreting surveillance trends; thresholds must be adapted to disease, seasonality and system objectives.", "fieldAr": "أنهِ كل أسبوع ترصد بتغذية راجعة وإجراء واحد. وإذا لم يكن هناك إجراء، قل ذلك — وأصلح السلسلة. مرجع المراجعة: إرشادات CDC الميدانية لتفسير اتجاهات الترصد؛ ويجب تكييف العتبات مع المرض والموسمية وأهداف النظام.", "calcTitleEn": "Worked calculation — from reports to action", "calcTitleAr": "حساب محلول — من التقارير إلى الإجراء", "calcStepsEn": ["Step 1 — Illustrative baseline: 10 cases per week, averaged over the previous 4 weeks.", "Step 2 — Current week: 24 cases; this is 24 ÷ 10 = 2.4 times baseline, or a 140% increase over baseline.", "Step 3 — For this exercise only, the locally pre-agreed alert rule is ≥2 times baseline; 24 exceeds the threshold of 20.", "Step 4 — Investigate promptly, but first check reporting completeness, case definition, testing and seasonality. The threshold is not universal and does not itself prove an outbreak."], "calcStepsAr": ["الخطوة 1 — خط أساس توضيحي: 10 حالات أسبوعيًا، وهو متوسط الأسابيع الأربعة السابقة.", "الخطوة 2 — الأسبوع الحالي: 24 حالة؛ أي 24 ÷ 10 = 2.4 مرة خط الأساس، أو زيادة قدرها 140% عن خط الأساس.", "الخطوة 3 — في هذا التمرين فقط، قاعدة الإنذار المحلية المتفق عليها مسبقًا هي ≥ ضعفي خط الأساس؛ وتتجاوز 24 عتبة 20.", "الخطوة 4 — ابدأ التحقيق سريعًا، لكن تحقق أولًا من اكتمال الإبلاغ وتعريف الحالة والفحص والموسمية. العتبة ليست عالمية ولا تثبت الفاشية بذاتها."], "calcResultEn": "Result: 24 cases are 2.4 times the illustrative baseline (140% higher). The exercise’s locally pre-agreed threshold is crossed; the team should verify data comparability and investigate. A doubled-baseline rule is not a universal threshold.", "calcResultAr": "النتيجة: 24 حالة تساوي 2.4 مرة خط الأساس التوضيحي (أعلى بنسبة 140%). تم تجاوز العتبة المحلية المتفق عليها في التمرين؛ وعلى الفريق التحقق من قابلية مقارنة البيانات والتحقيق. قاعدة ضعف خط الأساس ليست عتبة عالمية.", "terms": [{"termEn": "Detect", "termAr": "الكشف", "defEn": "Notice a rise or a new pattern early.", "defAr": "ملاحظة ارتفاع أو نمط جديد مبكرا."}, {"termEn": "Monitor", "termAr": "المراقبة", "defEn": "Follow trends over time to see whether control is working.", "defAr": "متابعة الاتجاهات عبر الزمن لمعرفة هل السيطرة تعمل."}, {"termEn": "Feedback", "termAr": "التغذية الراجعة", "defEn": "Returning analysis to reporters so reporting stays alive.", "defAr": "إعادة التحليل إلى المبلغين حتى يبقى الإبلاغ حيا."}, {"termEn": "Action", "termAr": "الإجراء", "defEn": "The decision the surveillance data supports.", "defAr": "القرار الذي تدعمه بيانات الترصد."}], "deepSections": [{"titleEn": "Surveillance is a decision system, not a reporting warehouse", "titleAr": "الترصد نظام لاتخاذ القرار وليس مستودعاً للتقارير", "bodyEn": "Public-health surveillance is the continuous, systematic collection, analysis, interpretation and dissemination of health-related data for action. The word continuous describes an ongoing function, not necessarily daily reporting for every condition; frequency must match the disease, hazard, incubation period and decision need. Begin system design with a decision question: what event must be detected, by whom, how quickly, and what action follows? A notifiable rare disease may require immediate single-case notification, whereas a common endemic condition may be monitored through weekly counts or rates. Indicator-based surveillance uses structured reports and predefined variables; event-based surveillance captures unstructured signals such as a clinician''s unusual cluster, community reports, hotline calls or media information. Sentinel surveillance uses selected sites to monitor trends and may not estimate population incidence. Active surveillance seeks information directly and can improve ascertainment during a response, but it requires more resources. Passive surveillance is more sustainable but depends on routine reporting behaviour. These approaches are complementary; no single design is best for every objective. Specify the target population, case definition, reporting unit, reporting interval, data flow, analysis plan, feedback recipient and action threshold before collecting a large dataset. WHO describes surveillance as an early-warning function and as a means to monitor interventions and guide priorities. Reference: WHO, Surveillance in emergencies — https://www.who.int/emergencies/surveillance; WHO EWAR operational guide (2023) — https://www.who.int/publications/i/item/9789240063587.", "bodyAr": "الترصد الصحي العمومي هو الجمع والتحليل والتفسير والنشر المستمر والمنهجي للبيانات الصحية بغرض اتخاذ إجراء. وتعني كلمة «مستمر» وظيفة متواصلة، ولا تعني بالضرورة الإبلاغ اليومي عن كل حالة؛ إذ يجب أن يتناسب التواتر مع المرض أو الخطر وفترة الحضانة والحاجة إلى القرار. ابدأ تصميم النظام بسؤال قرار: ما الحدث المطلوب كشفه؟ ومن المسؤول؟ وخلال أي مدة؟ وما الإجراء الذي سيترتب عليه؟ قد يتطلب مرض نادر واجب الإبلاغ إخطاراً فورياً عن حالة واحدة، بينما قد تُراقب حالة متوطنة شائعة بأعداد أو معدلات أسبوعية. يستخدم الترصد القائم على المؤشرات تقارير منظمة ومتغيرات محددة مسبقاً؛ أما الترصد القائم على الأحداث فيلتقط إشارات غير منظمة مثل تجمع غير معتاد يلاحظه طبيب، أو بلاغ مجتمعي، أو اتصال بخط ساخن، أو معلومة إعلامية. ويستخدم الترصد بالمواقع الحارسة مواقع مختارة لمراقبة الاتجاهات، وقد لا يقدّر حدوث المرض في المجتمع كله. ويسعى الترصد النشط إلى الحصول على المعلومات مباشرة وقد يحسن اكتشاف الحالات أثناء الاستجابة، لكنه يحتاج موارد أكبر. أما الترصد السلبي فأكثر قابلية للاستمرار لكنه يعتمد على سلوك الإبلاغ الروتيني. هذه الأساليب متكاملة ولا يوجد تصميم واحد أفضل لكل الأهداف. حدد المجتمع المستهدف وتعريف الحالة ووحدة الإبلاغ والفترة الزمنية وتدفق البيانات وخطة التحليل ومستلم التغذية الراجعة وعتبة الإجراء قبل جمع قاعدة بيانات كبيرة. تصف منظمة الصحة العالمية الترصد بأنه وظيفة للإنذار المبكر ووسيلة لمراقبة التدخلات وتوجيه الأولويات. المرجع: WHO، الترصد في الطوارئ — https://www.who.int/emergencies/surveillance؛ والدليل التشغيلي EWAR لعام 2023 — https://www.who.int/publications/i/item/9789240063587."}, {"titleEn": "Design the minimum dataset and the reporting-to-action loop", "titleAr": "صمّم الحد الأدنى من البيانات وحلقة الإبلاغ إلى الإجراء", "bodyEn": "A surveillance form should collect information that supports a defined decision, not every variable that might someday be interesting. At minimum, a case-based record commonly needs a unique record identifier, reporting facility or source, dates (onset, consultation, specimen and report as relevant), age or age group, sex where relevant, residence/location, key clinical criteria, laboratory status, outcome and classification. The exact dataset must follow the disease-specific national protocol and privacy rules. Define each field in a data dictionary: name, operational definition, format, allowed values, source, mandatory status and missing-value code. Distinguish a person from a visit, specimen or report; otherwise duplicate encounters may be counted as separate people. Assign a unique identifier and a documented deduplication rule. Map the flow: community or facility → district → governorate → national level, with named responsibility and deadlines at each transfer. Specify how urgent alerts bypass routine aggregation. Feedback must travel back to the reporting level and community in a useful format: what was detected, what was verified, what action was taken, and what data-quality correction is needed. Protect confidentiality through role-based access, secure transfer, minimum necessary identifiers and aggregate public reporting. A data system that collects more than it can validate or use can increase burden and reduce reporting quality. The existing F-107 laboratory directly operationalizes this loop: learners trace Week 3 through collection → reporting → analysis → feedback → action, calculate the active-only share (12/30 = 40%), calculate monthly alert PPV (48/60 = 80%), and propose one owned, dated correction. A small data-dictionary review can be an instructor-led extension, but it must not be misrepresented as an existing scored lab requirement. Reference: WHO EWAR operational guide — https://www.who.int/publications/i/item/9789240063587; CDC Field Epidemiology Manual, Data collection — https://www.cdc.gov/field-epi-manual/php/chapters/collecting-data.html.", "bodyAr": "ينبغي أن يجمع نموذج الترصد المعلومات التي تدعم قراراً محدداً، لا كل متغير قد يبدو مثيراً للاهتمام مستقبلاً. ويحتاج سجل الحالة عادةً، كحد أدنى، إلى معرف فريد للسجل، ومرفق أو مصدر الإبلاغ، والتواريخ اللازمة (بدء الأعراض والمراجعة وأخذ العينة والإبلاغ)، والعمر أو فئته، والجنس عند صلته، ومكان الإقامة، والمعايير السريرية الأساسية، وحالة الفحص المخبري، والنتيجة والتصنيف. ويجب أن تتبع مجموعة البيانات الدقيقة البروتوكول الوطني الخاص بالمرض وقواعد الخصوصية. عرّف كل حقل في قاموس بيانات: الاسم والتعريف الإجرائي والصيغة والقيم المسموح بها والمصدر وكونه إلزامياً ورمز القيمة المفقودة. ميّز الشخص عن الزيارة أو العينة أو التقرير؛ وإلا فقد تُحسب الزيارات المتكررة كأشخاص مختلفين. خصص معرفاً فريداً وقاعدة موثقة لإزالة التكرار. ارسم تدفق البيانات: المجتمع أو المرفق ← المديرية ← المحافظة ← المستوى الوطني، مع تحديد المسؤول والمهلة عند كل انتقال. وضّح كيف تتجاوز التنبيهات العاجلة التجميع الروتيني. ويجب أن تعود التغذية الراجعة إلى مستوى الإبلاغ والمجتمع بصيغة مفيدة: ما الذي كُشف؟ وما الذي تم التحقق منه؟ وما الإجراء المتخذ؟ وما تصحيح جودة البيانات المطلوب؟ احمِ السرية بصلاحيات وصول حسب الدور ونقل آمن وأقل قدر لازم من المعرفات وتقارير عامة مجمعة. وقد يزيد النظام الذي يجمع بيانات أكثر مما يستطيع التحقق منها أو استخدامها العبء ويخفض جودة الإبلاغ. يطبّق مختبر F-107 الموجود هذه الحلقة مباشرة: يتتبع الطالب الأسبوع الثالث عبر الجمع ← الإبلاغ ← التحليل ← التغذية الراجعة ← الإجراء، ويحسب حصة الحالات المكتشفة نشطاً فقط (12/30 = 40%)، والقيمة التنبؤية الإيجابية الشهرية للتنبيهات (48/60 = 80%)، ثم يقترح تصحيحاً واحداً له مسؤول وموعد. ويمكن أن تكون مراجعة قاموس بيانات صغير امتداداً تعليمياً بإشراف المدرس، لكن لا يجوز تقديمها على أنها متطلب مقوّم موجود في المختبر. المراجع: WHO EWAR — https://www.who.int/publications/i/item/9789240063587؛ ودليل CDC الميداني، جمع البيانات — https://www.cdc.gov/field-epi-manual/php/chapters/collecting-data.html."}, {"titleEn": "Worked system-design example: define what an alert means", "titleAr": "مثال محلول لتصميم النظام: حدّد معنى التنبيه", "bodyEn": "Assume a fictional district has 10 expected reporting facilities each week. In the previous four weeks, all 10 reported and the mean count was 10 cases per week. This week, 8 facilities submitted reports and the total reported count was 18. The raw count is 1.8 times the earlier mean, but reporting completeness has fallen from 10/10 = 100% to 8/10 = 80%. Do not mechanically divide 18 by 0.80 and call the result the true count: the two non-reporting facilities may serve populations with different risk, and missingness may not be random. The correct operational conclusion is that the signal warrants rapid verification while data completeness is investigated. Contact the two non-reporting facilities; confirm whether zero cases or no report was submitted; check whether the case definition and reporting period are unchanged; inspect onset dates, laboratory confirmation and possible duplicates; and compare with a suitable seasonal baseline. If a disease-specific protocol requires immediate notification of one suspected case, that rule overrides a general count threshold. Document the signal, verification steps, evidence, decision, person responsible and next review time. These numbers are constructed for teaching and are not observations from a real district. In the F-107 practical, learners should calculate completeness, state what the raw ratio can and cannot establish, and draft a verification request. Reference: WHO EWAR — https://www.who.int/publications/i/item/9789240063587.", "bodyAr": "افترض أن مديرية افتراضية لديها 10 مرافق متوقعاً منها الإبلاغ أسبوعياً. وفي الأسابيع الأربعة السابقة أبلغت المرافق العشرة كلها، وكان متوسط العدد 10 حالات أسبوعياً. أما هذا الأسبوع فقد أرسلت 8 مرافق تقارير، وبلغ مجموع الحالات المبلغ عنها 18. العدد الخام يساوي 1.8 مرة المتوسط السابق، لكن اكتمال الإبلاغ انخفض من 10/10 = 100% إلى 8/10 = 80%. لا تقسم 18 آلياً على 0.80 ثم تسمِّ الناتج العدد الحقيقي؛ فقد يخدم المرفقان غير المبلغين سكاناً يختلف خطر المرض لديهم، وقد لا يكون الفقد عشوائياً. والاستنتاج التشغيلي الصحيح هو أن الإشارة تستدعي تحققاً سريعاً بالتوازي مع فحص اكتمال البيانات. اتصل بالمرفقين اللذين لم يبلغا؛ وتحقق هل لم توجد حالات أم لم يُرسل التقرير؛ وافحص ثبات تعريف الحالة والفترة؛ وراجع تواريخ بدء الأعراض والتأكيد المخبري والتكرارات المحتملة؛ وقارن بخط أساس موسمي مناسب. إذا كان بروتوكول مرض محدد يوجب الإبلاغ الفوري عن حالة مشتبهة واحدة، فإن هذه القاعدة تتقدم على عتبة عددية عامة. وثّق الإشارة وخطوات التحقق والأدلة والقرار والمسؤول وموعد المراجعة التالية. هذه أرقام مصطنعة للتعليم وليست مشاهدات من مديرية حقيقية. وفي التطبيق العملي لـF-107 يحسب الطالب اكتمال الإبلاغ، ويحدد ما الذي تثبته النسبة الخام وما لا تثبته، ويكتب طلب تحقق. المرجع: WHO EWAR — https://www.who.int/publications/i/item/9789240063587."}], "objEn": ["Name the five functions: detect, monitor, alert, evaluate, guide action.", "Trace the chain: collection → reporting → analysis → feedback → action.", "Explain why surveillance without feedback fails."], "objAr": ["تسمية الوظائف الخمس: الكشف والمراقبة والتنبيه والتقييم وتوجيه الإجراء.", "تتبع السلسلة: الجمع ← الإبلاغ ← التحليل ← التغذية الراجعة ← الإجراء.", "شرح لماذا يفشل الترصد بلا تغذية راجعة."]}', '[{"qEn": "The first purpose of surveillance is to…", "qAr": "الغرض الأول من الترصد هو أن…", "optsEn": ["Collect reports for filing", "Detect a rise early and guide action", "Replace outbreak investigation"], "optsAr": ["يجمع التقارير للحفظ", "يكشف الارتفاع مبكرا ويوجه الإجراء", "يحل محل التحقيق في الفاشية"], "ans": 1, "explEn": "Surveillance exists to produce timely action.", "explAr": "الترصد موجود لإنتاج إجراء في الوقت المناسب."}, {"qEn": "The surveillance chain is…", "qAr": "سلسلة الترصد هي…", "optsEn": ["Action → feedback → collection", "Reporting only", "Collection → reporting → analysis → feedback → action"], "optsAr": ["الإجراء ← التغذية الراجعة ← الجمع", "الإبلاغ فقط", "الجمع ← الإبلاغ ← التحليل ← التغذية الراجعة ← الإجراء"], "ans": 2, "explEn": "Each link must work for the next one to matter.", "explAr": "كل حلقة يجب أن تعمل حتى تهم التالية."}, {"qEn": "24 cases against a baseline of 10 is…", "qAr": "24 حالة مقابل خط أساس 10 هي…", "optsEn": ["2.4 times baseline", "14% higher", "10 times baseline"], "optsAr": ["2.4 ضعف خط الأساس", "أعلى 14%", "10 أضعاف خط الأساس"], "ans": 0, "explEn": "24 ÷ 10 = 2.4 times baseline (a 140% increase). The alert rule is locally defined for this exercise, not universal.", "explAr": "24 ÷ 10 = 2.4 مرة خط الأساس (زيادة 140%). قاعدة الإنذار محلية لهذا التمرين وليست عالمية."}, {"qEn": "Without feedback, reporters…", "qAr": "من دون تغذية راجعة، المبلغون…", "optsEn": ["Report more accurately", "Stop reporting, because they see no result", "Need no thresholds"], "optsAr": ["يبلغون بدقة أكثر", "يتوقفون عن الإبلاغ، لأنهم لا يرون نتيجة", "لا يحتاجون عتبات"], "ans": 1, "explEn": "Feedback keeps reporting alive.", "explAr": "التغذية الراجعة تبقي الإبلاغ حيا."}]' FROM courses WHERE course_code='B-108';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 2, 'الترصد السلبي والنشط والخافر', 'Passive, active and sentinel surveillance', '[''تعريف الترصد السلبي والنشط والخافر.'', ''مقارنة نقاط قوتها وضعفها وتكلفتها.'', ''اختيار نوع لغرض معين وكتابة تعريف حالته.'']', '[''Define passive, active and sentinel surveillance.'', ''Compare their strengths, weaknesses and costs.'', ''Choose a type for a given purpose and write its case definition.'']', 'الترصد السلبي ينتظر التقارير: العيادات والمختبرات ترسل الحالات كما تصل. وهو رخيص ويغطي مساحة واسعة، لكنه بطيء وناقص، ويفوّت من لم يطلبوا رعاية أبدا. والترصد النشط يذهب للبحث: الفريق يزور العيادات، ويراجع السجلات، ويتصل بالأسر، أو يبحث عن الحالات. وهو أسرع وأكمل للمنطقة التي يغطيها، لكنه يكلف أكثر ولا يمكنه تغطية كل مكان طوال الوقت. والترصد الخافر يراقب مواقع قليلة مختارة عن قرب — عيادات أو مستشفيات خافرة — لتتبع الاتجاهات وكشف الارتفاع مبكرا. وهو فعال للاتجاهات، لكنه لا يمكنه تقدير إجمالي عدد الحالات في كل السكان. وأيا كان النوع الذي تستخدمه، يجب أن يكون تعريف الحالة هو نفسه في كل مكان: نفس الشخص والمكان والزمان والمعايير السريرية أو المخبرية. وإذا استخدم موقع تعريفا مختلفا، لا يمكن مقارنة أرقامه. في مقارنة مثل 18 بلاغًا سلبيًا إضافة إلى 12 حالة إضافية عُثر عليها نشطًا، لا تصح نسبة 40% «الموجودة بالنشط فقط» إلا إذا كانت الحالات الاثنتا عشرة فريدة بعد إزالة التكرار، وبالتعريف والفترة نفسيهما، وكان البحث النشط مكتملًا بدرجة كافية في النطاق المحدد. ولا يُعد البحث النشط معيارًا ذهبيًا تلقائيًا وقد يفوّت حالات أيضًا.', 'Passive surveillance waits for reports: clinics and laboratories send cases as they arrive. It is cheap and covers a wide area, but it is slow, incomplete, and misses people who never seek care. Active surveillance goes looking: the team visits clinics, reviews registers, calls households, or searches for cases. It is faster and more complete for the area it covers, but it costs more and cannot cover everywhere all the time. Sentinel surveillance watches a few chosen sites closely — sentinel clinics or hospitals — to track trends and detect a rise early. It is efficient for trends, but it cannot estimate the total number of cases in the whole population. Whichever type you use, the case definition must be the same everywhere: the same person, place, time and clinical or laboratory criteria. If one site uses a different definition, its numbers cannot be compared. In a comparison such as 18 passive reports plus 12 additional cases found actively, the 40% “active-only” share is valid only if the 12 are unique after deduplication, use the same case definition and period, and the active search is sufficiently complete for the defined catchment. Active case finding is not automatically a gold standard and may still miss cases.', '{"exampleEn": "Field case — A sentinel clinic reports a doubling of cases. The team does not wait: it switches to active surveillance for one week in that neighbourhood — visiting clinics, reviewing registers, and calling households. It finds 12 more cases, confirms the rise, and starts control. Sentinel gave the alert; active gave the complete picture.", "exampleAr": "حالة ميدانية — عيادة خافرة تبلغ عن تضاعف الحالات. لا ينتظر الفريق: يتحول إلى ترصد نشط لأسبوع واحد في ذلك الحي — بزيارة العيادات ومراجعة السجلات والاتصال بالأسر. يجد 12 حالة أخرى، ويؤكد الارتفاع، ويبدأ السيطرة. الخافر أعطى التنبيه؛ والنشط أعطى الصورة الكاملة.", "fieldEn": "When you switch types, write the date and the reason. A trend that jumps because you started searching is not the same as a true rise.", "fieldAr": "عندما تبدّل الأنواع، اكتب التاريخ والسبب. اتجاه يقفز لأنك بدأت البحث ليس نفس ارتفاع حقيقي.", "calcTitleEn": "Worked calculation — what active finding adds", "calcTitleAr": "حساب محلول — ما يضيفه البحث النشط", "calcStepsEn": ["Step 1 — Passive reports in one week: 18 cases.", "Step 2 — Active visits find 12 more cases missed by passive reports: 18 + 12 = 30 cases.", "Step 3 — Share missed by passive: 12 ÷ 30 = 0.40 = 40%.", "Step 4 — Conclusion: passive surveillance alone would have missed 40% of cases that week."], "calcStepsAr": ["الخطوة 1 — البلاغات السلبية في أسبوع واحد: 18 حالة.", "الخطوة 2 — الزيارات النشطة تجد 12 حالة أخرى فاتت البلاغات السلبية: 18 + 12 = 30 حالة.", "الخطوة 3 — الحصة التي فاتت السلبي: 12 ÷ 30 = 0.40 = 40%.", "الخطوة 4 — الاستنتاج: الترصد السلبي وحده كان سيفوّت 40% من الحالات ذلك الأسبوع."], "calcResultEn": "Result: 30 unique cases were identified; 12/30 (40%) were found only through active search, assuming deduplication and comparable case definitions. This does not prove active search found every case.", "calcResultAr": "النتيجة: تم تحديد 30 حالة فريدة؛ وعُثر على 12/30 (40%) بالبحث النشط فقط، بافتراض إزالة التكرار وتوحيد تعريف الحالة. ولا يثبت ذلك أن البحث النشط اكتشف جميع الحالات.", "terms": [{"termEn": "Passive surveillance", "termAr": "الترصد السلبي", "defEn": "Waiting for routine reports to arrive.", "defAr": "انتظار التقارير الروتينية لتصل."}, {"termEn": "Active surveillance", "termAr": "الترصد النشط", "defEn": "Going to find cases: visits, register review, household calls.", "defAr": "الذهاب للبحث عن الحالات: زيارات ومراجعة سجلات واتصالات بالأسر."}, {"termEn": "Sentinel surveillance", "termAr": "الترصد الخافر", "defEn": "Watching a few chosen sites closely to track trends.", "defAr": "مراقبة مواقع قليلة مختارة عن قرب لتتبع الاتجاهات."}, {"termEn": "Case definition", "termAr": "تعريف الحالة", "defEn": "The same rule for who counts as a case, everywhere.", "defAr": "نفس القاعدة لتحديد من يُحسب حالة، في كل مكان."}], "deepSections": [{"titleEn": "Indicator-based and event-based surveillance: integrate rather than compete", "titleAr": "الترصد القائم على المؤشرات والقائم على الأحداث: تكامل لا تنافس", "bodyEn": "Indicator-based surveillance (IBS) collects structured data through routine case notifications, laboratory reports, registers or periodic summaries. It supports trend analysis and comparison when definitions, reporting units and time periods remain consistent. Event-based surveillance (EBS) detects signals from unstructured information: a health worker reports an unusual cluster, a community leader describes unexplained deaths, or several facilities note a syndrome not yet represented in a routine form. EBS is designed to be sensitive to unusual events, so many signals will not become confirmed outbreaks. A signal is information requiring triage; an alert is a signal that meets a locally agreed criterion for verification or response; a verified event is supported by further evidence. These labels should be defined in the local standard operating procedure. Triage should consider severity, unusualness, credibility, geographic spread, vulnerable groups, potential for transmission and whether an immediate action is available. Do not dismiss a community signal because it lacks a laboratory result, and do not label it a confirmed outbreak solely because it is alarming. Link EBS to IBS, laboratories, animal health, environmental health and community feedback where relevant. WHO EWAR emphasizes earlier detection and response in emergencies and the need for trust and coordination. Reference: WHO EWAR operational guide — https://www.who.int/publications/i/item/9789240063587; WHO surveillance in emergencies — https://www.who.int/emergencies/surveillance.", "bodyAr": "يجمع الترصد القائم على المؤشرات بيانات منظمة عبر الإخطارات الروتينية للحالات أو تقارير المختبر أو السجلات أو الملخصات الدورية. وهو يدعم تحليل الاتجاهات والمقارنة عندما تبقى التعريفات ووحدات الإبلاغ والفترات الزمنية متسقة. أما الترصد القائم على الأحداث فيكشف الإشارات من معلومات غير منظمة: يبلغ عامل صحي عن تجمع غير معتاد، أو يصف قائد مجتمعي وفيات غير مفسرة، أو تلاحظ عدة مرافق متلازمة لم يشملها النموذج الروتيني بعد. صُمم الترصد القائم على الأحداث ليكون حساساً للأحداث غير المعتادة، ولذلك لن تتحول إشارات كثيرة إلى فاشيات مؤكدة. الإشارة معلومة تحتاج إلى فرز أولي؛ والتنبيه إشارة تستوفي معياراً محلياً متفقاً عليه للتحقق أو الاستجابة؛ والحدث المتحقق منه تدعمه أدلة إضافية. يجب تعريف هذه المصطلحات في إجراءات التشغيل المحلية. وينبغي أن يراعي الفرز شدة الحدث وعدم اعتياديته ومصداقية المصدر والانتشار الجغرافي والفئات الهشة واحتمال الانتقال وإمكانية اتخاذ إجراء فوري. لا ترفض إشارة مجتمعية لغياب نتيجة مخبرية، ولا تصفها بفاشية مؤكدة لمجرد أنها مقلقة. اربط الترصد القائم على الأحداث بالترصد القائم على المؤشرات والمختبرات وصحة الحيوان والصحة البيئية والتغذية المجتمعية عند الصلة. تؤكد إرشادات WHO EWAR أهمية الكشف والاستجابة المبكرين في الطوارئ والثقة والتنسيق. المراجع: WHO EWAR — https://www.who.int/publications/i/item/9789240063587؛ وWHO، الترصد في الطوارئ — https://www.who.int/emergencies/surveillance."}, {"titleEn": "Choose and review alert thresholds without turning them into universal rules", "titleAr": "اختر عتبات التنبيه وراجعها دون تحويلها إلى قواعد عالمية", "bodyEn": "Thresholds are decision rules, not biological truths. A single case may trigger immediate investigation for a rare, eradication-targeted or high-consequence disease; an endemic syndrome may require a count, rate, proportion or statistical deviation from a baseline. Some systems use fixed thresholds, seasonal channels, moving averages or cumulative-sum methods. Each method has assumptions and trade-offs. A low threshold may detect events earlier but generate more false alerts and workload; a high threshold may reduce workload but miss or delay detection. Select the rule according to the disease, surveillance purpose, baseline quality, population size, seasonality, reporting completeness, laboratory access and response capacity. Specify the unit and time window (for example, cases per facility-week or incidence per 100,000 person-weeks), the comparison period, exclusions, escalation route and who can change the threshold. Reassess after changes in case definition, diagnostic availability, reporting coverage, population movement or intervention. Do not transfer a threshold from another district or disease without validation. A statistical signal is not the same as a confirmed outbreak, and absence of a signal does not prove absence of transmission when surveillance is weak. Reference: WHO EWAR operational guide — https://www.who.int/publications/i/item/9789240063587; CDC field investigation — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html.", "bodyAr": "العتبات قواعد لاتخاذ القرار وليست حقائق بيولوجية. فقد تستدعي حالة واحدة تحقيقاً فورياً لمرض نادر أو مستهدف للاستئصال أو ذي عواقب جسيمة؛ بينما قد تتطلب متلازمة متوطنة عتبة عدد أو معدل أو نسبة أو انحرافاً إحصائياً عن خط أساس. تستخدم بعض الأنظمة عتبات ثابتة أو قنوات موسمية أو متوسطات متحركة أو أساليب المجموع التراكمي. ولكل طريقة افتراضات ومفاضلات. قد تكشف العتبة المنخفضة الأحداث مبكراً لكنها تولد تنبيهات كاذبة وعبئاً أكبر؛ وقد تخفض العتبة المرتفعة العبء لكنها تفوّت الكشف أو تؤخره. اختر القاعدة وفق المرض وهدف الترصد وجودة خط الأساس وحجم السكان والموسمية واكتمال الإبلاغ وإتاحة المختبر وقدرة الاستجابة. حدد الوحدة والفترة (مثل الحالات لكل مرفق-أسبوع أو الحدوث لكل 100 ألف شخص-أسبوع)، وفترة المقارنة والاستبعادات ومسار التصعيد ومن يملك تعديل العتبة. أعد التقييم عند تغير تعريف الحالة أو إتاحة التشخيص أو تغطية الإبلاغ أو حركة السكان أو التدخلات. لا تنقل عتبة من مديرية أو مرض آخر دون تحقق. الإشارة الإحصائية ليست فاشية مؤكدة، وغياب الإشارة لا يثبت غياب الانتقال عندما يكون الترصد ضعيفاً. المراجع: WHO EWAR — https://www.who.int/publications/i/item/9789240063587؛ وCDC، التحقيق الميداني — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html."}, {"titleEn": "Alert verification: a reproducible triage checklist", "titleAr": "التحقق من التنبيه: قائمة فرز قابلة لإعادة التطبيق", "bodyEn": "When an alert arrives, record the source, time received, event description, location, affected group, reported count, severity and contact details in a restricted-access log. A trained focal person should acknowledge receipt and assign a verification owner. Check the source''s credibility and whether the information is first-hand or repeated from another source. Verify the case definition and dates; distinguish onset date from report date. Search for duplicate reports and confirm whether counts refer to people, visits, specimens or notifications. Compare the current period with an appropriate baseline using the same case definition and reporting coverage. Check denominator changes, population displacement, facility opening/closure, campaign activity, diagnostic test changes, stock-outs, media attention and reporting backlogs. Contact facilities and community informants; review registers; consult laboratory or veterinary/environmental experts when relevant. Grade the result (for example: unsubstantiated, under verification, verified event, or no event) according to the local SOP, and document evidence and uncertainty. Escalate immediately if the potential severity or transmissibility warrants precautionary action; verification should not become a reason for dangerous delay. The laboratory exercise should have students classify a set of mixed signals and defend which require immediate escalation, routine verification or closure with reasons. Reference: WHO EWAR — https://www.who.int/publications/i/item/9789240063587.", "bodyAr": "عند وصول تنبيه، سجّل المصدر ووقت الاستلام ووصف الحدث والموقع والفئة المتأثرة والعدد المبلغ عنه والشدة وبيانات الاتصال في سجل محدود الوصول. ينبغي لمسؤول مدرب تأكيد الاستلام وتعيين شخص للتحقق. افحص مصداقية المصدر وهل المعلومة مباشرة أم منقولة عن مصدر آخر. تحقق من تعريف الحالة والتواريخ، وميّز تاريخ بدء الأعراض عن تاريخ الإبلاغ. ابحث عن التقارير المكررة وتأكد هل تشير الأعداد إلى أشخاص أم زيارات أم عينات أم إخطارات. قارن الفترة الحالية بخط أساس مناسب باستخدام تعريف الحالة نفسه وتغطية الإبلاغ نفسها. افحص تغير المقامات ونزوح السكان وفتح المرافق أو إغلاقها والحملات وتغير الفحوص ونفاد المخزون والاهتمام الإعلامي وتراكم التقارير. اتصل بالمرافق والمخبرين المجتمعيين، وراجع السجلات، واستشر خبراء المختبر أو الطب البيطري أو البيئة عند الصلة. صنّف النتيجة (مثلاً: غير مدعومة، قيد التحقق، حدث متحقق منه، أو لا يوجد حدث) وفق الإجراء المحلي، ووثّق الأدلة وعدم اليقين. صعّد فوراً إذا كانت الشدة أو قابلية الانتقال المحتملة تستدعي إجراءً احترازياً؛ فلا ينبغي أن يصبح التحقق سبباً لتأخير خطير. ينبغي أن يطلب المختبر من الطلاب تصنيف مجموعة إشارات مختلطة وتبرير ما يحتاج إلى تصعيد فوري أو تحقق روتيني أو إغلاق. المرجع: WHO EWAR — https://www.who.int/publications/i/item/9789240063587."}], "objEn": ["Define passive, active and sentinel surveillance.", "Compare their strengths, weaknesses and costs.", "Choose a type for a given purpose and write its case definition."], "objAr": ["تعريف الترصد السلبي والنشط والخافر.", "مقارنة نقاط قوتها وضعفها وتكلفتها.", "اختيار نوع لغرض معين وكتابة تعريف حالته."]}', '[{"qEn": "Passive surveillance…", "qAr": "الترصد السلبي…", "optsEn": ["Visits every household", "Watches only one clinic", "Waits for routine reports"], "optsAr": ["يزور كل أسرة", "يراقب عيادة واحدة فقط", "ينتظر التقارير الروتينية"], "ans": 2, "explEn": "Passive waits; active goes looking.", "explAr": "السلبي ينتظر؛ والنشط يذهب للبحث."}, {"qEn": "Sentinel surveillance is best for…", "qAr": "الترصد الخافر أفضل لـ…", "optsEn": ["Tracking trends at chosen sites", "Counting every case in the country", "Replacing laboratory testing"], "optsAr": ["تتبع الاتجاهات في مواقع مختارة", "عدّ كل حالة في البلد", "استبدال الفحص المخبري"], "ans": 0, "explEn": "Sentinel sites track trends efficiently, not totals.", "explAr": "مواقع الخافر تتبع الاتجاهات بكفاءة، لا المجاميع."}, {"qEn": "18 passive + 12 active gives…", "qAr": "18 سلبي + 12 نشط تعطي…", "optsEn": ["18 cases, 12% active", "30 cases, 40% found only actively", "12 cases only"], "optsAr": ["18 حالة، و12% نشط", "30 حالة، و40% وُجدت نشطا فقط", "12 حالة فقط"], "ans": 1, "explEn": "12 ÷ 30 = 40%, provided the 12 are unique additional cases and both approaches use the same case definition and period.", "explAr": "12 ÷ 30 = 40% بشرط أن تكون الحالات الاثنتا عشرة إضافية وفريدة، وأن يستخدم الأسلوبان تعريف الحالة والفترة نفسيهما."}, {"qEn": "If sites use different case definitions…", "qAr": "إذا استخدمت المواقع تعريفات حالة مختلفة…", "optsEn": ["Their numbers are more accurate", "Completeness improves", "Their numbers cannot be compared"], "optsAr": ["أرقامها أدق", "الاكتمال يتحسن", "لا يمكن مقارنة أرقامها"], "ans": 2, "explEn": "A shared definition is what makes comparison possible.", "explAr": "التعريف المشترك هو ما يجعل المقارنة ممكنة."}]' FROM courses WHERE course_code='B-108';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 3, 'تقييم نظام الترصد', 'Evaluating a surveillance system', '[''تعريف الحساسية والقيمة التنبؤية الإيجابية والسرعة والتمثيل.'', ''حساب القيمة التنبؤية الإيجابية من جدول على نمط 2×2.'', ''استخدام قائمة فحص للحكم على نظام وتسمية إصلاح واحد.'']', '[''Define sensitivity, PPV, timeliness and representativeness.'', ''Calculate PPV from a 2×2-style table.'', ''Use a checklist to judge a system and name one fix.'']', 'نظام الترصد يجب تقييمه، لا افتراض أنه جيد. الحساسية: من الحالات الحقيقية في السكان، أي حصة يلتقطها النظام؟ نظام يلتقط 40% يفوّت أغلب الحالات. والقيمة التنبؤية الإيجابية: من الحالات التي يبلغ عنها النظام، أي حصة حالات حقيقية؟ قيمة منخفضة تعني إنذارات خاطئة كثيرة. والسرعة: هل تصل التقارير في الوقت المناسب للتصرف؟ والتمثيل: هل يغطي النظام كل المجموعات والأماكن، أم العيادات الأسهل فقط؟ والبساطة والمرونة والقبول مهمة أيضا: نظام يجده المبلغون مرهقا سيُهجر. وينتهي التقييم بإصلاح أو اثنين، بمالك وتاريخ — لا بقائمة أمنيات طويلة. الحساسية = الحالات الحقيقية التي اكتشفها النظام ÷ جميع الحالات الحقيقية في السكان خلال الفترة نفسها. والقيمة التنبؤية الإيجابية = الحالات الحقيقية بين بلاغات النظام ÷ جميع البلاغات المصنفة حالات. لا يمكن حساب الحساسية من وجود 40 حالة حقيقية بين 50 بلاغًا وحده؛ بل يجب تقدير العدد الكلي للحالات الحقيقية في السكان بصورة مستقلة. كما تتأثر القيمة التنبؤية الإيجابية بمعدل حدوث المرض الأساسي وتعريف الحالة. اختر خصائص التقييم وفق أهداف النظام، ولا تفترض تساوي أولوية جميع الخصائص.', 'A surveillance system must be evaluated, not assumed good. Sensitivity: of the true cases in the population, what share does the system catch? A system that catches 40% is missing most cases. Positive predictive value (PPV): of the cases the system reports, what share are true cases? A low PPV means many false alarms. Timeliness: do reports arrive in time to act? Representativeness: does the system cover all groups and places, or only the easiest clinics? Simplicity, flexibility and acceptability also matter: a system reporters find burdensome will be abandoned. Evaluation ends with one or two fixes, with an owner and a date — not with a long wish list. Sensitivity = true cases detected by the system ÷ all true cases in the population during the same period. PPV = true cases among system reports ÷ all reports classified as cases. Sensitivity cannot be calculated from the 40 true cases among 50 reports alone: the total number of true cases in the population must be estimated independently. PPV also depends on the underlying frequency of disease and the case definition. Select attributes according to the system objectives rather than assuming every attribute has equal priority.', '{"exampleEn": "Field case — The four-week dataset contains 60 alerts classified as cases; 48 are confirmed true cases, so PPV = 80%. Sensitivity remains not estimable because the total number of true cases, including missed cases, has not been independently ascertained.", "exampleAr": "حالة ميدانية — تتضمن بيانات الأسابيع الأربعة 60 تنبيهًا صُنّف كحالة؛ تأكد أن 48 منها حالات حقيقية، لذا القيمة التنبؤية الإيجابية = 80%. وتظل الحساسية غير قابلة للتقدير لأن العدد الكلي للحالات الحقيقية، بما فيها الحالات الفائتة، لم يُحدد بصورة مستقلة.", "fieldEn": "Evaluate with numbers and a checklist. End with one fix, an owner and a date. Reference basis: CDC, Updated Guidelines for Evaluating Public Health Surveillance Systems (2001), including sensitivity, PPV, timeliness, representativeness and data quality.", "fieldAr": "قيّم بأرقام وقائمة فحص. وأنهِ بإصلاح واحد ومالك وتاريخ. مرجع المراجعة: CDC، الإرشادات المحدّثة لتقييم نظم الترصد للصحة العامة (2001)، وتشمل الحساسية والقيمة التنبؤية الإيجابية والالتزام بالموعد والتمثيل وجودة البيانات.", "calcTitleEn": "Worked calculation — PPV of a surveillance alert", "calcTitleAr": "حساب محلول — القيمة التنبؤية الإيجابية لتنبيه ترصد", "calcStepsEn": ["Step 1 — Reports classified as cases during the month: 60.", "Step 2 — True cases confirmed among those reports: 48; false-positive reports = 60 − 48 = 12.", "Step 3 — PPV = 48 ÷ 60 = 0.80 = 80%.", "Step 4 — Sensitivity cannot be calculated without an independent estimate of all true cases in the population, including those missed by the system."], "calcStepsAr": ["الخطوة 1 — البلاغات المصنفة حالات خلال الشهر: 60.", "الخطوة 2 — الحالات الحقيقية المؤكدة بين تلك البلاغات: 48؛ والبلاغات الإيجابية الكاذبة = 60 − 48 = 12.", "الخطوة 3 — القيمة التنبؤية الإيجابية = 48 ÷ 60 = 0.80 = 80%.", "الخطوة 4 — لا يمكن حساب الحساسية دون تقدير مستقل لجميع الحالات الحقيقية في السكان، بما فيها الحالات التي لم يكتشفها النظام."], "calcResultEn": "Result: PPV = 48/60 = 80%, matching the four-week training dataset. Sensitivity cannot be calculated without an independent estimate of all true cases in the population, including those missed by the system.", "calcResultAr": "النتيجة: القيمة التنبؤية الإيجابية = 48/60 = 80%، بما يتفق مع مجموعة بيانات الأسابيع الأربعة. ولا يمكن حساب الحساسية دون تقدير مستقل لجميع الحالات الحقيقية في السكان، بما فيها الحالات التي لم يكتشفها النظام.", "terms": [{"termEn": "Sensitivity", "termAr": "الحساسية", "defEn": "True cases caught divided by all true cases.", "defAr": "الحالات الحقيقية الملتقطة مقسومة على كل الحالات الحقيقية."}, {"termEn": "PPV", "termAr": "القيمة التنبؤية الإيجابية", "defEn": "True cases among reported cases.", "defAr": "الحالات الحقيقية بين الحالات المبلغ عنها."}, {"termEn": "Timeliness", "termAr": "السرعة", "defEn": "Reports arriving in time to act.", "defAr": "التقارير التي تصل في الوقت المناسب للتصرف."}, {"termEn": "Representativeness", "termAr": "التمثيل", "defEn": "Coverage of all groups and places, not only the easiest sites.", "defAr": "تغطية كل المجموعات والأماكن، لا المواقع الأسهل فقط."}], "deepSections": [{"titleEn": "Evaluate surveillance attributes as a balanced system", "titleAr": "قيّم خصائص الترصد بوصفه نظاماً متوازناً", "bodyEn": "Evaluation asks whether a surveillance system meets its purpose and produces useful public-health action. Usefulness is the extent to which it contributes to prevention and control. Simplicity concerns the structure and operation; flexibility is the ability to adapt to changing information needs. Acceptability reflects willingness of people and organizations to participate. Sensitivity is the ability to identify cases or events that truly occur, while positive predictive value (PPV) is the proportion of reported alerts or cases that are true under the chosen verification standard. Representativeness describes how well the data reflect the distribution of events by person, place and time. Timeliness concerns speed from event occurrence through detection, reporting, analysis and action. Stability concerns reliability and availability. Data quality includes completeness and validity. These attributes interact: adding many mandatory fields may improve detail but reduce simplicity and timeliness; broad case definitions may improve sensitivity but lower PPV. Evaluation must therefore begin with a clear objective and stakeholder use, not a generic scorecard. Stratify performance by facility and location because a high overall average can conceal underserved groups. Reference: CDC Updated Guidelines for Evaluating Public Health Surveillance Systems — https://www.cdc.gov/mmwr/preview/mmwrhtml/rr5013a1.htm; WHO EWAR — https://www.who.int/publications/i/item/9789240063587.", "bodyAr": "يسأل تقييم الترصد هل يحقق النظام غرضه وينتج إجراءً مفيداً للصحة العامة. وتعني المنفعة مدى مساهمته في الوقاية والسيطرة. وتشير البساطة إلى بنية النظام وتشغيله؛ والمرونة إلى قدرته على التكيف مع احتياجات معلومات متغيرة. وتعكس المقبولية استعداد الأفراد والمنظمات للمشاركة. أما الحساسية فهي قدرة النظام على تحديد الحالات أو الأحداث التي تقع فعلاً، والقيمة التنبؤية الإيجابية هي نسبة التنبيهات أو الحالات المبلغ عنها التي يتبين أنها حقيقية وفق معيار التحقق المختار. وتمثّل التمثيلية مدى انعكاس البيانات لتوزيع الأحداث حسب الشخص والمكان والزمان. وتتعلق سرعة التوقيت بالمدة من وقوع الحدث حتى الكشف والإبلاغ والتحليل والإجراء. وتعني الثبات موثوقية النظام وتوافره. وتشمل جودة البيانات الاكتمال والصحة. وتتفاعل هذه الخصائص: فقد تؤدي إضافة حقول إلزامية كثيرة إلى زيادة التفاصيل لكنها تخفض البساطة والسرعة؛ وقد يحسن تعريف الحالة الواسع الحساسية لكنه يخفض القيمة التنبؤية الإيجابية. لذلك يجب أن يبدأ التقييم بهدف واضح واستخدام أصحاب المصلحة، لا ببطاقة درجات عامة. حلل الأداء حسب المرفق والموقع لأن المتوسط العام المرتفع قد يخفي فئات محرومة من الخدمة. المراجع: إرشادات CDC المحدّثة لتقييم نظم الترصد — https://www.cdc.gov/mmwr/preview/mmwrhtml/rr5013a1.htm؛ وWHO EWAR — https://www.who.int/publications/i/item/9789240063587."}, {"titleEn": "Worked indicators: completeness, timeliness and alert confirmation", "titleAr": "مؤشرات محلولة: الاكتمال والتوقيت وتأكيد التنبيه", "bodyEn": "Use the existing F-107 four-week training dataset. Week 3 contains 12 cases found through active case finding among 30 total cases, so the active-only share is 12/30 × 100 = 40%. Across the four weeks, alerts total 8 + 10 + 20 + 22 = 60 and verified true alerts total 7 + 8 + 16 + 17 = 48; alert PPV is therefore 48/60 × 100 = 80% under the dataset''s stated verification classification. This is not system sensitivity, because the dataset does not enumerate all events that surveillance failed to detect. The dataset does not contain the number of reports expected from all facilities or due dates, so reporting completeness and timeliness cannot be calculated from these fields; do not invent their denominators. In a separate system evaluation, completeness may be defined as reports received divided by reports expected, and timeliness as reports received by the agreed deadline divided by the stated denominator (received or expected reports, which must be declared). Report numerator, denominator, period, data source and missingness with every indicator. Do not interpret high PPV as proof of high sensitivity. The existing F-107 lab asks learners to calculate the 40% active-only share and 80% PPV, trace the surveillance chain and recommend one owned, dated correction. The training dataset is synthetic. Reference: CDC surveillance evaluation guidance — https://www.cdc.gov/mmwr/preview/mmwrhtml/rr5013a1.htm.", "bodyAr": "استخدم مجموعة بيانات التدريب الحالية لـF-107 ذات الأسابيع الأربعة. يحتوي الأسبوع الثالث على 12 حالة اكتُشفت بالبحث النشط من أصل 30 حالة إجمالية؛ لذلك حصة الحالات المكتشفة نشطاً فقط = 12/30 × 100 = 40%. وعلى امتداد الأسابيع الأربعة، يبلغ مجموع التنبيهات 8 + 10 + 20 + 22 = 60، ويبلغ مجموع التنبيهات الحقيقية المتحقق منها 7 + 8 + 16 + 17 = 48؛ لذلك القيمة التنبؤية الإيجابية للتنبيهات = 48/60 × 100 = 80% وفق تصنيف التحقق المحدد في مجموعة البيانات. هذه ليست حساسية النظام، لأن مجموعة البيانات لا تحصر جميع الأحداث التي فشل الترصد في اكتشافها. ولا تتضمن البيانات عدد التقارير المتوقع من جميع المرافق أو مواعيد استحقاقها؛ لذلك لا يمكن حساب اكتمال الإبلاغ أو الالتزام بالوقت من هذه الحقول، ولا يجوز اختراع مقام لهما. وفي تقييم منفصل للنظام، يمكن تعريف الاكتمال بأنه التقارير المستلمة ÷ التقارير المتوقعة، والالتزام بالوقت بأنه التقارير المستلمة في الموعد ÷ المقام المعلن (التقارير المستلمة أو المتوقعة، ويجب تحديده). أبلغ مع كل مؤشر عن البسط والمقام والفترة ومصدر البيانات والفقد. لا تفسر القيمة التنبؤية المرتفعة على أنها إثبات لحساسية مرتفعة. يطلب مختبر F-107 الموجود من الطلاب حساب حصة 40% والقيمة التنبؤية 80% وتتبع سلسلة الترصد واقتراح تصحيح واحد له مسؤول وموعد. مجموعة البيانات تدريبية اصطناعية. المرجع: إرشادات CDC لتقييم الترصد — https://www.cdc.gov/mmwr/preview/mmwrhtml/rr5013a1.htm."}, {"titleEn": "Close the surveillance loop with feedback, action logs and review", "titleAr": "أغلق حلقة الترصد بالتغذية الراجعة وسجل الإجراءات والمراجعة", "bodyEn": "A surveillance bulletin should answer the operational questions: what changed, where, among whom, how certain is the signal, what has been done, and what is needed next? Provide feedback to facilities in a predictable schedule and format. Use an action log with alert identifier, date received, verification status, decision, responsible officer, action due date, completion evidence and review trigger. Monitor whether alerts lead to timely investigation and whether control actions change the outcome. A fall in reported cases may reflect successful control, reduced access to care, reporting fatigue, stock-outs or a change in case definition; interpret it with independent indicators such as facility attendance, test volume, positivity, community reports and completeness. Review thresholds and data definitions after major system changes. Conduct periodic tabletop exercises so staff know how to route an alert and who can authorize escalation. The F-107 capstone should ask learners to turn a verified signal into a one-page bulletin and a documented action plan, then present the limitations to a district decision-maker. The key bridge to F-108 is this: surveillance detects and verifies a signal; outbreak response investigates the event, controls risk and feeds findings back into surveillance. Reference: WHO surveillance in emergencies — https://www.who.int/emergencies/surveillance; WHO EWAR — https://www.who.int/publications/i/item/9789240063587.", "bodyAr": "ينبغي أن تجيب نشرة الترصد عن الأسئلة التشغيلية: ما الذي تغير؟ وأين؟ ولدى من؟ وما درجة اليقين في الإشارة؟ وما الذي نُفذ؟ وما المطلوب تالياً؟ قدم تغذية راجعة للمرافق وفق جدول وصيغة متوقعين. استخدم سجل إجراءات يتضمن معرف التنبيه وتاريخ الاستلام وحالة التحقق والقرار والمسؤول وموعد الإجراء ودليل الإنجاز ومحفز المراجعة. راقب هل تؤدي التنبيهات إلى تقصٍّ في الوقت المناسب وهل تغير إجراءات السيطرة النتيجة. قد يعكس انخفاض الحالات المبلغ عنها نجاح السيطرة أو انخفاض الوصول إلى الرعاية أو إرهاق الإبلاغ أو نفاد المخزون أو تغير تعريف الحالة؛ لذلك فسّره مع مؤشرات مستقلة مثل مراجعات المرافق وحجم الفحوص والإيجابية والبلاغات المجتمعية والاكتمال. راجع العتبات وتعريفات البيانات بعد التغييرات الكبيرة في النظام. نفّذ تمارين محاكاة مكتبية دورية حتى يعرف الموظفون كيفية تمرير التنبيه ومن يملك صلاحية التصعيد. ينبغي لمشروع F-107 الختامي أن يطلب من الطلاب تحويل إشارة متحقق منها إلى نشرة من صفحة واحدة وخطة إجراءات موثقة، ثم عرض القيود على مسؤول المديرية. والوصلة الأساسية إلى F-108 هي: يكشف الترصد الإشارة ويتحقق منها؛ ثم يستقصي رد الفاشية الحدث ويحد من الخطر ويعيد النتائج إلى نظام الترصد. المراجع: WHO، الترصد في الطوارئ — https://www.who.int/emergencies/surveillance؛ وWHO EWAR — https://www.who.int/publications/i/item/9789240063587."}], "objEn": ["Define sensitivity, PPV, timeliness and representativeness.", "Calculate PPV from a 2×2-style table.", "Use a checklist to judge a system and name one fix."], "objAr": ["تعريف الحساسية والقيمة التنبؤية الإيجابية والسرعة والتمثيل.", "حساب القيمة التنبؤية الإيجابية من جدول على نمط 2×2.", "استخدام قائمة فحص للحكم على نظام وتسمية إصلاح واحد."]}', '[{"qEn": "PPV = 48 true cases among 60 reported alerts is…", "qAr": "القيمة التنبؤية الإيجابية = 48 حالة حقيقية من 60 بلاغًا هي…", "optsEn": ["80%", "40%", "20%"], "optsAr": ["80%", "40%", "20%"], "ans": 0, "explEn": "48 ÷ 60 = 80%, matching the monthly training dataset.", "explAr": "48 ÷ 60 = 80%، بما يتفق مع مجموعة البيانات الشهرية."}, {"qEn": "Sensitivity asks…", "qAr": "الحساسية تسأل…", "optsEn": ["How many reports arrive on time?", "What share of true cases does the system catch?", "How simple is the form?"], "optsAr": ["كم تقريرا يصل في الوقت؟", "أي حصة من الحالات الحقيقية يلتقطها النظام؟", "كم النموذج بسيط؟"], "ans": 1, "explEn": "Sensitivity requires all true cases in the population as the denominator, including cases missed by surveillance.", "explAr": "تتطلب الحساسية مقامًا يشمل جميع الحالات الحقيقية في السكان، بما فيها الحالات التي لم يكتشفها الترصد."}, {"qEn": "A low PPV means…", "qAr": "قيمة تنبؤية إيجابية منخفضة تعني…", "optsEn": ["No cases exist", "Perfect timeliness", "Many false alarms"], "optsAr": ["لا حالات موجودة", "سرعة كاملة", "إنذارات خاطئة كثيرة"], "ans": 2, "explEn": "Low PPV = few reported cases are true.", "explAr": "قيمة منخفضة = قلة من الحالات المبلغ عنها حقيقية."}, {"qEn": "Representativeness means…", "qAr": "التمثيل يعني…", "optsEn": ["Coverage of all groups and places", "Only the easiest clinics report", "Reports arrive on time"], "optsAr": ["تغطية كل المجموعات والأماكن", "العيادات الأسهل فقط تبلغ", "التقارير تصل في الوقت"], "ans": 0, "explEn": "A representative system does not leave out a valley or a group.", "explAr": "النظام الممثل لا يترك واديا أو مجموعة."}]' FROM courses WHERE course_code='B-108';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 1, 'الاستجابة للفاشية: الخطوات 1–5', 'Outbreak response: steps 1–5', '[''سرد خطوات الفاشية 1–5 بالترتيب.'', ''التحقق من فاشية وكتابة تعريف حالة.'', ''الوصف حسب الشخص والمكان والزمان، ثم تكوين فرضية.'']', '[''List outbreak steps 1–5 in order.'', ''Verify an outbreak and write a case definition.'', ''Describe by person, place and time, then form a hypothesis.'']', 'إطار الخطوات العشر للتحقيق في الفاشيات تسلسل تعليمي مفيد، وليس ترتيبًا جامدًا عالميًا. تشمل الأنشطة الأولى الاستعداد، والتحقق من أن الزيادة حقيقية، والتحقق من التشخيص، ووضع تعريف حالة عملي، والبحث عن الحالات، ووصف الشخص والمكان والزمان. يجب أن يحدد تعريف الحالة السكان والمكان والفترة والمعايير السريرية أو المخبرية؛ كما يجب أن تتبع تصنيفات مشتبهة ومحتملة ومؤكدة البروتوكول الخاص بالمرض. طوّر الفرضيات واختبرها بمقارنة مناسبة ومقامات صحيحة. ويمكن بدء تدابير السيطرة المهمة في أي مرحلة عندما يستدعي خطر الصحة العامة ذلك؛ فلا تؤخر السيطرة المتناسبة انتظارًا لنتيجة تحليلية مثالية. غالبًا ما تتداخل الخطوات، وقد يُنقح تعريف الحالة العملي مع تطور الأدلة.', 'A ten-step outbreak-investigation framework is a useful teaching sequence, not a rigid universal order. The first activities include preparation, verifying that the increase is real, verifying diagnosis, establishing a working case definition, finding cases, and describing person, place and time. The case definition should specify the population, place, period and clinical/laboratory criteria; suspected, probable and confirmed classifications must follow the disease-specific protocol. Develop hypotheses and test them with an appropriate comparison and valid denominators. Important control measures may begin at any stage when the public-health risk warrants action; do not delay proportionate control while waiting for a perfect analytic result. Steps often overlap, and the working case definition may be refined as evidence develops.', '{"exampleEn": "Field case — The team verifies the increase, defines a case as a wedding guest with 3 or more loose stools in 24 hours and onset 1–6 June, and enumerates 150 guests. It identifies 45 probable cases and describes the curve. The team develops a food hypothesis while initiating proportionate hygiene and food-safety actions; it does not wait for every analytic result.", "exampleAr": "حالة ميدانية — يتحقق الفريق من الزيادة، ويعرّف الحالة بأنها ضيف زفاف لديه ثلاث مرات أو أكثر من البراز الرخو خلال 24 ساعة وبدأت الأعراض بين 1 و6 يونيو، ويحصر 150 ضيفًا. ويحدد 45 حالة محتملة ويصف المنحنى. يضع الفريق فرضية غذائية مع بدء إجراءات متناسبة للنظافة وسلامة الغذاء؛ ولا ينتظر جميع النتائج التحليلية.", "fieldEn": "Write steps 1–5 on one page before you act. If the case definition is missing, stop and write it. Reference basis: CDC Field Epidemiology Manual, “Conducting a Field Investigation”; steps overlap and control can be concurrent.", "fieldAr": "اكتب الخطوات 1–5 في صفحة واحدة قبل أن تتصرف. وإذا كان تعريف الحالة غائبا، توقف واكتبه. مرجع المراجعة: دليل CDC الميداني للوبائيات، «إجراء تحقيق ميداني»؛ فالخطوات قد تتداخل ويمكن تنفيذ السيطرة بالتوازي.", "calcTitleEn": "Worked calculation — attack rate for the first description", "calcTitleAr": "حساب محلول — معدل الهجوم للوصف الأول", "calcStepsEn": ["Step 1 — Cases among wedding guests: 45.", "Step 2 — Guests at risk: 150.", "Step 3 — Divide: 45 ÷ 150 = 0.30.", "Step 4 — As a percentage: 0.30 × 100 = 30% attack rate."], "calcStepsAr": ["الخطوة 1 — الحالات بين ضيوف الزفاف: 45.", "الخطوة 2 — الضيوف المعرضون للخطر: 150.", "الخطوة 3 — اقسم: 45 ÷ 150 = 0.30.", "الخطوة 4 — كنسبة مئوية: 0.30 × 100 = 30% معدل هجوم."], "calcResultEn": "Result: 45/150 = 30% among the defined wedding-guest cohort during the specified period. Household contacts are outside this guest-cohort calculation. Control measures may be initiated in parallel when risk warrants.", "calcResultAr": "النتيجة: 45/150 = 30% بين مجموعة ضيوف الزفاف المحددة خلال الفترة المذكورة. المخالطون الأسريون خارج حساب مجموعة الضيوف. ويمكن بدء تدابير السيطرة بالتوازي عندما يستدعي الخطر ذلك.", "terms": [{"termEn": "Verify", "termAr": "التحقق", "defEn": "Check the rise is real, not a reporting artefact.", "defAr": "التحقق أن الارتفاع حقيقي، لا أثر إبلاغ."}, {"termEn": "Case definition", "termAr": "تعريف الحالة", "defEn": "Person, place, time and clinical or laboratory criteria.", "defAr": "الشخص والمكان والزمان والمعايير السريرية أو المخبرية."}, {"termEn": "Describe", "termAr": "الوصف", "defEn": "Line list, person–place–time tables and epidemic curve.", "defAr": "قائمة حالات وجداول الشخص والمكان والزمان ومنحنى وبائي."}, {"termEn": "Hypothesis", "termAr": "الفرضية", "defEn": "A testable proposed exposure from the description.", "defAr": "تعرض مقترح قابل للاختبار من الوصف."}], "deepSections": [{"titleEn": "Verify the signal, the diagnosis and the existence of an outbreak", "titleAr": "تحقق من الإشارة والتشخيص ووجود الفاشية", "bodyEn": "An outbreak is generally more cases than expected in a defined population, place and period, but the operational definition depends on the disease and setting. A single case can be an outbreak trigger for a rare or immediately notifiable condition; for a common endemic syndrome, comparison with a suitable baseline is usually needed. Before declaring an outbreak, check whether the increase is real: compare the same case definition, population, time window, reporting coverage, healthcare access, diagnostic testing and seasonality. A rise in positive tests may reflect more testing or a laboratory contamination event rather than increased disease. Verify diagnosis through clinical review, record review and laboratory consultation as appropriate; do not demand laboratory confirmation for every case if doing so would delay necessary action or if the protocol allows clinical/epidemiological classification. Prepare the team: define roles, logistics, transport, communication, safety and infection prevention requirements, specimen pathways and data protection. Initial risk reduction may begin while verification continues if the potential harm is serious. The CDC field-investigation framework notes that steps can overlap and that control measures may be implemented concurrently. Reference: CDC, Conducting a Field Investigation — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html; WHO, Stages to follow in an outbreak investigation — https://www.who.int/emergencies/outbreak-toolkit/standardized-data-collection-tools/investigating-outbreak-of-unknown-disease.", "bodyAr": "تُعرّف الفاشية عموماً بأنها وقوع حالات أكثر مما هو متوقع في مجتمع ومكان وفترة محددة، لكن التعريف التشغيلي يعتمد على المرض والسياق. وقد تكون حالة واحدة محفزاً للتحقيق في مرض نادر أو واجب الإبلاغ الفوري؛ أما المتلازمة المتوطنة الشائعة فعادة تحتاج إلى مقارنة بخط أساس مناسب. قبل إعلان الفاشية، تحقق هل الزيادة حقيقية: قارن تعريف الحالة نفسه والسكان والفترة وتغطية الإبلاغ والوصول إلى الرعاية والفحوص التشخيصية والموسمية. فقد تعكس زيادة الفحوص الإيجابية إجراء فحوص أكثر أو تلوثاً مخبرياً لا زيادة المرض. تحقق من التشخيص بالمراجعة السريرية ومراجعة السجلات والاستشارة المخبرية حسب الحاجة؛ ولا تشترط التأكيد المخبري لكل حالة إذا كان ذلك سيؤخر إجراءً ضرورياً أو كان البروتوكول يسمح بالتصنيف السريري أو الوبائي. جهّز الفريق: حدد الأدوار واللوجستيات والنقل والاتصال والسلامة ومتطلبات الوقاية من العدوى ومسارات العينات وحماية البيانات. ويمكن بدء خفض الخطر الأولي أثناء استمرار التحقق إذا كان الضرر المحتمل جسيماً. يوضح إطار CDC للتحقيق الميداني أن الخطوات قد تتداخل وأن تدابير السيطرة قد تُنفذ بالتوازي. المراجع: CDC، إجراء تحقيق ميداني — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html؛ وWHO، مراحل التحقيق في الفاشية — https://www.who.int/emergencies/outbreak-toolkit/standardized-data-collection-tools/investigating-outbreak-of-unknown-disease."}, {"titleEn": "Construct a working case definition and manage its revisions", "titleAr": "أنشئ تعريف حالة عملياً وأدر مراجعاته", "bodyEn": "A case definition is a standardized classification rule for identifying people who may be part of the event; it is not necessarily a clinical diagnosis. Specify person or population, place, time period and clinical, epidemiological or laboratory criteria. Use suspected, probable and confirmed categories only as defined by the disease-specific national or international protocol. At the beginning, a sensitive definition can help find a broad set of possible cases; it may have lower specificity and include non-cases. As evidence develops, refine the definition without retrospectively hiding the effect of the change. Version every definition with date, rationale, criteria and effective period, and communicate it to all case finders. Apply the same version consistently when comparing groups or calculating rates. Avoid adding an exposure criterion to the case definition if that exposure is the hypothesis being tested; doing so creates circular reasoning and can bias the association. Distinguish a suspected syndrome from a confirmed pathogen diagnosis. The line list should retain the classification and definition version used for each record. The laboratory exercise should ask students to classify short vignettes under a supplied protocol and explain why a case may move from suspected to probable or confirmed. Reference: CDC Field Investigation — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html; WHO outbreak investigation stages — https://www.who.int/emergencies/outbreak-toolkit/standardized-data-collection-tools/investigating-outbreak-of-unknown-disease.", "bodyAr": "تعريف الحالة قاعدة تصنيف موحدة لتحديد الأشخاص الذين قد يكونون جزءاً من الحدث؛ وليس بالضرورة تشخيصاً سريرياً. حدد الشخص أو المجتمع والمكان والفترة الزمنية والمعايير السريرية أو الوبائية أو المخبرية. لا تستخدم فئات مشتبهة ومحتملة ومؤكدة إلا وفق تعريف البروتوكول الوطني أو الدولي الخاص بالمرض. في البداية قد يساعد التعريف الحساس على العثور على مجموعة واسعة من الحالات المحتملة؛ لكنه قد يكون أقل نوعية ويضم غير الحالات. ومع تطور الأدلة، نقّح التعريف دون إخفاء أثر التغيير بأثر رجعي. أعطِ كل إصدار رقماً وتاريخاً ومبرراً ومعايير وفترة سريان، وبلّغه لجميع الباحثين عن الحالات. طبّق الإصدار نفسه باستمرار عند مقارنة المجموعات أو حساب المعدلات. تجنب إدخال التعرض محل الفرضية ضمن تعريف الحالة؛ لأن ذلك ينشئ استدلالاً دائرياً وقد يحيّز الارتباط. ميّز المتلازمة المشتبهة عن التشخيص المؤكد للعامل الممرض. وينبغي أن تحتفظ قائمة الحالات بتصنيف كل سجل وإصدار التعريف المستخدم. يجب أن يطلب المختبر من الطلاب تصنيف حالات وصفية قصيرة وفق بروتوكول معطى وشرح سبب انتقال الحالة من مشتبهة إلى محتملة أو مؤكدة. المراجع: CDC، التحقيق الميداني — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html؛ وWHO، مراحل التحقيق في الفاشية — https://www.who.int/emergencies/outbreak-toolkit/standardized-data-collection-tools/investigating-outbreak-of-unknown-disease."}, {"titleEn": "Worked verification example: a cluster is a trigger, not yet a conclusion", "titleAr": "مثال محلول للتحقق: التجمع محفز للتحقيق وليس استنتاجاً نهائياً", "bodyEn": "In a fictional district, 15 syndrome reports arrive this week compared with a usual weekly count of 6. The crude ratio is 15/6 = 2.5, or 150% above the baseline. This is a signal, not proof of an outbreak. The team checks whether the same facilities reported, whether the reporting week has the same number of days, whether a new alert form was introduced, whether clinics expanded opening hours, whether testing increased, and whether the six-case baseline reflects the same season. It then reviews onset dates and symptoms, contacts facilities, checks duplicates and consults the laboratory about specimen quality and test changes. If the syndrome is associated with a high-consequence disease, the relevant protocol may require immediate escalation before the comparison is complete. Record both the raw signal and the verification result. Do not silently adjust the count for incomplete reporting unless a defensible method and assumptions are specified. These values are constructed for teaching and do not describe a real outbreak. In the F-108 lab, students should complete a verification matrix with evidence, alternative explanations, urgency and decision. Reference: CDC field investigation — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html.", "bodyAr": "في مديرية افتراضية، وصلت هذا الأسبوع 15 بلاغاً عن متلازمة مقارنة بعدد أسبوعي معتاد قدره 6. النسبة الخام 15/6 = 2.5، أي أعلى من خط الأساس بنسبة 150%. هذه إشارة وليست دليلاً قاطعاً على فاشية. يفحص الفريق هل أبلغت المرافق نفسها، وهل أسبوع الإبلاغ له عدد الأيام نفسه، وهل أُدخل نموذج تنبيه جديد، وهل مددت العيادات ساعات العمل، وهل زاد الفحص، وهل يعكس خط الأساس المكون من ست حالات الموسم نفسه. ثم يراجع تواريخ بدء الأعراض والأعراض، ويتصل بالمرافق، ويفحص التكرارات، ويستشير المختبر بشأن جودة العينات وتغير الفحوص. إذا ارتبطت المتلازمة بمرض ذي عواقب خطيرة، فقد يوجب البروتوكول المعني التصعيد الفوري قبل اكتمال المقارنة. سجّل الإشارة الخام ونتيجة التحقق معاً. لا تعدّل العدد بصمت بسبب نقص الإبلاغ ما لم تحدد طريقة مبررة وافتراضاتها. هذه قيم تعليمية مصطنعة ولا تصف فاشية حقيقية. وفي مختبر F-108 يكمل الطلاب مصفوفة تحقق تتضمن الأدلة والتفسيرات البديلة والاستعجال والقرار. المرجع: CDC، التحقيق الميداني — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html."}], "objEn": ["List outbreak steps 1–5 in order.", "Verify an outbreak and write a case definition.", "Describe by person, place and time, then form a hypothesis."], "objAr": ["سرد خطوات الفاشية 1–5 بالترتيب.", "التحقق من فاشية وكتابة تعريف حالة.", "الوصف حسب الشخص والمكان والزمان، ثم تكوين فرضية."]}', '[{"qEn": "Step 1 is…", "qAr": "الخطوة 1 هي…", "optsEn": ["Control measures", "Prepare and verify", "Write the final report"], "optsAr": ["تدابير السيطرة", "الاستعداد والتحقق", "كتابة التقرير النهائي"], "ans": 1, "explEn": "Verify first, so you do not chase an artefact.", "explAr": "تحقق أولا، حتى لا تطارد أثرا."}, {"qEn": "45 of 150 guests gives an attack rate of…", "qAr": "45 من 150 ضيفا تعطي معدل هجوم…", "optsEn": ["45%", "15%", "30%"], "optsAr": ["45%", "15%", "30%"], "ans": 2, "explEn": "45 ÷ 150 = 0.30 = 30%.", "explAr": "45 ÷ 150 = 0.30 = 30%."}, {"qEn": "Step 4 is…", "qAr": "الخطوة 4 هي…", "optsEn": ["Form a hypothesis", "Verify the outbreak", "Communicate results"], "optsAr": ["تكوين فرضية", "التحقق من الفاشية", "إيصال النتائج"], "ans": 0, "explEn": "Description leads to a testable hypothesis.", "explAr": "الوصف يقود إلى فرضية قابلة للاختبار."}, {"qEn": "Step 5 tests the hypothesis by…", "qAr": "الخطوة 5 تختبر الفرضية بـ…", "optsEn": ["Writing a press release", "Comparing exposed and unexposed in a 2×2 table", "Closing the investigation"], "optsAr": ["كتابة بيان صحفي", "مقارنة المعرضين وغير المعرضين في جدول 2×2", "إغلاق التحقيق"], "ans": 1, "explEn": "Compare exposed and unexposed groups using a consistent case definition and valid group denominators; urgent control can begin before all analyses are complete.", "explAr": "قارن المعرضين وغير المعرضين بتعريف حالة موحد ومقامات صحيحة؛ ويمكن بدء السيطرة العاجلة قبل اكتمال جميع التحليلات."}]' FROM courses WHERE course_code='B-109';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 2, 'الاستجابة للفاشية: الخطوات 6–10', 'Outbreak response: steps 6–10', '[''سرد خطوات الفاشية 6–10 بالترتيب.'', ''اختيار تدابير سيطرة تناسب المصدر.'', ''كتابة بنية تقرير موقف وخطة تقييم.'']', '[''List outbreak steps 6–10 in order.'', ''Choose control measures that match the source.'', ''Write a SitRep structure and an evaluation plan.'']', 'الخطوات 6–10 تحوّل التحقيق إلى سيطرة وتعلم. الخطوة 6 — تنفيذ السيطرة: إزالة المصدر أو إصلاحه، وحماية المعرضين، وعلاج المرضى. والسيطرة لا تنتظر برهانا كاملا عندما يكون الخطر عاليا — لكن يجب أن تكون متناسبة ومسجلة. الخطوة 7 — التواصل: أخبر الحالات والمخالطين والعاملين الصحيين والجمهور بما هو معروف وما هو غائب وماذا يفعلون. الخطوة 8 — المراقبة والتقييم: أبقِ المنحنى محدثا، وتحقق هل تناقصت الحالات الجديدة، واسأل هل نجحت السيطرة. الخطوة 9 — التقرير: اكتب التحقيق الكامل، بالطرق والنتائج والقيود والتوصيات. الخطوة 10 — الإغلاق والمتابعة: اتفق متى تنتهي الفاشية، وأبقِ الترصد لفترة محددة، واحفظ قائمة الحالات والنتائج المخبرية. والمنحنى الوبائي وقائمة الحالات يبقيان حيّين خلال الخطوات الخمس كلها: بهما تعرف هل السيطرة تعمل. انخفاض الحالات المبلّغ عنها بعد السيطرة لا يثبت وحده أن التدخل سبب الانخفاض. تحقق مما إذا كان تعريف الحالة أو اكتمال الإبلاغ أو الفحص أو السكان المعرضون للخطر أو الموسمية أو التدخلات الأخرى قد تغيرت. واصل المتابعة بطرق قابلة للمقارنة وفترة متابعة محددة.', 'Steps 6–10 turn investigation into control and learning. Step 6 — Implement control: remove or fix the source, protect the exposed, and treat the ill. Control does not wait for perfect proof when the risk is high — but it must be proportionate and recorded. Step 7 — Communicate: tell cases, contacts, health workers and the public what is known, what is missing, and what to do. Step 8 — Monitor and evaluate: keep the curve updated, check whether new cases fall, and ask whether control worked. Step 9 — Report: write the full investigation, with methods, results, limitations and recommendations. Step 10 — Close and follow up: agree when the outbreak is over, keep surveillance for a defined period, and file the line list and laboratory results. The epidemic curve and line list stay live through all five steps: they are how you know whether control is working. A fall in reported cases after control is not, by itself, proof that the intervention caused the decline. Check whether case definitions, reporting completeness, testing, population at risk, seasonality or other interventions changed. Continue monitoring using comparable methods and a defined follow-up period.', '{"exampleEn": "Field case — Dish A is held, preparation is inspected, and remaining food is kept for testing (Step 6). Guests are told what is known, what is still missing, and what symptoms should trigger care (Step 7). The team updates the curve daily (Step 8), writes the investigation report (Step 9), and keeps surveillance for two incubation periods before declaring the outbreak over (Step 10).", "exampleAr": "حالة ميدانية — يُحجز الطبق أ، ويُفحص التحضير، ويُحتفظ بالطعام المتبقي للفحص (الخطوة 6). ويُخبر الضيوف بما هو معروف وما ما زال غائبا وأي أعراض يجب أن تستدعي الرعاية (الخطوة 7). ويحدّث الفريق المنحنى يوميا (الخطوة 8)، ويكتب تقرير التحقيق (الخطوة 9)، ويبقي الترصد لفترتي حضانة قبل إعلان انتهاء الفاشية (الخطوة 10).", "fieldEn": "Control, communicate and monitor in parallel. Do not wait for the final report to tell people what to do.", "fieldAr": "سيطر وتواصل وراقب بالتوازي. لا تنتظر التقرير النهائي لتخبر الناس ماذا يفعلون.", "calcTitleEn": "Worked calculation — did control work?", "calcTitleAr": "حساب محلول — هل نجحت السيطرة؟", "calcStepsEn": ["Step 1 — Reported new cases in the week before control: 24.", "Step 2 — Reported new cases in the week after control: 6.", "Step 3 — Observed relative decline = (24 − 6) ÷ 24 = 75%.", "Step 4 — This is a decline in reported counts, not a causal estimate of intervention effectiveness. Check comparable case finding, reporting, testing and other changes before attributing the decline to control."], "calcStepsAr": ["الخطوة 1 — الحالات الجديدة المبلّغ عنها في الأسبوع السابق للسيطرة: 24.", "الخطوة 2 — الحالات الجديدة المبلّغ عنها في الأسبوع التالي للسيطرة: 6.", "الخطوة 3 — الانخفاض النسبي المرصود = (24 − 6) ÷ 24 = 75%.", "الخطوة 4 — هذا انخفاض في الأعداد المبلّغ عنها، وليس تقديرًا سببيًا لفعالية التدخل. تحقق من قابلية مقارنة اكتشاف الحالات والإبلاغ والفحص والتغيرات الأخرى قبل نسبة الانخفاض إلى السيطرة."], "calcResultEn": "Result: reported counts fell by 75% after control. This is a temporal change, not proof of intervention effect; compare case finding, reporting, testing and other concurrent changes.", "calcResultAr": "النتيجة: انخفضت الأعداد المبلّغ عنها بنسبة 75% بعد السيطرة. وهذا تغير زمني وليس دليلًا على أثر التدخل؛ قارن اكتشاف الحالات والإبلاغ والفحص والتغيرات المتزامنة الأخرى.", "terms": [{"termEn": "Control measures", "termAr": "تدابير السيطرة", "defEn": "Actions that remove the source, protect the exposed and treat the ill.", "defAr": "إجراءات تزيل المصدر وتحمي المعرضين وتعالج المرضى."}, {"termEn": "SitRep", "termAr": "تقرير الموقف", "defEn": "A short, dated situation report: known, missing, next action.", "defAr": "تقرير موقف قصير مؤرخ: معروف وغائب والإجراء التالي."}, {"termEn": "Monitor", "termAr": "المراقبة", "defEn": "Updating the curve and line list to see whether control works.", "defAr": "تحديث المنحنى وقائمة الحالات لمعرفة هل السيطرة تعمل."}, {"termEn": "Close-out", "termAr": "الإغلاق", "defEn": "Agreed end of the outbreak plus follow-up surveillance.", "defAr": "نهاية متفق عليها للفاشية مع ترصد متابعة."}], "deepSections": [{"titleEn": "Find cases systematically and build a usable line list", "titleAr": "ابحث عن الحالات بصورة منهجية وأنشئ قائمة حالات قابلة للاستخدام", "bodyEn": "Case finding should use more than one source when feasible: health-facility registers, laboratory records, community health workers, school or workplace records, referral logs and structured interviews. The sources selected depend on the suspected event and legal authority. Use a standardized form and line list with a unique identifier, case-definition version, demographic details, onset date, symptoms, exposures, location, laboratory status, outcome and follow-up fields appropriate to the event. Do not collect identifiers that are not needed for response. Apply a documented duplicate rule using identifiers and key dates; keep an audit trail rather than deleting records invisibly. Distinguish zero, unknown, not applicable and not yet collected. Train all data collectors on definitions, date formats, interview neutrality, consent or notification requirements and secure handling. Conduct active case finding when routine reporting is likely to miss cases or when the response requires a more complete denominator. Contact tracing is appropriate for diseases and exposures where it can interrupt transmission; it is not automatically useful for every outbreak. Protect confidentiality in transport, storage, team briefings and public reporting. The practical link to F-105 is data quality and bias: broadening case finding can improve sensitivity but different sources may have different ascertainment. Reference: CDC data collection — https://www.cdc.gov/field-epi-manual/php/chapters/collecting-data.html; WHO outbreak stages — https://www.who.int/emergencies/outbreak-toolkit/standardized-data-collection-tools/investigating-outbreak-of-unknown-disease.", "bodyAr": "ينبغي أن يستخدم البحث عن الحالات أكثر من مصدر متى أمكن: سجلات المرافق الصحية وسجلات المختبر والعاملين الصحيين المجتمعيين وسجلات المدارس أو أماكن العمل وسجلات الإحالة والمقابلات المنظمة. وتعتمد المصادر المختارة على الحدث المشتبه به والصلاحيات القانونية. استخدم نموذجاً موحداً وقائمة حالات تتضمن معرفاً فريداً وإصدار تعريف الحالة والبيانات السكانية وتاريخ بدء الأعراض والأعراض والتعرضات والموقع والحالة المخبرية والنتيجة وحقول المتابعة المناسبة للحدث. لا تجمع معرفات لا تحتاجها الاستجابة. طبّق قاعدة موثقة لإزالة التكرار باستخدام المعرفات والتواريخ الأساسية، واحتفظ بمسار تدقيق بدلاً من حذف السجلات دون أثر. ميّز بين الصفر والمجهول وغير المنطبق وما لم يُجمع بعد. درّب جميع جامعي البيانات على التعريفات وصيغ التواريخ وحياد المقابلة ومتطلبات الموافقة أو الإخطار والتعامل الآمن. نفّذ البحث النشط عندما يُحتمل أن يفوّت الإبلاغ الروتيني حالات أو عندما تتطلب الاستجابة مقاماً أكثر اكتمالاً. ويكون تتبع المخالطين مناسباً للأمراض والتعرضات التي يمكن أن يقطع انتقالها؛ لكنه ليس مفيداً تلقائياً في كل فاشية. احمِ السرية أثناء النقل والتخزين وإحاطات الفريق والتقارير العامة. والارتباط العملي بـF-105 هو جودة البيانات والتحيز: قد يحسن توسيع البحث حساسية الكشف، لكن مصادر مختلفة قد تختلف في اكتشاف الحالات. المراجع: CDC، جمع البيانات — https://www.cdc.gov/field-epi-manual/php/chapters/collecting-data.html؛ وWHO، مراحل التحقيق — https://www.who.int/emergencies/outbreak-toolkit/standardized-data-collection-tools/investigating-outbreak-of-unknown-disease."}, {"titleEn": "Describe person, place and time before testing a causal hypothesis", "titleAr": "صِف الشخص والمكان والزمان قبل اختبار فرضية سببية", "bodyEn": "Start with a line-list quality check, then summarize cases by time, place and person. For time, use onset date where possible rather than report date; plot case counts by an interval appropriate to the suspected incubation period and data volume. A sharp single peak may suggest a point-source exposure, successive waves may suggest propagated spread, and a prolonged plateau may suggest a continuous common source, but curve shapes are clues rather than proof. For place, use maps that protect identity and interpret counts alongside population denominators; a neighbourhood with more cases may simply have more residents or better access to testing. For person, describe age, occupation, sex or other relevant characteristics using clear denominators and avoid stigmatizing labels. Calculate attack rates only when the at-risk group can be enumerated. Check missing dates, referral patterns, reporting delays and case-definition changes. Use descriptive patterns to generate hypotheses about source, route and setting; do not present a hypothesis as established fact. In the F-108 exercise, learners should build an epidemic curve and spot map from the supplied training line list, write a three-part description and list at least two alternative explanations. Reference: CDC, Conducting a Field Investigation — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html.", "bodyAr": "ابدأ بفحص جودة قائمة الحالات، ثم لخّص الحالات حسب الزمان والمكان والشخص. بالنسبة للزمان، استخدم تاريخ بدء الأعراض متى أمكن بدلاً من تاريخ الإبلاغ؛ وارسم عدد الحالات حسب فترة تتناسب مع فترة الحضانة المشتبه بها وحجم البيانات. قد توحي القمة الحادة الواحدة بتعرض لمصدر نقطي، وقد توحي الموجات المتعاقبة بانتقال متسلسل، وقد يوحي الثبات المطول بمصدر مشترك مستمر، لكن أشكال المنحنى قرائن وليست إثباتاً. وبالنسبة للمكان، استخدم خرائط تحمي الهوية وفسّر الأعداد مع مقامات السكان؛ فقد يكون الحي ذو الحالات الأكثر أكبر سكاناً أو أفضل وصولاً للفحص. وبالنسبة للشخص، صف العمر والمهنة والجنس أو الخصائص ذات الصلة بمقامات واضحة وتجنب الأوصاف الوصمية. لا تحسب معدل هجوم إلا إذا أمكن حصر المجموعة المعرضة للخطر. افحص التواريخ المفقودة وأنماط الإحالة وتأخر الإبلاغ وتغير تعريف الحالة. استخدم الأنماط الوصفية لتوليد فرضيات عن المصدر والطريق والبيئة، ولا تقدم الفرضية كحقيقة مثبتة. وفي تمرين F-108 يبني الطلاب منحنى وبائياً وخريطة نقاط من قائمة التدريب المعطاة، ويكتبون وصفاً ثلاثياً ويذكرون تفسيرين بديلين على الأقل. المرجع: CDC، إجراء تحقيق ميداني — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html."}, {"titleEn": "Test an exposure hypothesis with the design that fits the event", "titleAr": "اختبر فرضية التعرض بالتصميم الملائم للحدث", "bodyEn": "After descriptive analysis, state a testable hypothesis with exposure, outcome, population and time window. In an enumerated cohort, such as guests at a meal, compare attack rates among exposed and unexposed people. In a case-control investigation, select controls from the population that produced the cases and compare exposure odds; do not calculate risks from outcome-based sampling fractions. Consider confounding, selection bias, recall bias, exposure misclassification and missing data. Use the existing F-108 wedding training dataset. Among guests who ate Dish A, 18/30 became ill, an attack proportion of 60%. Among guests who did not eat Dish A, 27/120 became ill, an attack proportion of 22.5%. The attack-rate ratio is 0.60/0.225 = 2.6667 (about 2.67), and the risk difference is 0.60 − 0.225 = 0.375, or 37.5 percentage points. The overall guest-cohort attack proportion is 45/150 = 30%. These are synthetic course data; the association supports prioritizing the food hypothesis for investigation but does not by itself prove causation. Verify the food history, timing, alternative menu items, dose and plausible incubation period; consider whether ill people were more likely to recall the exposure. Report both group denominators and the uncertainty around estimates where appropriate. Do not delay urgent control measures if the exposure is plausible and the potential harm is serious. These are invented instructional numbers, not outbreak data. Reference: CDC field investigation — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html; CDC outbreak analysis — https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html.", "bodyAr": "بعد التحليل الوصفي، صغ فرضية قابلة للاختبار تتضمن التعرض والنتيجة والسكان والفترة الزمنية. في مجموعة أترابية محصورة، مثل ضيوف وجبة، قارن معدلات الهجوم بين من تعرضوا ومن لم يتعرضوا. وفي تحقيق الحالات والشواهد، اختر الشواهد من المجتمع الذي نشأت منه الحالات وقارن أرجحية التعرض؛ ولا تحسب المخاطر من نسب المعاينة المحددة بحسب النتيجة. ضع في الحسبان الإرباك وتحيز الاختيار وتحيز التذكر وسوء تصنيف التعرض والبيانات المفقودة. استخدم مجموعة بيانات التدريب الحالية لفاشية الزفاف في F-108. مرض 18/30 من الضيوف الذين تناولوا الطبق A، أي نسبة هجوم 60%. ومرض 27/120 ممن لم يتناولوه، أي نسبة هجوم 22.5%. نسبة معدلي الهجوم هي 0.60/0.225 = 2.6667 (نحو 2.67)، وفرق الخطر 0.60 − 0.225 = 0.375، أي 37.5 نقطة مئوية. أما نسبة الهجوم الإجمالية بين الضيوف فهي 45/150 = 30%. هذه بيانات تدريبية اصطناعية؛ والارتباط يدعم إعطاء فرضية الطعام أولوية في التقصي، لكنه لا يثبت السببية بمفرده. تحقق من تاريخ الطعام والتوقيت والأصناف البديلة والكمية وفترة الحضانة المعقولة؛ وافحص هل كان المرضى أكثر ميلاً لتذكر التعرض. أبلغ عن مقامي المجموعتين وعن عدم اليقين حول التقديرات عند الاقتضاء. لا تؤخر تدابير السيطرة العاجلة إذا كان التعرض معقولاً والضرر المحتمل جسيماً. هذه أرقام تعليمية مخترعة وليست بيانات فاشية. المراجع: CDC، التحقيق الميداني — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html؛ وCDC، تحليل وتفسير البيانات — https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html."}], "objEn": ["List outbreak steps 6–10 in order.", "Choose control measures that match the source.", "Write a SitRep structure and an evaluation plan."], "objAr": ["سرد خطوات الفاشية 6–10 بالترتيب.", "اختيار تدابير سيطرة تناسب المصدر.", "كتابة بنية تقرير موقف وخطة تقييم."]}', '[{"qEn": "Step 6 is…", "qAr": "الخطوة 6 هي…", "optsEn": ["Write the case definition", "Verify the outbreak", "Implement control"], "optsAr": ["كتابة تعريف الحالة", "التحقق من الفاشية", "تنفيذ السيطرة"], "ans": 2, "explEn": "Control may begin when risk warrants action; investigation steps can overlap and are not a rigid sequence.", "explAr": "يمكن بدء السيطرة عندما يستدعي الخطر ذلك؛ وقد تتداخل خطوات التحقيق وليست ترتيبًا جامدًا."}, {"qEn": "24 cases falling to 6 is a fall of…", "qAr": "هبوط الحالات من 24 إلى 6 هو هبوط…", "optsEn": ["75%", "25%", "18%"], "optsAr": ["75%", "25%", "18%"], "ans": 0, "explEn": "The observed decline is 75%, but it does not prove the intervention caused it.", "explAr": "الانخفاض المرصود 75%، لكنه لا يثبت أن التدخل هو سببه."}, {"qEn": "A SitRep should contain…", "qAr": "تقرير الموقف يجب أن يحتوي…", "optsEn": ["Only rumours", "What is known, what is missing, next action", "Only the final conclusion"], "optsAr": ["الشائعات فقط", "ما هو معروف وما هو غائب والإجراء التالي", "الاستنتاج النهائي فقط"], "ans": 1, "explEn": "A SitRep is a short, dated, honest update.", "explAr": "تقرير الموقف تحديث قصير مؤرخ صادق."}, {"qEn": "Before closing, you should…", "qAr": "قبل الإغلاق، يجب أن…", "optsEn": ["Delete the line list", "Stop all communication", "Keep surveillance for a defined period"], "optsAr": ["تحذف قائمة الحالات", "توقف كل التواصل", "تبقي الترصد لفترة محددة"], "ans": 2, "explEn": "Close-out needs follow-up surveillance and filing.", "explAr": "الإغلاق يحتاج ترصد متابعة وحفظا."}]' FROM courses WHERE course_code='B-109';
INSERT INTO lectures (course_id, lecture_no, title_ar, title_en, objectives_ar, objectives_en, body_ar, body_en, payload, quiz_json) SELECT id, 3, 'تمرين ميداني كامل: فاشية زفاف', 'Full field exercise: a wedding outbreak', '[''تشغيل الخطوات 1–10 على سيناريو فاشية واحد.'', ''حساب معدل الهجوم والإيجابية والخطر النسبي من نفس السيناريو.'', ''كتابة تقرير موقف بمعروف وغائب وإجراء تالي.'']', '[''Run steps 1–10 on one outbreak scenario.'', ''Calculate attack rate, positivity and RR from the same scenario.'', ''Write a SitRep with known, missing and next action.'']', 'طبّق الآن إطار التحقيق على مجموعة محددة من ضيوف الزفاف. السيناريو: حُصر 150 ضيفًا، وجُمعت حالة المرض والتعرض للطبق أ للفترة نفسها من الفاشية. تعريف الحالة العملي هو ضيف الزفاف الذي أصيب بثلاث مرات أو أكثر من البراز الرخو خلال 24 ساعة وبدأت أعراضه بين 1 و6 يونيو؛ ولا يُدرج المخالطون الأسريون في بسط أو مقام مجموعة الضيوف. توجد 45 حالة محتملة بين 150 ضيفًا. فُحصت 20 عينة براز وكانت 14 إيجابية: إيجابية العينات = 14/20 = 70% (فترة ويلسون 95% نحو 48%–85%)؛ وهذا يصف العينات المفحوصة ولا يمثل تلقائيًا انتشار المرض بين جميع الضيوف أو حساسية الاختبار. أكل الطبق أ 30 ضيفًا، مرض 18 منهم؛ ولم يأكله 120، مرض 27 منهم. الخطران هما 18/30 = 60% و27/120 = 22.5%؛ والخطر النسبي = 2.67. نسبة الهجوم المرصودة إجمالًا = 45/150 = 30%. يفترض جدول 2×2 أن حالة التعرض والمرض معروفتان لجميع الضيوف الـ150 بالتعريفات نفسها. ولا تزال نتيجة فحص الطعام والتحقيق الكامل في المصدر قيد الانتظار. ينفذ الفريق تدابير سيطرة متناسبة، ويفحص التحضير، ويحفظ العينات المناسبة، ويحدث المنحنى، ويسجل المعروف وما بقي غير مؤكد والإجراء التالي مع مسؤول وموعد.', 'Now apply the framework to a defined guest cohort. Scenario: 150 wedding guests are enumerated and their illness status and Dish A exposure are ascertained for the same outbreak period. The working case definition is a wedding guest with 3 or more loose stools in 24 hours and onset from 1–6 June; household contacts are not included in this guest-cohort numerator or denominator. There are 45 probable cases among the 150 guests. Twenty stool specimens are tested and 14 are positive: specimen positivity is 14/20 = 70% (Wilson 95% CI about 48%–85%); this describes the tested specimens and is not automatically prevalence among all guests or test sensitivity. Dish A was eaten by 30 guests, 18 ill; 120 did not eat it, 27 ill. Risks are 18/30 = 60% and 27/120 = 22.5%; RR = 2.67. The overall observed attack proportion is 45/150 = 30%. The 2×2 table assumes exposure and illness status are ascertained for all 150 guests using the same definitions. The food laboratory result and full source investigation remain pending. The team applies proportionate controls, inspects preparation, retains appropriate specimens, updates the curve, and records what is known, what remains uncertain, and the next action with an owner and date.', '{"exampleEn": "Field decision — The RR of 2.67 makes Dish A a priority hypothesis, not a proven cause. Check food handling, timing, other shared dishes, and possible confounding; keep control proportionate while the food specimen result and source investigation are pending.", "exampleAr": "قرار ميداني — يجعل الخطر النسبي 2.67 الطبق أ فرضية ذات أولوية، لا سببًا مثبتًا. تحقق من تداول الطعام والتوقيت والأطباق المشتركة الأخرى والإرباك المحتمل؛ واستمر في السيطرة المتناسبة إلى حين ظهور نتيجة عينة الطعام واستكمال التحقيق في المصدر.", "fieldEn": "Close every outbreak day with a SitRep: known, missing, next action, owner, date. Reference basis: CDC Field Epidemiology Manual, outbreak investigation; CDC Quick-Learn on epi curves; interpret food-specific attack rates alongside exposure histories and potential confounding.", "fieldAr": "أغلق كل يوم فاشية بتقرير موقف: معروف وغائب وإجراء تالي ومالك وتاريخ. مرجع المراجعة: دليل CDC الميداني للتحقيق في الفاشيات؛ ودرس CDC للمنحنيات الوبائية؛ ويجب تفسير نسب الهجوم الخاصة بالأطعمة مع تاريخ التعرض والإرباك المحتمل.", "calcTitleEn": "Worked calculation — the whole scenario in four numbers", "calcTitleAr": "حساب محلول — السيناريو كله في أربعة أرقام", "calcStepsEn": ["Step 1 — Guest-cohort attack proportion = 45 probable cases ÷ 150 enumerated guests = 30%; case definition and period apply to the same guest cohort.", "Step 2 — Specimen positivity = 14 positive ÷ 20 tested = 70%; Wilson 95% CI ≈ 48%–85%. This is positivity among tested specimens only.", "Step 3 — Dish A eaters: 18 ÷ 30 = 60%. Non-eaters: 27 ÷ 120 = 22.5%.", "Step 4 — RR = 0.60 ÷ 0.225 = 2.67. Interpret as an observed association in this cohort, not proof of causation; assess confounding, recall and selection, and verify exposure and outcome completeness."], "calcStepsAr": ["الخطوة 1 — نسبة الهجوم في مجموعة الضيوف = 45 حالة محتملة ÷ 150 ضيفًا محصورًا = 30%؛ وينطبق تعريف الحالة والفترة على مجموعة الضيوف نفسها.", "الخطوة 2 — إيجابية العينات = 14 إيجابية ÷ 20 مفحوصة = 70%؛ فترة ويلسون 95% نحو 48%–85%. وهذه إيجابية العينات المفحوصة فقط.", "الخطوة 3 — آكلو الطبق أ: 18 ÷ 30 = 60%. غير الآكلين: 27 ÷ 120 = 22.5%.", "الخطوة 4 — الخطر النسبي = 0.60 ÷ 0.225 = 2.67. فسّره بوصفه ارتباطًا مرصودًا في هذه المجموعة لا دليلًا على السببية؛ وقيّم الإرباك والتذكر والاختيار، وتحقق من اكتمال بيانات التعرض والنتيجة."], "calcResultEn": "Result: guest-cohort attack proportion 30%; specimen positivity 70% (Wilson 95% CI about 48%–85%); Dish A RR 2.67. The association prioritizes a hypothesis but does not prove causation. Food testing and source investigation remain open.", "calcResultAr": "النتيجة: نسبة الهجوم في مجموعة الضيوف 30%؛ وإيجابية العينات 70% (فترة ويلسون 95% نحو 48%–85%)؛ والخطر النسبي للطبق أ 2.67. يعطي الارتباط أولوية لفرضية لكنه لا يثبت السببية. ولا يزال فحص الطعام والتحقيق في المصدر مفتوحين.", "terms": [{"termEn": "Probable case", "termAr": "الحالة المحتملة", "defEn": "Fits the clinical picture plus an epidemiological link, without lab confirmation.", "defAr": "تنطبق عليها الصورة السريرية مع ارتباط وبائي، من دون تأكيد مخبري."}, {"termEn": "Attack rate", "termAr": "معدل الهجوم", "defEn": "Cases divided by people at risk during the outbreak.", "defAr": "الحالات مقسومة على المعرضين للخطر خلال الفاشية."}, {"termEn": "Positivity", "termAr": "الإيجابية", "defEn": "Positive tests divided by tests done.", "defAr": "الفحوص الإيجابية مقسومة على الفحوص المجراة."}, {"termEn": "SitRep", "termAr": "تقرير الموقف", "defEn": "Short, dated update: known, missing, next action.", "defAr": "تحديث قصير مؤرخ: معروف وغائب والإجراء التالي."}], "deepSections": [{"titleEn": "Implement proportionate control measures while the investigation continues", "titleAr": "نفّذ تدابير سيطرة متناسبة بينما يستمر التحقيق", "bodyEn": "Control measures should target the likely source, route of transmission and susceptible host, while reflecting the disease, setting, severity, feasibility and community context. Depending on evidence, measures may include safe water and sanitation, food-handling controls, infection prevention in healthcare facilities, isolation or cohorting when indicated, vaccination or prophylaxis under protocol, vector control, environmental remediation, risk communication and clinical referral. Match the measure to the transmission pathway; an intervention that does not address the route may consume resources without reducing risk. Implement urgent, low-regret actions when potential harm is high, but document the evidence, rationale, expected benefit, possible harms and review date. Do not wait for every hypothesis test if delay could lead to preventable illness; equally, do not impose restrictive measures without legal authority, proportionality and safeguards. Engage affected communities in selecting feasible actions and monitor unintended consequences such as barriers to care, stigma, income loss or misinformation. The CDC and WHO describe investigation steps as overlapping and permit early control measures when warranted. In the F-108 lab, learners should map each proposed intervention to a transmission link and specify an indicator that would show whether it is working. Reference: CDC field investigation — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html; WHO outbreak stages — https://www.who.int/emergencies/outbreak-toolkit/standardized-data-collection-tools/investigating-outbreak-of-unknown-disease.", "bodyAr": "ينبغي أن تستهدف تدابير السيطرة المصدر المحتمل وطريق الانتقال والعائل القابل للإصابة، مع مراعاة المرض والبيئة والشدة والجدوى وسياق المجتمع. وقد تشمل التدابير، حسب الأدلة، سلامة المياه والصرف الصحي وضوابط تداول الغذاء والوقاية من العدوى في المرافق الصحية والعزل أو التجميع عند الحاجة والتطعيم أو الوقاية الدوائية وفق البروتوكول ومكافحة النواقل والمعالجة البيئية والتواصل بشأن المخاطر والإحالة السريرية. طابق التدبير مع طريق الانتقال؛ فالتدخل الذي لا يعالج الطريق قد يستهلك الموارد دون خفض الخطر. نفّذ الإجراءات العاجلة منخفضة الضرر عندما يكون الضرر المحتمل كبيراً، لكن وثّق الأدلة والمبرر والمنفعة المتوقعة والأضرار المحتملة وموعد المراجعة. لا تنتظر كل اختبارات الفرضية إذا كان التأخير قد يؤدي إلى مرض يمكن منعه؛ وبالمثل لا تفرض تدابير تقييدية دون صلاحية قانونية وتناسب وضمانات. أشرك المجتمعات المتأثرة في اختيار إجراءات قابلة للتنفيذ، وراقب العواقب غير المقصودة مثل عوائق الرعاية والوصم وفقدان الدخل والمعلومات المضللة. يوضح CDC وWHO أن خطوات التحقيق قد تتداخل وأن السيطرة المبكرة جائزة عند وجود ما يبررها. وفي مختبر F-108 يربط الطلاب كل تدخل مقترح بحلقة من سلسلة الانتقال ويحددون مؤشراً يبين فعاليته. المراجع: CDC، التحقيق الميداني — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html؛ وWHO، مراحل التحقيق — https://www.who.int/emergencies/outbreak-toolkit/standardized-data-collection-tools/investigating-outbreak-of-unknown-disease."}, {"titleEn": "Coordinate the response and communicate risk with transparency", "titleAr": "نسّق الاستجابة وتواصل بشأن المخاطر بشفافية", "bodyEn": "An outbreak response requires clear coordination across surveillance, clinical services, laboratories, environmental health, water and sanitation, animal health when relevant, local authorities, logistics and community representatives. Establish an incident lead, technical focal points, a reporting rhythm, a decision log and a route for urgent escalation. Define who can authorize public messages and protective measures. Risk communication should be timely, accurate, actionable, empathetic and updated as evidence changes. State what is known, what is not known, what people can do now, where to seek care and when the next update will occur. Avoid premature claims about a source or blame of a group; disclose uncertainty without creating unnecessary alarm. Listen to rumours and community concerns as potential signals about access, acceptability or new exposures. Protect case identities and avoid maps or small-cell tables that enable re-identification. Provide messages in the languages and formats people can use, including accessible channels for people with disabilities or limited connectivity. In the assessment, students should draft a 150-word public update and a one-page internal situation report that distinguish confirmed findings from hypotheses. Reference: WHO outbreak communication resources — https://www.who.int/emergencies/risk-communications; CDC field investigation — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html.", "bodyAr": "تتطلب الاستجابة للفاشية تنسيقاً واضحاً بين الترصد والخدمات السريرية والمختبرات والصحة البيئية والمياه والصرف الصحي وصحة الحيوان عند الصلة والسلطات المحلية واللوجستيات وممثلي المجتمع. عيّن قائد الحادث ونقاط الاتصال الفنية وإيقاع الإبلاغ وسجل القرارات ومسار التصعيد العاجل. حدد من يملك اعتماد الرسائل العامة والتدابير الوقائية. يجب أن يكون التواصل بشأن المخاطر في الوقت المناسب ودقيقاً وقابلاً للتطبيق ومتعاطفاً ومحدثاً مع تغير الأدلة. اذكر ما هو معلوم وما هو غير معلوم وما الذي يستطيع الناس فعله الآن وأين يطلبون الرعاية وموعد التحديث التالي. تجنب الادعاءات المبكرة عن مصدر أو لوم فئة؛ وأفصح عن عدم اليقين دون إثارة ذعر غير ضروري. استمع إلى الشائعات ومخاوف المجتمع بوصفها إشارات محتملة عن الوصول أو المقبولية أو تعرضات جديدة. احمِ هويات الحالات وتجنب الخرائط أو الجداول ذات الخلايا الصغيرة التي تسمح بإعادة التعرف. قدم الرسائل باللغات والصيغ التي يستطيع الناس استخدامها، بما فيها قنوات ميسرة لذوي الإعاقة أو محدودي الاتصال. وفي التقييم، يكتب الطلاب تحديثاً عاماً من 150 كلمة وتقرير موقف داخلياً من صفحة واحدة يميزان النتائج المؤكدة عن الفرضيات. المراجع: موارد WHO للتواصل بشأن المخاطر — https://www.who.int/emergencies/risk-communications؛ وCDC، التحقيق الميداني — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html."}, {"titleEn": "Evaluate control, maintain surveillance and close the response responsibly", "titleAr": "قيّم السيطرة واستمر في الترصد وأغلق الاستجابة بمسؤولية", "bodyEn": "Response evaluation asks whether the event is controlled, whether the intervention was delivered as intended, and whether harms or gaps remain. Track epidemiologic outcomes (new cases, severe cases, deaths, attack rates where valid), process indicators (time from alert to verification, time to first control action, proportion of facilities reporting) and balancing indicators (care access, stock-outs, adverse effects, community trust). Use consistent case definitions and onset dates; apparent declines can be caused by reporting interruption or reduced testing. Continue surveillance for an appropriate period after the last case according to the disease-specific incubation, transmission and national guidance; there is no universal number of days. Update the line list, document case-definition versions, reconcile laboratory and field records, and maintain a decision/action log. Communicate preliminary findings rapidly and produce a final report with methods, results, limitations, control actions and recommendations. Hold a structured after-action review: what worked, what failed, why, and who owns each corrective action by what date? Preserve data securely and de-identify teaching or public outputs. The bridge back to F-107 is explicit: response-generated information should improve routine thresholds, reporting pathways and preparedness. In the F-108 capstone, students submit a response timeline, control-evaluation dashboard, public update and after-action matrix. Reference: CDC field investigation — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html; WHO EWAR — https://www.who.int/publications/i/item/9789240063587.", "bodyAr": "يسأل تقييم الاستجابة هل تمت السيطرة على الحدث، وهل نُفذ التدخل كما خُطط، وهل بقيت أضرار أو فجوات. تتبع النتائج الوبائية (الحالات الجديدة والحالات الشديدة والوفيات ومعدلات الهجوم حيث تصح)، ومؤشرات العملية (الزمن من التنبيه إلى التحقق، والزمن حتى أول إجراء سيطرة، ونسبة المرافق المبلغة)، والمؤشرات الموازنة (الوصول إلى الرعاية ونفاد المخزون والآثار الضارة وثقة المجتمع). استخدم تعريفات حالة وتواريخ بدء أعراض متسقة؛ فقد ينتج الانخفاض الظاهري عن انقطاع الإبلاغ أو انخفاض الفحص. استمر في الترصد مدة مناسبة بعد آخر حالة وفق فترة الحضانة والانتقال والإرشادات الوطنية الخاصة بالمرض؛ فلا توجد مدة عالمية واحدة. حدّث قائمة الحالات، ووثق إصدارات تعريف الحالة، وطابق سجلات المختبر والميدان، واحتفظ بسجل القرارات والإجراءات. أبلغ النتائج الأولية سريعاً وأصدر تقريراً نهائياً يتضمن المنهجية والنتائج والقيود وإجراءات السيطرة والتوصيات. نفّذ مراجعة منظمة بعد الإجراء: ما الذي نجح؟ وما الذي فشل؟ ولماذا؟ ومن المسؤول عن كل إجراء تصحيحي وبأي موعد؟ احفظ البيانات بأمان وأزل الهوية من المخرجات التعليمية أو العامة. والربط العائد إلى F-107 واضح: ينبغي للمعلومات الناتجة عن الاستجابة أن تحسن عتبات الترصد ومسارات الإبلاغ والاستعداد. وفي المشروع الختامي لـF-108 يقدم الطلاب خطاً زمنياً للاستجابة ولوحة لتقييم السيطرة وتحديثاً عاماً ومصفوفة مراجعة بعد الإجراء. المراجع: CDC، التحقيق الميداني — https://www.cdc.gov/field-epi-manual/php/chapters/field-investigation.html؛ وWHO EWAR — https://www.who.int/publications/i/item/9789240063587."}], "objEn": ["Run steps 1–10 on one outbreak scenario.", "Calculate attack rate, positivity and RR from the same scenario.", "Write a SitRep with known, missing and next action."], "objAr": ["تشغيل الخطوات 1–10 على سيناريو فاشية واحد.", "حساب معدل الهجوم والإيجابية والخطر النسبي من نفس السيناريو.", "كتابة تقرير موقف بمعروف وغائب وإجراء تالي."]}', '[{"qEn": "Attack rate for 45 of 150 is…", "qAr": "معدل الهجوم لـ 45 من 150 هو…", "optsEn": ["30%", "45%", "70%"], "optsAr": ["30%", "45%", "70%"], "ans": 0, "explEn": "45/150 = 30% for the defined guest cohort and outbreak period; household contacts are not included in this numerator.", "explAr": "45/150 = 30% لمجموعة الضيوف والفترة المحددتين؛ ولا يُدرج المخالطون الأسريون في هذا البسط."}, {"qEn": "Positivity for 14 of 20 is…", "qAr": "الإيجابية لـ 14 من 20 هي…", "optsEn": ["30%", "70%", "48%"], "optsAr": ["30%", "70%", "48%"], "ans": 1, "explEn": "14/20 = 70% positivity among specimens tested; it is not automatically prevalence in all guests.", "explAr": "14/20 = 70% إيجابية بين العينات المفحوصة؛ وليست تلقائيًا انتشارًا بين جميع الضيوف."}, {"qEn": "RR for Dish A (60% vs 22.5%) is…", "qAr": "الخطر النسبي للطبق أ (60% مقابل 22.5%) هو…", "optsEn": ["1.4", "5.17", "2.67"], "optsAr": ["1.4", "5.17", "2.67"], "ans": 2, "explEn": "60% ÷ 22.5% = 2.67. This is an observed cohort association, not proof of causation.", "explAr": "60% ÷ 22.5% = 2.67. وهذا ارتباط مرصود في مجموعة أترابية وليس إثباتًا للسببية."}, {"qEn": "A good SitRep ends with…", "qAr": "تقرير الموقف الجيد ينتهي بـ…", "optsEn": ["Next action with owner and date", "A vague wish", "No mention of missing data"], "optsAr": ["إجراء تالي بمالك وتاريخ", "أمنية غامضة", "لا ذكر للبيانات الغائبة"], "ans": 0, "explEn": "Owned, dated actions make a SitRep useful.", "explAr": "الإجراءات بمالك وتاريخ تجعل تقرير الموقف مفيدا."}]' FROM courses WHERE course_code='B-109';
